INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C1','soc',4,2,'u1',1,'민주주의의 의미 — 민주주의는 구성원들의 다양한 의견을 반영하여 사회 공동의 문제에 관한 의사 결정을 하는 방식 · 민주주의 사회에서는 구성원 모두가 존중받고 평등한 입장에서 의견을 말하고 자유롭게 행동할 수 있음 · 몇몇 사람의 뜻대로 정하면 여러 사람의 의견을 반영할 수 없고 일부에게만 유리한 선택을 할 수 있음 · 학교에 건의함을 두는 까닭, 학생 자치회 임원 선거(공약을 듣고 투표) · 가정(가족회의)·학교(학급 회의)·지역(주민 회의)·국가에서 실천',ARRAY['[4사08-01] 민주주의의 의미와 중요성을 파악하고, 학교생활에서 민주주의를 실천하는 태도를 기른다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C2','soc',4,2,'u1',2,'민주주의를 실천하는 태도 — 공동의 문제를 민주적으로 해결하려면 충분한 대화가 필요 · 상대방의 의견을 존중하고 서로 배려하며 양보하고 타협 · 상대방 의견의 옳고 그름과 장단점을 생각하며 해결 방안을 찾음 · 함께 결정한 해결 방안은 구성원 모두가 적극적으로 실천 · 내 의견만 강하게 주장하거나 자기 생각과 다르다고 다른 의견을 무시하면 안 됨 · 반대의 까닭을 받아들여 처음 의견을 고쳐 다시 낼 수 있음 · 여론 조사 전문가(여론 = 많은 사람이 가지고 있는 생각이나 의견)',ARRAY['[4사08-01] 민주주의의 의미와 중요성을 파악하고, 학교생활에서 민주주의를 실천하는 태도를 기른다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C3','soc',4,2,'u1',3,'학교생활 속 민주주의 실천 사례 — 학교에서는 더 나은 학교를 만들려고 구성원들이 민주주의를 실천함 · 학생들은 대표를 뽑아 학생 자치회를 구성하고, 학생 자치회는 학생들의 의견을 학교에 전달하고 학교의 일을 민주적으로 해결하려고 노력함 · 학생·교사·학부모는 학교 구성원으로서 학교의 일을 함께 의논하며 해결 · 학생 참여 예산제 = 학생들이 제안한 사업을 실현하도록 예산을 지원하고 학생들이 스스로 기획·운영하는 제도(예산 = 어떤 일에 필요한 돈을 미리 계획함) · 사례마다 한 일은 달라도 의견 모으기 → 회의로 정하기 → 함께 실천하기는 같음(3월 행사, 학교 구성원 전체 회의, 우산 빗물 제거기)',ARRAY['[4사08-01] 민주주의의 의미와 중요성을 파악하고, 학교생활에서 민주주의를 실천하는 태도를 기른다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C4','soc',4,2,'u1',4,'학교에서 민주주의를 실천하는 과정 — 해결하고 싶은 일 확인하기 → 해결 방안 탐색하기 → 민주적인 방법으로 해결 방안 결정하기 → 해결 방안 실천하기 → 실천 결과 확인하기 · 놀이터 사례(오래되어 불편하고 위험한 놀이기구, 움푹 파인 모래 바닥) → 안전한 놀이기구·넘어져도 다치지 않는 바닥·이용 규칙 · 놀이기구와 바닥은 설문조사, 이용 규칙은 학급 회의 → 학생·교사·학부모 회의 · 방안 찾을 때 원인·장단점·많은 구성원의 만족을 생각 · 결과 확인 때 전과 후 비교, 구성원 생각 확인, 아쉬운 점 보완 · 학교 이름 바꾸기(공약, 편지와 서명 운동, 민주적인 절차)',ARRAY['[4사08-01] 민주주의의 의미와 중요성을 파악하고, 학교생활에서 민주주의를 실천하는 태도를 기른다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C5','soc',4,2,'u1',5,'학교생활 속 민주주의 정리 — 민주주의의 의미·실천 모습·태도·사례·과정 되짚기 · 학생 자치회 월별 행사 계획: 3~4월 사이좋은 친구 사이 만들기(우정 표어 공모전·바른 말 사용 캠페인), 5~6월 깨끗한 학교 만들기(분리수거 도우미·학교 공간 꾸미기 공모전), 7~8월 안전한 학교 만들기(등하교 안전 도우미·시설 안전 이용 규칙) · 행사의 내용뿐 아니라 행사로 얻을 수 있는 결과를 생각 · 임원의 태도: 민주적으로 의사소통, 적극적으로 참여, 학생들의 생각을 최대한 반영 · 민주주의는 자유와 평등을 지켜 주고, 모두가 평등한 입장에서 함께 만들어 감',ARRAY['[4사08-01] 민주주의의 의미와 중요성을 파악하고, 학교생활에서 민주주의를 실천하는 태도를 기른다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C6','soc',4,2,'u1',6,'주민 자치의 의미 — 주민 자치는 주민이 지역의 주인으로서 지역의 일에 참여하여 함께 문제를 해결해 나가는 것 · 주민 자치회는 지역 주민을 대표하는 기구로 주민 자치 활동을 운영하고 지원함 · 학교에 학생 자치회가 있다면 지역에는 주민 자치회가 있음(구성원이면 누구나 참여, 더 나은 사회를 위해 함께 노력) · 어두운 골목길을 밝히는 사업(안전하게 다니고 밤 풍경이 아름다워짐) · 일부 사람만 모여 정하면 많은 사람의 입장을 고려하지 못함 · 주민 회의, 예산을 세우는 일에 참여, 지역 역사·문화 축제, 도움이 필요한 사람 돕기 · 주민이 적극적으로 참여할 때 지역에서 민주주의를 실천',ARRAY['[4사08-02] 주민 자치의 의미를 알고, 지역 문제 해결에 참여하는 주민 자치의 사례를 탐구한다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C7','soc',4,2,'u1',7,'주민 참여가 중요한 까닭 — 지역에서 일어나는 일들은 주민들의 생활에 많은 영향을 미침 · 지역 주민이 지역을 잘 알기 때문에 직접 참여하는 것이 중요 · 혼자 생활하는 노인에게 돌봄 로봇 지원, 아이를 함께 보살핌 · 「온 마을이 학교다」(친구야 소풍 가자, 세대 공감 마을 지도) — 세대가 소통, 주민과 지역이 함께 성장 · 참여가 활발하면 불편한 문제를 직접 해결하고 원하는 방향으로 지역이 달라짐, 지역의 일을 민주적으로 해결하고 더 살기 좋은 지역으로 발전 · 활발하지 않으면 문제 해결과 발전이 어려워짐 · 관광 두레(숙박·먹거리·여행 체험으로 지역 특색)',ARRAY['[4사08-02] 주민 자치의 의미를 알고, 지역 문제 해결에 참여하는 주민 자치의 사례를 탐구한다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C8','soc',4,2,'u1',8,'주민 참여의 방법 — 일상생활과 관련 있는 지역의 일에 직접 참여하거나 의견을 다른 주민이나 공공 기관에 전달 · 축제 자원봉사, 소식지, 공공 기관 누리집 게시판, 청소, 벽화, 등하교 안전 지킴이, 주민 회의, 주민 투표, 서명 운동, 공청회, 시민 단체 · 참여가 없으면 주민이 원하는 방향과 상관없이 결정됨 · 적극적으로, 나의 이익만이 아니라 지역 전체의 이익을 생각 · 더 나은 지역, 구성원으로서 만족감 · 작은 일에서부터 · 주민 투표로 사업 결정(곳곳의 투표판·사회 관계망 서비스)',ARRAY['[4사08-02] 주민 자치의 의미를 알고, 지역 문제 해결에 참여하는 주민 자치의 사례를 탐구한다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C9','soc',4,2,'u1',9,'우리 지역의 주민 자치 사례 조사 — 주민 자치는 지역마다 다양한 모습 · 조사 방법: 인터넷으로 찾아보기, 지역 신문 찾아보기, 지역 주민 면담하기, 지역 게시판 찾아보기, 공공 기관 방문하기 · 방문 전 미리 연락해 허락받기, 보호자와 함께, 공공질서 지키기 · 조사 계획서(주제·목적·사람과 역할·방법·내용·주의할 점) · 조사 보고서(목적·날짜·사람·방법·모습·내용·알게 된 점·더 알고 싶은 점) — 조사하기 전·조사하는 날·조사를 마친 뒤 쓰는 칸이 다름 · 발표는 주민 자치로 더 나아진 점 중심 · 생활 실험실(주민이 공공 기관·전문가와 손잡고 생활 속 불편을 직접 해결)',ARRAY['[4사08-02] 주민 자치의 의미를 알고, 지역 문제 해결에 참여하는 주민 자치의 사례를 탐구한다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u1-C10','soc',4,2,'u1',10,'주민 자치에 참여하기 — 지역 주민들이 중심이 되어 관심을 기울이고 노력하면 더 나은 지역 · 주민의 힘만으로 어려운 문제는 공공 기관에 도움을 청할 수 있음 · 참여 과정: 필요한 일 찾기(통학로) → 참여 방법 찾기(누리집 게시판, 캠페인 문구, 회의로 협의) → 계획을 세워 실천하기(캠페인, 곳곳을 예쁘게, 벽화) → 달라진 점 쓰기(더 안전하게, 주민들의 관심) → 돌아보며 평가하기 · 참여하기 전과 후를 견주어 봄 · 어린이도 친구들과 함께 참여할 수 있음',ARRAY['[4사08-02] 주민 자치의 의미를 알고, 지역 문제 해결에 참여하는 주민 자치의 사례를 탐구한다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X01','soc',4,'u1',ARRAY['SO4-2-u1-C1']::text[],'민주주의의 뜻을 잘못 안다(한 사람이나 몇몇이 정하는 것, 빨리 정하는 것으로 여기는 등)','다양한 의견을 반영해 함께 결정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X02','soc',4,'u1',ARRAY['SO4-2-u1-C1']::text[],'몇몇 사람의 의견만으로도 결정이 났으니 괜찮다고 여겨, 반영된 의견의 수를 놓친다','결정이 났는가보다 누구의 의견이 들어갔는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X03','soc',4,'u1',ARRAY['SO4-2-u1-C1']::text[],'민주주의를 나라의 일로만 좁혀 보고 가정·학교·지역의 일상 속 실천을 놓친다','가족회의 · 학급 회의 · 주민 회의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X04','soc',4,'u1',ARRAY['SO4-2-u1-C1']::text[],'민주주의 사회에서 일부 사람만 의견을 말할 수 있다고 여겨 존중·평등·자유를 놓친다','모두 존중받고 평등하게 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X05','soc',4,'u1',ARRAY['SO4-2-u1-C2']::text[],'내 의견만 강하게 주장하거나 큰 목소리로 말하는 사람의 뜻대로 정하면 된다고 여긴다','충분한 대화 · 존중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X06','soc',4,'u1',ARRAY['SO4-2-u1-C2']::text[],'반대 의견이 나오면 처음 의견은 버려진다고 여겨, 까닭을 받아들여 고쳐 다시 낼 수 있음을 놓친다','배려 · 양보 · 타협으로 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X07','soc',4,'u1',ARRAY['SO4-2-u1-C2']::text[],'함께 정한 해결 방안은 그 의견을 낸 사람이나 찬성한 사람만 지키면 된다고 여긴다','구성원 모두가 적극적으로 실천해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X08','soc',4,'u1',ARRAY['SO4-2-u1-C2']::text[],'의견을 따질 때 옳고 그름과 장단점 대신 말한 사람·말한 차례·목소리 크기를 본다','옳고 그름과 장단점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X09','soc',4,'u1',ARRAY['SO4-2-u1-C3']::text[],'학교에서는 민주주의를 실천하는 모습을 찾을 수 없다고, 또는 학교의 일은 한 구성원만 정한다고 여긴다','학생 · 교사 · 학부모가 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X10','soc',4,'u1',ARRAY['SO4-2-u1-C3']::text[],'학생 자치회나 학생 참여 예산제가 무엇이고 무슨 일을 하는지 잘못 안다','학생 대표 · 학생이 제안한 사업') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X11','soc',4,'u1',ARRAY['SO4-2-u1-C3']::text[],'사례마다 한 일이 다르면 민주주의를 실천하는 걸음도 다르다고 여긴다','의견 모으기 → 회의로 정하기 → 함께 실천') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X12','soc',4,'u1',ARRAY['SO4-2-u1-C4']::text[],'학교의 일을 민주적으로 해결하는 과정의 차례를 잘못 안다(해결 방안을 먼저 결정하는 등)','확인 → 탐색 → 결정 → 실천 → 결과 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X13','soc',4,'u1',ARRAY['SO4-2-u1-C4']::text[],'해결 방안을 찾을 때 생각할 점을 잘못 안다(빨리 끝나는 것, 한 사람이 좋아하는 것만 보는 등)','원인 · 장단점 · 많은 구성원의 만족') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X14','soc',4,'u1',ARRAY['SO4-2-u1-C4']::text[],'민주적으로 정하는 방법은 한 가지뿐이라고, 또는 한 방법이 언제나 더 낫다고 여긴다','무엇을 정하느냐에 따라 설문조사도 회의도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X15','soc',4,'u1',ARRAY['SO4-2-u1-C4']::text[],'해결 방안을 실천하면 끝이라고 여겨 결과를 확인하고 보완하는 일을 놓친다','전과 후를 비교하고 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X16','soc',4,'u1',ARRAY['SO4-2-u1-C5']::text[],'학교 행사를 계획할 때 이름이나 내용만 보고 행사로 얻을 수 있는 결과를 놓친다','그 행사로 무엇을 얻을까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X17','soc',4,'u1',ARRAY['SO4-2-u1-C5']::text[],'학생 자치회 임원은 학생들에게 묻지 않고 자기 생각이나 임원끼리 정해도 된다고 여긴다','민주적 의사소통 · 생각을 최대한 반영') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X18','soc',4,'u1',ARRAY['SO4-2-u1-C6']::text[],'주민 자치의 뜻을 잘못 안다(몇몇이 대신 정해 알려 주는 것, 자기 집 일만 해결하는 것으로 여기는 등)','주민이 지역의 주인으로서 함께 해결해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X19','soc',4,'u1',ARRAY['SO4-2-u1-C6']::text[],'주민 자치회가 무엇인지, 학생 자치회와 어떤 점이 같은지 잘못 안다','구성원이 주인으로서 함께 참여해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X20','soc',4,'u1',ARRAY['SO4-2-u1-C7']::text[],'지역에서 일어나는 일이 주민들의 생활과 관계없다고, 또는 주민은 지역을 잘 모른다고 여긴다','생활에 영향 · 지역을 잘 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X21','soc',4,'u1',ARRAY['SO4-2-u1-C7']::text[],'주민 참여가 활발할 때와 활발하지 않을 때의 지역 모습을 바꾸어 짝짓는다','참여하면 해결 · 발전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X22','soc',4,'u1',ARRAY['SO4-2-u1-C8']::text[],'주민 참여 방법을 한두 가지로 좁히거나 방법과 모습을 잘못 짝짓는다','직접 참여 · 의견 전달 · 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X23','soc',4,'u1',ARRAY['SO4-2-u1-C8']::text[],'지역의 일에 참여할 때 나의 이익만 생각하거나 다른 사람이 대신해 주기를 기다려도 된다고 여긴다','적극적으로 · 지역 전체의 이익') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X24','soc',4,'u1',ARRAY['SO4-2-u1-C9']::text[],'주민 자치 사례를 조사하는 방법이나 공공 기관을 방문할 때 지킬 점을 잘못 안다','미리 허락 · 보호자 · 공공질서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X25','soc',4,'u1',ARRAY['SO4-2-u1-C9']::text[],'조사 계획서와 조사 보고서를 헷갈리거나, 조사해야 쓸 수 있는 칸을 조사 전에 쓸 수 있다고 여긴다','전에 정할 칸 · 마친 뒤 쓸 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X26','soc',4,'u1',ARRAY['SO4-2-u1-C10']::text[],'주민 자치에 참여하는 과정의 차례를 잘못 알거나, 어린이는 주민 자치에 참여할 수 없다고 여긴다','찾기 → 방법 → 실천 → 달라진 점 → 평가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u1-X27','soc',4,'u1',ARRAY['SO4-2-u1-C10']::text[],'주민의 힘만으로 해결하기 어려운 문제는 그냥 두어야 한다고 여겨 공공 기관에 도움을 청할 수 있음을 놓친다','공공 기관에 도움을 청해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#1','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',1,'mc','auto','구성원들의 다양한 의견을 반영하여 사회 공동의 문제에 관한 의사 결정을 하는 방식을 무엇이라고 하나요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"mc","stem":"구성원들의 다양한 의견을 반영하여 사회 공동의 문제에 관한 의사 결정을 하는 방식을 무엇이라고 하나요?","options":[{"t":"민주주의","correct":true},{"t":"봉사 활동","mis":"SO4-2-u1-X01"},{"t":"여가 활동","mis":"SO4-2-u1-X01"},{"t":"경제 활동","mis":"SO4-2-u1-X01"}],"explanation":["모두의 의견을 모아요.","함께 결정하는 방식이에요.","민주주의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#2','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',1,'sa','auto','신문 기사에서 학생들은 후보들의 ○○을 듣고 투표했어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"sa","stem":"신문 기사에서 학생들은 후보들의 ○○을 듣고 투표했어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["공약"],"explanation":["후보가 하겠다고 한 약속이에요.","공◯이에요.","공약이에요."],"asset":{"type":"passage","lines":["○○ 초등학교에서 학생 자치회 임원 선거가 열렸다.","학생들은 후보들의 공약을 듣고 기표소에서 투표했다.","투표 결과에 따라 학생 자치회 임원이 정해졌다."],"title":"신문 기사(내 말로)"},"mis":"SO4-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#3','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',1,'ox','auto','민주주의 사회에서는 구성원 모두가 평등한 입장에서 자신의 의견을 말할 수 있어요.',ARRAY['SO4-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"ox","stem":"민주주의 사회에서는 구성원 모두가 평등한 입장에서 자신의 의견을 말할 수 있어요.","answer":"O","reason_options":[{"t":"구성원 모두가 인간으로서 존중받기 때문에","correct":true},{"t":"어른만 의견을 말할 수 있기 때문에","mis":"SO4-2-u1-X04"}],"mis":"SO4-2-u1-X04","explanation":["모두 존중받아요.","평등하게 말해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#4','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',1,'mc','auto','학교에 의견함을 둔 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X01','SO4-2-u1-X04']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"mc","stem":"학교에 의견함을 둔 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생들의 의견을 모아 학교의 일을 정할 때 반영하려고","correct":true},{"t":"학교를 꾸미는 장식으로 쓰려고","mis":"SO4-2-u1-X01"},{"t":"선생님 혼자 학교의 일을 정하려고","mis":"SO4-2-u1-X01"},{"t":"학생들의 말을 막으려고","mis":"SO4-2-u1-X04"}],"explanation":["하고 싶은 말을 넣어요.","학교가 살펴봐요.","의견을 반영해요."],"asset":{"type":"passage","lines":["학교 복도에 「의견함」이 놓여 있다.","학생들은 학교에 하고 싶은 말을 적어 넣는다.","학교는 모인 의견을 살펴 학교의 일을 정할 때 참고한다."],"title":"우리 학교의 의견함"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#5','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',2,'mc','auto','일상생활에서 민주주의를 실천하는 모습이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u1-X03']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"mc","stem":"일상생활에서 민주주의를 실천하는 모습이 아닌 것은 무엇인가요?","options":[{"t":"반장이 혼자 학급 규칙을 정해 알려 줘요","correct":true},{"t":"가족회의로 주말에 갈 곳을 정해요","mis":"SO4-2-u1-X03"},{"t":"주민 회의로 축제 장소를 정해요","mis":"SO4-2-u1-X03"},{"t":"투표로 국가의 중요한 일을 정해요","mis":"SO4-2-u1-X03"}],"explanation":["함께 정했는지 봐요.","혼자 정한 것이 있어요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#6','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',2,'match','auto','민주주의를 실천하는 곳과 그 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"match","stem":"민주주의를 실천하는 곳과 그 모습을 알맞게 이으세요.","pairs":[{"l":"가정","r":"가족회의로 여행 갈 장소 정하기"},{"l":"학교","r":"학급 회의로 급식 먹는 순서 정하기"},{"l":"지역","r":"주민 회의로 축제 장소 정하기"},{"l":"국가","r":"투표로 국가의 중요한 일 정하기"}],"mis":"SO4-2-u1-X03","explanation":["집에서는 가족이에요.","학교와 지역도 있어요.","나라도 있어요."],"asset":{"type":"passage","lines":["가정 — 가족회의로 주말에 여행 갈 장소를 정해요.","학교 — 학급 회의로 급식 먹는 순서를 정해요.","지역 — 주민 회의로 지역 축제를 열 장소를 정해요.","국가 — 투표로 국가의 중요한 일을 정해요."],"title":"일상생활 속 민주주의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#7','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',2,'mc','auto','한 사회에서 몇몇 사람의 뜻대로만 결정하면 생길 수 있는 문제는 무엇인가요?',ARRAY['SO4-2-u1-X02']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"mc","stem":"한 사회에서 몇몇 사람의 뜻대로만 결정하면 생길 수 있는 문제는 무엇인가요?","options":[{"t":"결정을 내린 일부 사람에게만 유리한 선택을 할 수 있어요","correct":true},{"t":"결정이 아예 나지 않아요","mis":"SO4-2-u1-X02"},{"t":"모든 사람의 의견이 빠짐없이 담겨요","mis":"SO4-2-u1-X02"},{"t":"모두가 더 만족해요","mis":"SO4-2-u1-X02"}],"explanation":["몇몇만 정했어요.","다른 사람 의견은 빠져요.","일부에게만 유리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#8','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',2,'blank','auto','민주주의는 구성원들의 다양한 (    )을 반영하여 사회 공동의 문제를 결정하는 방식이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"blank","stem":"민주주의는 구성원들의 다양한 (    )을 반영하여 사회 공동의 문제를 결정하는 방식이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"의견","correct":true},{"t":"나이","mis":"SO4-2-u1-X01"},{"t":"키","mis":"SO4-2-u1-X01"},{"t":"이름","mis":"SO4-2-u1-X01"}],"explanation":["사람들이 내는 생각이에요.","의◯이에요.","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#9','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',2,'ox','auto','학생 자치회 임원 선거는 민주주의를 실천하는 사례예요.',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"ox","stem":"학생 자치회 임원 선거는 민주주의를 실천하는 사례예요.","answer":"O","reason_options":[{"t":"학생들의 의견을 투표로 확인해 학교의 대표를 정하기 때문에","correct":true},{"t":"기표소가 있으면 무엇이든 민주주의이기 때문에","mis":"SO4-2-u1-X01"}],"mis":"SO4-2-u1-X01","explanation":["투표로 의견을 확인해요.","대표를 정해요.","그래서 O예요."],"asset":{"type":"passage","lines":["○○ 초등학교에서 학생 자치회 임원 선거가 열렸다.","학생들은 후보들의 공약을 듣고 기표소에서 투표했다.","투표 결과에 따라 학생 자치회 임원이 정해졌다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_basic#10','soc',4,2,'u1','L01','g4_2_soc_u1_L01_basic','lesson_basic','SO4-2-u1-C1',3,'mc','auto','의견함 판 두 번을 견줄 때 달라진 것은 무엇인가요?',ARRAY['SO4-2-u1-X02']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"mc","stem":"의견함 판 두 번을 견줄 때 달라진 것은 무엇인가요?","options":[{"t":"결정에 반영된 의견의 수","correct":true},{"t":"결정이 났는지 안 났는지","mis":"SO4-2-u1-X02"},{"t":"회의 주제","mis":"SO4-2-u1-X02"},{"t":"반 친구의 수","mis":"SO4-2-u1-X02"}],"explanation":["두 번 다 결정이 났어요.","의견을 낸 사람 수가 달라요.","반영된 의견의 수예요."],"asset":{"type":"passage","lines":["첫째 판 — 여섯 명 가운데 두 명만 의견을 냈고 결정이 났다.","둘째 판 — 여섯 명이 모두 의견을 냈고 결정이 났다.","(주제 — 급식을 먹는 순서를 어떻게 정할까요?)"],"title":"의견함 판 두 번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
