INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#3','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',3,'mc','auto','민주주의가 중요한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X01','SO4-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"mc","stem":"민주주의가 중요한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"구성원 모두가 존중받고 평등하게 의견을 낼 수 있기 때문이에요","correct":true},{"t":"결정을 가장 빨리 내릴 수 있기 때문이에요","mis":"SO4-2-u1-X01"},{"t":"말을 잘하는 사람이 이길 수 있기 때문이에요","mis":"SO4-2-u1-X04"},{"t":"의논하지 않아도 되기 때문이에요","mis":"SO4-2-u1-X01"}],"explanation":["누가 존중받나요?","모두예요.","평등하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#4','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',3,'error','auto','민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X03','SO4-2-u1-X01']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"error","stem":"민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「민주주의는 나라에서만 실천하는 거야.」","correct":true,"mis_target":"SO4-2-u1-X03"},{"t":"친구 가 — 「가족회의도 민주주의를 실천하는 모습이야.」","mis":"SO4-2-u1-X03"},{"t":"친구 다 — 「다양한 의견을 반영해 함께 결정해.」","mis":"SO4-2-u1-X01"}],"explanation":["가정에서도 해요.","나라만이 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가정 — 가족회의로 주말에 여행 갈 장소를 정해요.","학교 — 학급 회의로 급식 먹는 순서를 정해요.","지역 — 주민 회의로 지역 축제를 열 장소를 정해요.","국가 — 투표로 국가의 중요한 일을 정해요."],"title":"일상생활 속 민주주의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#5','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',3,'mc','auto','「급식 먹는 순서」를 정할 때 민주주의에 가장 가까운 방법은 무엇인가요?',ARRAY['SO4-2-u1-X02','SO4-2-u1-X04','SO4-2-u1-X01']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"mc","stem":"「급식 먹는 순서」를 정할 때 민주주의에 가장 가까운 방법은 무엇인가요?","options":[{"t":"반 친구 모두의 의견을 듣고 함께 정해요","correct":true},{"t":"먼저 말한 두 사람의 뜻대로 정해요","mis":"SO4-2-u1-X02"},{"t":"목소리가 큰 친구가 정해요","mis":"SO4-2-u1-X04"},{"t":"선생님께 정해 달라고만 해요","mis":"SO4-2-u1-X01"}],"explanation":["누구의 의견이 들어가나요?","모두의 의견이에요.","함께 정해요."],"asset":{"type":"passage","lines":["첫째 판 — 여섯 명 가운데 두 명만 의견을 냈고 결정이 났다.","둘째 판 — 여섯 명이 모두 의견을 냈고 결정이 났다.","(주제 — 급식을 먹는 순서를 어떻게 정할까요?)"],"title":"의견함 판 두 번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#6','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',3,'ox','auto','신문 기사에서 학생 자치회 임원은 투표 결과에 따라 정해졌어요.',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"ox","stem":"신문 기사에서 학생 자치회 임원은 투표 결과에 따라 정해졌어요.","answer":"O","reason_options":[{"t":"학생들이 공약을 듣고 투표해 임원을 정했기 때문에","correct":true},{"t":"선생님이 미리 정해 두었기 때문에","mis":"SO4-2-u1-X01"}],"mis":"SO4-2-u1-X01","explanation":["기표소에서 투표했어요.","결과에 따라 정했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["○○ 초등학교에서 학생 자치회 임원 선거가 열렸다.","학생들은 후보들의 공약을 듣고 기표소에서 투표했다.","투표 결과에 따라 학생 자치회 임원이 정해졌다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#7','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',3,'mc','auto','민주주의 사회의 구성원이 누리는 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X04']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"mc","stem":"민주주의 사회의 구성원이 누리는 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"허락받은 사람만 의견을 말할 수 있어요","correct":true},{"t":"인간으로서 존중받아요","mis":"SO4-2-u1-X04"},{"t":"평등한 입장에서 의견을 말해요","mis":"SO4-2-u1-X04"},{"t":"자유롭게 행동할 수 있어요","mis":"SO4-2-u1-X04"}],"explanation":["존중 · 평등 · 자유예요.","모두가 누려요.","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#8','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',4,'mc','auto','의견함 판 두 번을 보고 알 수 있는 민주주의의 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X02','SO4-2-u1-X01']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C1","difficulty":4,"kind":"mc","stem":"의견함 판 두 번을 보고 알 수 있는 민주주의의 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"결정이 났는가보다 구성원의 다양한 의견이 결정에 들어갔는가가 중요해요","correct":true},{"t":"결정만 나면 어떤 방법이든 같아요","mis":"SO4-2-u1-X02"},{"t":"의견을 내는 사람은 적을수록 좋아요","mis":"SO4-2-u1-X02"},{"t":"결정은 한 사람이 내리는 것이 좋아요","mis":"SO4-2-u1-X01"}],"explanation":["둘 다 결정은 났어요.","들어간 의견이 달라요.","그것이 중요해요."],"asset":{"type":"passage","lines":["첫째 판 — 여섯 명 가운데 두 명만 의견을 냈고 결정이 났다.","둘째 판 — 여섯 명이 모두 의견을 냈고 결정이 났다.","(주제 — 급식을 먹는 순서를 어떻게 정할까요?)"],"title":"의견함 판 두 번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#9','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',4,'mc','auto','네 곳의 모습을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X03','SO4-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":4,"kind":"mc","stem":"네 곳의 모습을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"민주주의는 가정·학교·지역·국가 등 일상생활 곳곳에서 실천해요","correct":true},{"t":"민주주의는 국가에서만 실천해요","mis":"SO4-2-u1-X03"},{"t":"어린이는 민주주의를 실천할 수 없어요","mis":"SO4-2-u1-X03"},{"t":"민주주의는 한 사람이 정하는 거예요","mis":"SO4-2-u1-X01"}],"explanation":["가정이 있어요.","학교와 지역도 있어요.","곳곳에서 실천해요."],"asset":{"type":"passage","lines":["가정 — 가족회의로 주말에 여행 갈 장소를 정해요.","학교 — 학급 회의로 급식 먹는 순서를 정해요.","지역 — 주민 회의로 지역 축제를 열 장소를 정해요.","국가 — 투표로 국가의 중요한 일을 정해요."],"title":"일상생활 속 민주주의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L01_challenge#10','soc',4,2,'u1','L01','g4_2_soc_u1_L01_challenge','lesson_challenge','SO4-2-u1-C1',4,'essay','teacher','의견함 판의 첫째 판과 둘째 판을 견주어, 어느 판이 민주주의에 더 가까운지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C1","difficulty":4,"kind":"essay","stem":"의견함 판의 첫째 판과 둘째 판을 견주어, 어느 판이 민주주의에 더 가까운지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 둘째 판이 민주주의에 더 가까워요. 첫째 판은 두 명의 의견만 반영되었지만, 둘째 판은 여섯 명 모두의 의견이 반영되어 함께 결정했기 때문이에요.","scoring_points":["둘째 판을 골랐는가","반영된 의견의 수를 견주었는가","다양한 의견을 반영한다는 뜻과 이었는가"]},"explanation":["두 판을 견줘요.","들어간 의견을 세어요.","까닭을 써요."],"asset":{"type":"passage","lines":["첫째 판 — 여섯 명 가운데 두 명만 의견을 냈고 결정이 났다.","둘째 판 — 여섯 명이 모두 의견을 냈고 결정이 났다.","(주제 — 급식을 먹는 순서를 어떻게 정할까요?)"],"title":"의견함 판 두 번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#1','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',1,'mc','auto','일상생활에서 공동의 문제를 민주적으로 해결하려면 무엇이 필요한가요?',ARRAY['SO4-2-u1-X05']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"mc","stem":"일상생활에서 공동의 문제를 민주적으로 해결하려면 무엇이 필요한가요?","options":[{"t":"충분한 대화","correct":true},{"t":"빠른 결정","mis":"SO4-2-u1-X05"},{"t":"큰 목소리","mis":"SO4-2-u1-X05"},{"t":"조용히 있기","mis":"SO4-2-u1-X05"}],"explanation":["서로 이야기를 나눠요.","충분히 해요.","충분한 대화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#2','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',1,'sa','auto','많은 사람이 가지고 있는 생각이나 의견을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"sa","stem":"많은 사람이 가지고 있는 생각이나 의견을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["여론"],"explanation":["여론 조사 전문가가 조사해요.","여◯이에요.","여론이에요."],"mis":"SO4-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#3','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',1,'ox','auto','민주적으로 문제를 해결하려면 내 의견만 강하게 주장해야 해요.',ARRAY['SO4-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"ox","stem":"민주적으로 문제를 해결하려면 내 의견만 강하게 주장해야 해요.","answer":"X","reason_options":[{"t":"상대방의 의견을 존중하고 서로 배려해야 하기 때문에","correct":true},{"t":"내 의견이 언제나 옳기 때문에","mis":"SO4-2-u1-X05"}],"mis":"SO4-2-u1-X05","explanation":["내 의견만일까요?","상대방도 존중해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#4','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',1,'mc','auto','함께 결정한 해결 방안은 누가 실천해야 하나요?',ARRAY['SO4-2-u1-X07']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"mc","stem":"함께 결정한 해결 방안은 누가 실천해야 하나요?","options":[{"t":"구성원 모두가 적극적으로 실천해요","correct":true},{"t":"의견을 낸 사람만 지켜요","mis":"SO4-2-u1-X07"},{"t":"반장만 지켜요","mis":"SO4-2-u1-X07"},{"t":"찬성한 사람만 지켜요","mis":"SO4-2-u1-X07"}],"explanation":["함께 정했어요.","모두의 약속이에요.","모두가 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#5','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',2,'mc','auto','해결 방안을 찾을 때 상대방 의견의 무엇을 생각해야 하나요?',ARRAY['SO4-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"mc","stem":"해결 방안을 찾을 때 상대방 의견의 무엇을 생각해야 하나요?","options":[{"t":"옳고 그름과 장단점","correct":true},{"t":"말한 사람의 나이","mis":"SO4-2-u1-X08"},{"t":"목소리의 크기","mis":"SO4-2-u1-X08"},{"t":"말한 차례","mis":"SO4-2-u1-X08"}],"explanation":["의견 자체를 봐요.","좋은 점과 아쉬운 점이에요.","옳고 그름과 장단점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#6','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',2,'blank','auto','상대방의 의견을 존중하고, 서로 배려하며 양보하고 (    )하는 태도를 갖춰야 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X05']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"blank","stem":"상대방의 의견을 존중하고, 서로 배려하며 양보하고 (    )하는 태도를 갖춰야 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"타협","correct":true},{"t":"고집","mis":"SO4-2-u1-X05"},{"t":"무시","mis":"SO4-2-u1-X05"},{"t":"명령","mis":"SO4-2-u1-X05"}],"explanation":["서로 조금씩 물러나요.","알맞게 맞춰요.","타협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#7','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',2,'mc','auto','회의 장면에서 마 의견은 왜 함께 문제를 해결하려는 의견이 아닌가요?',ARRAY['SO4-2-u1-X08']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"mc","stem":"회의 장면에서 마 의견은 왜 함께 문제를 해결하려는 의견이 아닌가요?","options":[{"t":"회의를 하지 말고 한 사람에게 다 몰아 주자고 했기 때문이에요","correct":true},{"t":"너무 짧은 말이기 때문이에요","mis":"SO4-2-u1-X08"},{"t":"맨 뒤에 나온 말이기 때문이에요","mis":"SO4-2-u1-X08"},{"t":"목소리가 작았기 때문이에요","mis":"SO4-2-u1-X08"}],"explanation":["회의를 하지 말자고 했어요.","한 사람에게 몰아요.","함께 해결하지 않아요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#8','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',2,'ox','auto','반대 의견이 나왔던 의견도 까닭을 받아들여 고치면 다시 낼 수 있어요.',ARRAY['SO4-2-u1-X06']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"ox","stem":"반대 의견이 나왔던 의견도 까닭을 받아들여 고치면 다시 낼 수 있어요.","answer":"O","reason_options":[{"t":"물러난 의견도 지워지지 않고 남아 있어 고쳐 쓸 수 있기 때문에","correct":true},{"t":"한 번 반대된 의견은 영영 버려지기 때문에","mis":"SO4-2-u1-X06"}],"mis":"SO4-2-u1-X06","explanation":["의견은 남아 있어요.","고칠 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_basic#9','soc',4,2,'u1','L02','g4_2_soc_u1_L02_basic','lesson_basic','SO4-2-u1-C2',2,'match','auto','회의 장면의 모습과 그 태도를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"match","stem":"회의 장면의 모습과 그 태도를 알맞게 이으세요.","pairs":[{"l":"다른 의견의 장단점을 들어 반대해요","r":"옳고 그름과 장단점을 생각해요"},{"l":"처음 의견을 고쳐 새로 제안해요","r":"양보하고 타협해요"},{"l":"함께 정한 방법을 모두 지켜요","r":"적극적으로 실천해요"}],"mis":"SO4-2-u1-X06","explanation":["장단점을 들었어요.","고쳐서 냈어요.","모두 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
