INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#2','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',2,'ox','auto','자기 생각과 다르다고 해서 다른 사람의 의견을 무시하면 안 돼요.',ARRAY['SO4-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"ox","stem":"자기 생각과 다르다고 해서 다른 사람의 의견을 무시하면 안 돼요.","answer":"O","reason_options":[{"t":"상대방의 의견을 존중해야 함께 문제를 해결할 수 있기 때문에","correct":true},{"t":"다른 생각은 회의에 방해만 되기 때문에","mis":"SO4-2-u1-X05"}],"mis":"SO4-2-u1-X05","explanation":["생각이 다를 수 있어요.","존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#3','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',3,'mc','auto','회의 장면에서 다 의견이 나 의견에 반대한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X08']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"mc","stem":"회의 장면에서 다 의견이 나 의견에 반대한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제비뽑기로 정하면 학급을 위해 봉사하고 싶은 학생들의 뜻을 놓칠 수 있어서","correct":true},{"t":"나 의견을 낸 친구가 싫어서","mis":"SO4-2-u1-X08"},{"t":"나 의견이 맨 처음에 나와서","mis":"SO4-2-u1-X08"},{"t":"제비뽑기는 시간이 너무 짧아서","mis":"SO4-2-u1-X08"}],"explanation":["의견의 단점을 봐요.","봉사하고 싶은 뜻이에요.","그것을 놓쳐요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#4','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',3,'error','auto','회의 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X06','SO4-2-u1-X08','SO4-2-u1-X07']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"error","stem":"회의 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「반대 의견이 나오면 내 의견은 그냥 버려야 해.」","correct":true,"mis_target":"SO4-2-u1-X06"},{"t":"친구 가 — 「까닭을 들어 반대할 수 있어.」","mis":"SO4-2-u1-X08"},{"t":"친구 나 — 「정한 방법은 모두 함께 지켜야 해.」","mis":"SO4-2-u1-X07"}],"explanation":["버려야 할까요?","고쳐서 낼 수 있어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#5','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',3,'mc','auto','회의에서 마 의견을 낸 친구의 태도를 고친다면 어떻게 하면 좋을까요?',ARRAY['SO4-2-u1-X05','SO4-2-u1-X07']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"mc","stem":"회의에서 마 의견을 낸 친구의 태도를 고친다면 어떻게 하면 좋을까요?","options":[{"t":"공동의 일에 관심을 갖고 함께 해결하려고 노력해요","correct":true},{"t":"더 큰 목소리로 같은 말을 해요","mis":"SO4-2-u1-X05"},{"t":"다른 의견은 듣지 않아요","mis":"SO4-2-u1-X05"},{"t":"회의가 끝나면 정한 것을 지키지 않아요","mis":"SO4-2-u1-X07"}],"explanation":["회의를 하지 말자고 했어요.","관심이 필요해요.","함께 해결해요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#6','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',3,'ox','auto','회의에서 가장 먼저 나온 의견을 따르는 것이 민주적인 방법이에요.',ARRAY['SO4-2-u1-X08']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"ox","stem":"회의에서 가장 먼저 나온 의견을 따르는 것이 민주적인 방법이에요.","answer":"X","reason_options":[{"t":"먼저 나왔는지가 아니라 의견의 옳고 그름과 장단점을 따져야 하기 때문에","correct":true},{"t":"먼저 말한 사람의 의견이 언제나 옳기 때문에","mis":"SO4-2-u1-X08"}],"mis":"SO4-2-u1-X08","explanation":["차례가 중요할까요?","장단점을 따져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#7','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',3,'mc','auto','회의 장면의 다섯 의견 가운데 서로 배려하며 겹치는 사람만 따로 정하자고 한 의견은 무엇인가요?',ARRAY['SO4-2-u1-X06','SO4-2-u1-X05']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"mc","stem":"회의 장면의 다섯 의견 가운데 서로 배려하며 겹치는 사람만 따로 정하자고 한 의견은 무엇인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"SO4-2-u1-X06"},{"t":"나","mis":"SO4-2-u1-X06"},{"t":"마","mis":"SO4-2-u1-X05"}],"explanation":["원하는 역할을 먼저 골라요.","겹치면 가위바위보예요.","다 의견이에요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#8','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',4,'mc','auto','회의 장면을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X06','SO4-2-u1-X05']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C2","difficulty":4,"kind":"mc","stem":"회의 장면을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"반대하는 까닭을 듣고 의견을 고쳐 가며 더 나은 해결 방안을 찾을 수 있어요","correct":true},{"t":"처음 나온 의견이 끝까지 그대로 정해져요","mis":"SO4-2-u1-X06"},{"t":"목소리가 큰 의견이 정해져요","mis":"SO4-2-u1-X05"},{"t":"회의를 하지 않는 것이 가장 좋아요","mis":"SO4-2-u1-X05"}],"explanation":["반대가 있었어요.","고친 의견이 나왔어요.","더 나아졌어요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#9','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',4,'mc','auto','민주주의를 실천하는 태도를 차례대로 가장 알맞게 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X07','SO4-2-u1-X05','SO4-2-u1-X08']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C2","difficulty":4,"kind":"mc","stem":"민주주의를 실천하는 태도를 차례대로 가장 알맞게 정리한 것은 무엇인가요?","options":[{"t":"충분히 대화하고, 장단점을 따지며 서로 양보해 정한 뒤, 모두 함께 실천해요","correct":true},{"t":"먼저 정하고, 나중에 대화하고, 의견을 낸 사람만 실천해요","mis":"SO4-2-u1-X07"},{"t":"내 의견을 끝까지 주장하고, 정해지면 나만 지켜요","mis":"SO4-2-u1-X05"},{"t":"대화 없이 차례대로 하나씩 고르고 끝내요","mis":"SO4-2-u1-X08"}],"explanation":["먼저 대화해요.","따지고 양보해요.","모두 실천해요."],"asset":{"type":"passage","lines":["① 충분한 대화를 나눠요.","② 상대방의 의견을 존중해요.","③ 서로 배려하며 양보하고 타협해요.","④ 의견의 옳고 그름과 장단점을 생각해요.","⑤ 함께 정한 것은 모두가 적극적으로 실천해요."],"title":"민주적으로 해결하는 태도 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L02_challenge#10','soc',4,2,'u1','L02','g4_2_soc_u1_L02_challenge','lesson_challenge','SO4-2-u1-C2',4,'essay','teacher','회의 장면에서 나라면 어떤 의견을 내고 싶은지 쓰고, 그 의견을 낼 때 지킬 태도를 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C2","difficulty":4,"kind":"essay","stem":"회의 장면에서 나라면 어떤 의견을 내고 싶은지 쓰고, 그 의견을 낼 때 지킬 태도를 하나 쓰세요.","answer_guide":{"answer":"예: 저는 원하는 역할을 먼저 고르고 겹치면 지난 학기에 그 역할을 해 보지 못한 친구에게 먼저 기회를 주자고 하고 싶어요. 의견을 낼 때 다른 친구의 의견도 존중하며 장단점을 함께 따져 볼 거예요.","scoring_points":["회의 주제에 맞는 의견을 썼는가","지킬 태도를 썼는가","태도가 민주주의 실천과 맞는가"]},"explanation":["주제를 봐요.","내 의견을 써요.","태도도 써요."],"asset":{"type":"passage","lines":["주제 — 2학기 1인 1역할을 어떻게 정할까요?","가. 칭찬 스티커를 많이 받은 학생이 먼저 골라요.","나. 공평하게 제비뽑기로 정해요.","다. 원하는 역할을 먼저 고르고, 겹치는 사람만 가위바위보로 정해요.","라. 칭찬 스티커를 적게 받은 학생에게 먼저 고를 기회를 줘요.","마. 회의는 하지 말고 한 사람에게 다 몰아 줘요."],"title":"교과서 학급 회의 장면(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#1','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',1,'mc','auto','학생들이 대표를 뽑아 구성하는 모임은 무엇인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"mc","stem":"학생들이 대표를 뽑아 구성하는 모임은 무엇인가요?","options":[{"t":"학생 자치회","correct":true},{"t":"학부모 모임","mis":"SO4-2-u1-X10"},{"t":"교사 회의","mis":"SO4-2-u1-X10"},{"t":"동네 모임","mis":"SO4-2-u1-X10"}],"explanation":["학생들의 대표예요.","학생 ◯◯회예요.","학생 자치회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#2','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',1,'sa','auto','어떤 일을 하기 위해 필요한 돈을 미리 계획하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"sa","stem":"어떤 일을 하기 위해 필요한 돈을 미리 계획하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["예산"],"explanation":["학생 참여 ◯◯제예요.","예◯이에요.","예산이에요."],"mis":"SO4-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#3','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',1,'ox','auto','학교에서는 구성원들이 민주주의를 실천하는 모습을 찾아볼 수 없어요.',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"ox","stem":"학교에서는 구성원들이 민주주의를 실천하는 모습을 찾아볼 수 없어요.","answer":"X","reason_options":[{"t":"학교에서도 더 나은 학교를 만들려고 구성원들이 민주주의를 실천하기 때문에","correct":true},{"t":"민주주의는 학교 밖에서만 실천하기 때문에","mis":"SO4-2-u1-X09"}],"mis":"SO4-2-u1-X09","explanation":["학생 자치회가 있어요.","함께 의논해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#4','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',1,'mc','auto','학교의 여러 가지 일을 함께 의논하며 해결해 나가는 학교 구성원은 누구인가요?',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"mc","stem":"학교의 여러 가지 일을 함께 의논하며 해결해 나가는 학교 구성원은 누구인가요?","options":[{"t":"학생, 교사, 학부모","correct":true},{"t":"학생만","mis":"SO4-2-u1-X09"},{"t":"교사만","mis":"SO4-2-u1-X09"},{"t":"학부모만","mis":"SO4-2-u1-X09"}],"explanation":["학교 구성원을 떠올려요.","셋이 있어요.","모두 함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#5','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',2,'mc','auto','학생 자치회가 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"mc","stem":"학생 자치회가 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"학생들의 의견을 학교에 전달하고 학교의 일을 민주적으로 해결하려고 노력해요","correct":true},{"t":"선생님의 수업을 대신해요","mis":"SO4-2-u1-X10"},{"t":"학생들의 의견을 막아요","mis":"SO4-2-u1-X10"},{"t":"학교 시설을 혼자 고쳐요","mis":"SO4-2-u1-X10"}],"explanation":["학생들의 대표예요.","의견을 전해요.","민주적으로 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#6','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',2,'mc','auto','학생 참여 예산제에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"mc","stem":"학생 참여 예산제에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"학생들이 제안한 사업에 예산을 지원하고 학생들이 스스로 기획해 운영해요","correct":true},{"t":"교사가 학생에게 상을 주는 제도예요","mis":"SO4-2-u1-X10"},{"t":"학부모가 학교를 찾아오는 제도예요","mis":"SO4-2-u1-X10"},{"t":"학생이 학교에 오는 시각을 정하는 제도예요","mis":"SO4-2-u1-X10"}],"explanation":["학생이 제안해요.","돈을 지원해요.","스스로 운영해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#7','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',2,'match','auto','세 사례와 그 사례에서 정한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"match","stem":"세 사례와 그 사례에서 정한 일을 알맞게 이으세요.","pairs":[{"l":"학생 자치회","r":"3월 행사 정하기"},{"l":"학교 구성원 전체 회의","r":"학교의 일 정하기"},{"l":"학생 참여 예산제","r":"우산 빗물 제거기 설치하기"}],"mis":"SO4-2-u1-X11","explanation":["학생 자치회는 행사예요.","전체 회의는 학교의 일이에요.","예산제는 사업이에요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#8','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',2,'blank','auto','학교에서는 더 나은 (    )를 만들려고 구성원들이 민주주의를 실천해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"blank","stem":"학교에서는 더 나은 (    )를 만들려고 구성원들이 민주주의를 실천해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"학교","correct":true},{"t":"시험","mis":"SO4-2-u1-X09"},{"t":"방학","mis":"SO4-2-u1-X09"},{"t":"운동회","mis":"SO4-2-u1-X09"}],"explanation":["어디에서의 일인가요?","우리가 다니는 곳이에요.","학교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#9','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',2,'ox','auto','도서관 꾸미기에서 학생·교사·학부모의 의견을 묻고 회의로 정한 것은 민주주의를 실천한 모습이에요.',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"ox","stem":"도서관 꾸미기에서 학생·교사·학부모의 의견을 묻고 회의로 정한 것은 민주주의를 실천한 모습이에요.","answer":"O","reason_options":[{"t":"구성원들의 의견을 모아 함께 결정했기 때문에","correct":true},{"t":"도서관은 책을 읽는 곳일 뿐이기 때문에","mis":"SO4-2-u1-X09"}],"mis":"SO4-2-u1-X09","explanation":["설문 조사를 했어요.","회의로 정했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["학교 도서관을 새롭게 꾸미기로 했다.","먼저 학생·교사·학부모에게 원하는 도서관 모습을 설문 조사했다.","설문 결과를 바탕으로 회의를 열어 모습을 정하고 새롭게 꾸몄다."],"title":"도서관 꾸미기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_basic#10','soc',4,2,'u1','L03','g4_2_soc_u1_L03_basic','lesson_basic','SO4-2-u1-C3',3,'mc','auto','세 사례가 한 일은 달라도 똑같이 밟은 걸음은 무엇인가요?',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"mc","stem":"세 사례가 한 일은 달라도 똑같이 밟은 걸음은 무엇인가요?","options":[{"t":"의견 모으기 → 회의로 정하기 → 함께 실천하기","correct":true},{"t":"한 사람이 정하기 → 모두 따르기","mis":"SO4-2-u1-X11"},{"t":"제안하기 → 바로 끝내기","mis":"SO4-2-u1-X11"},{"t":"세 사례의 걸음은 모두 달라요","mis":"SO4-2-u1-X11"}],"explanation":["한 일은 달라요.","걸음을 봐요.","세 걸음이 같아요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#1','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',2,'mc','auto','사례 ㉢에서 우산 빗물 제거기를 설치하기로 정한 곳은 어디인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"mc","stem":"사례 ㉢에서 우산 빗물 제거기를 설치하기로 정한 곳은 어디인가요?","options":[{"t":"전교 회의","correct":true},{"t":"교장실","mis":"SO4-2-u1-X10"},{"t":"학부모 모임","mis":"SO4-2-u1-X10"},{"t":"운동장","mis":"SO4-2-u1-X10"}],"explanation":["학급별로 제안했어요.","모여서 토의했어요.","전교 회의예요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#2','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',2,'ox','auto','학생 참여 예산제를 하면 학생들이 학교생활에 필요한 것을 직접 제안할 수 있어요.',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"ox","stem":"학생 참여 예산제를 하면 학생들이 학교생활에 필요한 것을 직접 제안할 수 있어요.","answer":"O","reason_options":[{"t":"학생들이 사업을 제안하면 실현하도록 예산을 지원하기 때문에","correct":true},{"t":"교사만 사업을 정하기 때문에","mis":"SO4-2-u1-X10"}],"mis":"SO4-2-u1-X10","explanation":["학생이 제안해요.","예산을 지원해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#3','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',3,'mc','auto','사례 ㉠에서 「모두 참여했다」는 세 걸음 가운데 어느 걸음인가요?',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"mc","stem":"사례 ㉠에서 「모두 참여했다」는 세 걸음 가운데 어느 걸음인가요?","options":[{"t":"함께 실천하기","correct":true},{"t":"의견 모으기","mis":"SO4-2-u1-X11"},{"t":"회의로 정하기","mis":"SO4-2-u1-X11"},{"t":"어느 걸음도 아니에요","mis":"SO4-2-u1-X11"}],"explanation":["행사를 정했어요.","그다음이에요.","함께 실천했어요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#4','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',3,'error','auto','세 사례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"error","stem":"세 사례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「세 사례는 한 일이 다르니 민주주의를 실천한 걸음도 모두 달라.」","correct":true,"mis_target":"SO4-2-u1-X11"},{"t":"친구 나 — 「세 사례 모두 의견을 모으는 데서 시작해.」","mis":"SO4-2-u1-X11"},{"t":"친구 다 — 「세 사례 모두 정한 것을 함께 실천했어.」","mis":"SO4-2-u1-X11"}],"explanation":["한 일은 달라요.","걸음은 같아요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#5','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',3,'mc','auto','학교에서 민주주의를 실천하는 사례로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X09','SO4-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"mc","stem":"학교에서 민주주의를 실천하는 사례로 알맞지 않은 것은 무엇인가요?","options":[{"t":"한 사람이 정한 것을 나머지가 묻지 않고 그대로 따라요","correct":true},{"t":"학생 자치회가 의견을 모아 행사를 정해요","mis":"SO4-2-u1-X09"},{"t":"학생·교사·학부모가 함께 의논해 학교의 일을 정해요","mis":"SO4-2-u1-X09"},{"t":"학생들이 제안한 사업을 전교 회의에서 정해요","mis":"SO4-2-u1-X10"}],"explanation":["함께 정했는지 봐요.","한 사람이 정한 것이 있어요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#6','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',3,'ox','auto','학교의 일은 교사만 의논해서 정하는 것이 바람직해요.',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"ox","stem":"학교의 일은 교사만 의논해서 정하는 것이 바람직해요.","answer":"X","reason_options":[{"t":"학생·교사·학부모가 학교 구성원으로서 함께 의논하기 때문에","correct":true},{"t":"학생과 학부모는 학교 구성원이 아니기 때문에","mis":"SO4-2-u1-X09"}],"mis":"SO4-2-u1-X09","explanation":["구성원은 누구일까요?","셋 모두예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#7','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',3,'mc','auto','도서관 꾸미기의 걸음을 세 사례의 걸음에 맞추면 「설문 조사」는 어느 걸음인가요?',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"mc","stem":"도서관 꾸미기의 걸음을 세 사례의 걸음에 맞추면 「설문 조사」는 어느 걸음인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"회의로 정하기","mis":"SO4-2-u1-X11"},{"t":"함께 실천하기","mis":"SO4-2-u1-X11"},{"t":"걸음과 관계없어요","mis":"SO4-2-u1-X11"}],"explanation":["원하는 모습을 물었어요.","생각을 모았어요.","의견 모으기예요."],"asset":{"type":"passage","lines":["학교 도서관을 새롭게 꾸미기로 했다.","먼저 학생·교사·학부모에게 원하는 도서관 모습을 설문 조사했다.","설문 결과를 바탕으로 회의를 열어 모습을 정하고 새롭게 꾸몄다."],"title":"도서관 꾸미기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#8','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',4,'mc','auto','세 사례와 도서관 꾸미기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X11','SO4-2-u1-X09']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C3","difficulty":4,"kind":"mc","stem":"세 사례와 도서관 꾸미기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학교의 일은 달라도 구성원의 의견을 모아 함께 정하고 실천하는 모습은 같아요","correct":true},{"t":"학교의 일마다 민주주의의 뜻이 달라져요","mis":"SO4-2-u1-X11"},{"t":"학교의 일은 한 사람이 정하는 게 빨라요","mis":"SO4-2-u1-X09"},{"t":"학생은 학교의 일에 참여할 수 없어요","mis":"SO4-2-u1-X09"}],"explanation":["한 일은 여러 가지예요.","걸음을 봐요.","모습이 같아요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#9','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',4,'mc','auto','학생 자치회가 학교에 꼭 필요한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X10','SO4-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C3","difficulty":4,"kind":"mc","stem":"학생 자치회가 학교에 꼭 필요한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생들의 대표로서 학생들의 의견을 학교에 전해 학교의 일에 반영되게 하기 때문이에요","correct":true},{"t":"학생들의 의견을 대신 정해 버리기 때문이에요","mis":"SO4-2-u1-X10"},{"t":"선생님 대신 수업을 하기 때문이에요","mis":"SO4-2-u1-X10"},{"t":"학교의 일은 학생 자치회만 정하기 때문이에요","mis":"SO4-2-u1-X09"}],"explanation":["누구의 대표일까요?","의견을 전해요.","반영되게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L03_challenge#10','soc',4,2,'u1','L03','g4_2_soc_u1_L03_challenge','lesson_challenge','SO4-2-u1-C3',4,'essay','teacher','세 사례 가운데 하나를 골라, 그 사례가 왜 민주주의를 실천한 것인지 세 걸음과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C3","difficulty":4,"kind":"essay","stem":"세 사례 가운데 하나를 골라, 그 사례가 왜 민주주의를 실천한 것인지 세 걸음과 이어 쓰세요.","answer_guide":{"answer":"예: 학생 참여 예산제 사례를 골랐어요. 학급별로 필요한 사업을 제안받아 의견을 모았고, 전교 회의에서 토의해 우산 빗물 제거기를 설치하기로 정했으며, 실제로 건물 앞에 설치했어요. 학생들의 의견을 모아 함께 정하고 실천했으니 민주주의를 실천한 것이에요.","scoring_points":["사례 하나를 골랐는가","세 걸음을 사례와 이어 썼는가","민주주의 실천과 연결했는가"]},"explanation":["하나를 골라요.","세 걸음을 찾아요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 학생 자치회 — 의견을 모아 3월 행사를 「욕설 없는 학교 만들기」로 정하고 모두 참여했다.","㉡ 학교 구성원 전체 회의 — 학생·교사·학부모의 의견을 모아 회의로 정하고 실천했다.","㉢ 학생 참여 예산제 — 학급별 제안을 전교 회의에서 토의해 우산 빗물 제거기를 설치했다."],"title":"학교에서 민주주의를 실천한 세 사례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#1','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',1,'mc','auto','학교에서 일어나는 여러 가지 일은 어떻게 해결하는 것이 바람직한가요?',ARRAY['SO4-2-u1-X13','SO4-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"mc","stem":"학교에서 일어나는 여러 가지 일은 어떻게 해결하는 것이 바람직한가요?","options":[{"t":"학교 구성원이 참여해 민주적인 방법으로 해결해요","correct":true},{"t":"가장 힘센 사람이 정해요","mis":"SO4-2-u1-X13"},{"t":"가장 먼저 말한 사람이 정해요","mis":"SO4-2-u1-X13"},{"t":"해결하지 않고 그냥 둬요","mis":"SO4-2-u1-X15"}],"explanation":["구성원이 참여해요.","민주적인 방법이에요.","함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#2','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',1,'sa','auto','놀이터 문제를 해결할 때 학교 구성원이 원하는 놀이기구를 묻는 데 쓴 방법은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"sa","stem":"놀이터 문제를 해결할 때 학교 구성원이 원하는 놀이기구를 묻는 데 쓴 방법은 무엇인가요? 네 글자로 쓰세요.","answer":["설문조사","설문 조사"],"explanation":["여러 사람에게 물어요.","설문◯◯예요.","설문조사예요."],"mis":"SO4-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#3','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',1,'ox','auto','학교에 해결하고 싶은 일이 있을 때는 해결 방안을 먼저 결정해야 해요.',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"ox","stem":"학교에 해결하고 싶은 일이 있을 때는 해결 방안을 먼저 결정해야 해요.","answer":"X","reason_options":[{"t":"해결하고 싶은 일을 먼저 확인해야 알맞은 방안을 찾을 수 있기 때문에","correct":true},{"t":"방안을 먼저 정하면 문제가 저절로 사라지기 때문에","mis":"SO4-2-u1-X12"}],"mis":"SO4-2-u1-X12","explanation":["무엇이 먼저일까요?","일을 확인해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#4','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',1,'mc','auto','놀이터에서 학생들이 해결하고 싶었던 일은 무엇인가요?',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"mc","stem":"놀이터에서 학생들이 해결하고 싶었던 일은 무엇인가요?","options":[{"t":"오래되어 위험한 놀이기구가 많고 바닥이 움푹 파인 것","correct":true},{"t":"놀이터가 너무 새것인 것","mis":"SO4-2-u1-X12"},{"t":"놀이기구가 너무 안전한 것","mis":"SO4-2-u1-X12"},{"t":"운동장에 나무가 많은 것","mis":"SO4-2-u1-X12"}],"explanation":["오래되었어요.","위험해요.","바닥도 파였어요."],"asset":{"type":"passage","lines":["문제 — 놀이터가 오래되어 위험한 놀이기구가 많고, 모래 바닥이 움푹 파였다.","방안 ㉠ 안전한 놀이기구로 바꾸기","방안 ㉡ 넘어져도 다치지 않는 바닥으로 바꾸기","방안 ㉢ 놀이터 이용 규칙 세우기"],"title":"우리 학교 놀이터 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#5','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',2,'mc','auto','해결 방안을 탐색할 때 생각할 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X13']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"mc","stem":"해결 방안을 탐색할 때 생각할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"최대한 많은 학교 구성원이 만족할 수 있는지 생각해요","correct":true},{"t":"가장 빨리 끝나는 방안만 생각해요","mis":"SO4-2-u1-X13"},{"t":"한 사람만 좋아하는 방안을 골라요","mis":"SO4-2-u1-X13"},{"t":"돈이 가장 많이 드는 방안을 골라요","mis":"SO4-2-u1-X13"}],"explanation":["누가 만족하나요?","많은 구성원이에요.","그것을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#6','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',2,'match','auto','놀이터 해결 방안과 그것을 정한 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"match","stem":"놀이터 해결 방안과 그것을 정한 방법을 알맞게 이으세요.","pairs":[{"l":"놀이기구와 바닥 소재 정하기","r":"설문조사"},{"l":"놀이터 이용 규칙 세우기","r":"학급 회의"},{"l":"바꾼 놀이터를 함께 살피기","r":"학생·교사·학부모가 모이는 회의"}],"mis":"SO4-2-u1-X14","explanation":["놀이기구와 바닥은 물어봤어요.","규칙은 학급에서 정했어요.","그 뒤 모두 모였어요."],"asset":{"type":"passage","lines":["문제 — 놀이터가 오래되어 위험한 놀이기구가 많고, 모래 바닥이 움푹 파였다.","방안 ㉠ 안전한 놀이기구로 바꾸기","방안 ㉡ 넘어져도 다치지 않는 바닥으로 바꾸기","방안 ㉢ 놀이터 이용 규칙 세우기"],"title":"우리 학교 놀이터 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#7','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',2,'blank','auto','실천 결과를 확인할 때는 문제를 해결하기 전과 (    )를 비교해 달라진 부분을 확인해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X15']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"blank","stem":"실천 결과를 확인할 때는 문제를 해결하기 전과 (    )를 비교해 달라진 부분을 확인해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"후","correct":true},{"t":"처음","mis":"SO4-2-u1-X15"},{"t":"옛날","mis":"SO4-2-u1-X15"},{"t":"계획","mis":"SO4-2-u1-X15"}],"explanation":["전의 짝이에요.","해결한 다음이에요.","후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#8','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',2,'ox','auto','놀이터 바닥을 바꿀 때 설문조사를 한 까닭은 모래 바닥을 더 좋아하는 학생도 있을 수 있기 때문이에요.',ARRAY['SO4-2-u1-X14']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"ox","stem":"놀이터 바닥을 바꿀 때 설문조사를 한 까닭은 모래 바닥을 더 좋아하는 학생도 있을 수 있기 때문이에요.","answer":"O","reason_options":[{"t":"구성원들이 원하는 것을 물어 많은 사람이 만족하도록 정하려 했기 때문에","correct":true},{"t":"설문조사는 언제나 회의보다 낫기 때문에","mis":"SO4-2-u1-X14"}],"mis":"SO4-2-u1-X14","explanation":["좋아하는 바닥이 달라요.","물어봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#9','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',2,'mc','auto','「학생 자치회가 학급 회의에서 나온 의견을 모아 규칙을 정하고 알렸다」는 다섯 걸음 가운데 어디에 가까운가요?',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"mc","stem":"「학생 자치회가 학급 회의에서 나온 의견을 모아 규칙을 정하고 알렸다」는 다섯 걸음 가운데 어디에 가까운가요?","options":[{"t":"해결 방안 실천하기","correct":true},{"t":"해결하고 싶은 일 확인하기","mis":"SO4-2-u1-X12"},{"t":"해결 방안 탐색하기","mis":"SO4-2-u1-X12"},{"t":"실천 결과 확인하기","mis":"SO4-2-u1-X12"}],"explanation":["규칙을 정했어요.","잘 지키도록 알렸어요.","실천하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_basic#10','soc',4,2,'u1','L04','g4_2_soc_u1_L04_basic','lesson_basic','SO4-2-u1-C4',3,'mc','auto','차례가 섞인 다섯 걸음을 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"mc","stem":"차례가 섞인 다섯 걸음을 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"나 → 라 → 다 → 마 → 가","correct":true},{"t":"다 → 나 → 라 → 마 → 가","mis":"SO4-2-u1-X12"},{"t":"나 → 다 → 라 → 가 → 마","mis":"SO4-2-u1-X12"},{"t":"가 → 나 → 다 → 라 → 마","mis":"SO4-2-u1-X12"}],"explanation":["일을 먼저 확인해요.","방안을 찾고 정해요.","실천하고 확인해요."],"asset":{"type":"passage","lines":["가. 실천 결과 확인하기","나. 해결하고 싶은 일 확인하기","다. 민주적인 방법으로 해결 방안 결정하기","라. 해결 방안 탐색하기","마. 해결 방안 실천하기"],"title":"차례가 섞인 다섯 걸음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#1','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',2,'mc','auto','실천 결과를 확인하는 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"mc","stem":"실천 결과를 확인하는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"새 규칙을 더 많은 학생이 만족하도록 고쳐 나가요","correct":true},{"t":"아쉬운 점은 못 본 척해요","mis":"SO4-2-u1-X15"},{"t":"결과를 아무에게도 묻지 않아요","mis":"SO4-2-u1-X15"},{"t":"다른 학교의 일만 살펴요","mis":"SO4-2-u1-X15"}],"explanation":["결과를 살펴요.","아쉬운 점이 있어요.","보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#2','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',2,'ox','auto','해결 방안을 찾을 때는 문제의 원인이 무엇인지 생각해 보고 원인에 따른 방안을 찾아요.',ARRAY['SO4-2-u1-X13']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"ox","stem":"해결 방안을 찾을 때는 문제의 원인이 무엇인지 생각해 보고 원인에 따른 방안을 찾아요.","answer":"O","reason_options":[{"t":"원인에 맞는 방안이어야 문제를 제대로 해결할 수 있기 때문에","correct":true},{"t":"원인은 해결과 관계가 없기 때문에","mis":"SO4-2-u1-X13"}],"mis":"SO4-2-u1-X13","explanation":["왜 생겼을까요?","원인을 찾아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#3','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',3,'mc','auto','놀이터 문제에서 정하는 방법이 설문조사와 학급 회의 두 갈래로 나뉜 까닭은 무엇인가요?',ARRAY['SO4-2-u1-X14']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"mc","stem":"놀이터 문제에서 정하는 방법이 설문조사와 학급 회의 두 갈래로 나뉜 까닭은 무엇인가요?","options":[{"t":"무엇을 정하느냐에 따라 알맞은 방법이 달랐기 때문이에요","correct":true},{"t":"설문조사가 학급 회의보다 언제나 낫기 때문이에요","mis":"SO4-2-u1-X14"},{"t":"세 방안 가운데 하나만 실천했기 때문이에요","mis":"SO4-2-u1-X14"},{"t":"정하는 방법은 한 가지뿐이기 때문이에요","mis":"SO4-2-u1-X14"}],"explanation":["놀이기구는 물어봤어요.","규칙은 회의했어요.","정할 것이 달랐어요."],"asset":{"type":"passage","lines":["문제 — 놀이터가 오래되어 위험한 놀이기구가 많고, 모래 바닥이 움푹 파였다.","방안 ㉠ 안전한 놀이기구로 바꾸기","방안 ㉡ 넘어져도 다치지 않는 바닥으로 바꾸기","방안 ㉢ 놀이터 이용 규칙 세우기"],"title":"우리 학교 놀이터 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#4','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',3,'error','auto','놀이터 해결 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X15','SO4-2-u1-X14','SO4-2-u1-X09']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"error","stem":"놀이터 해결 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「규칙을 정해 알렸으니 결과는 확인하지 않아도 돼.」","correct":true,"mis_target":"SO4-2-u1-X15"},{"t":"친구 가 — 「세 방안 모두 버리지 않고 실천했어.」","mis":"SO4-2-u1-X14"},{"t":"친구 다 — 「학생·교사·학부모가 모이는 회의가 열렸어.」","mis":"SO4-2-u1-X09"}],"explanation":["실천하면 끝일까요?","결과를 확인해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["문제 — 놀이터가 오래되어 위험한 놀이기구가 많고, 모래 바닥이 움푹 파였다.","방안 ㉠ 안전한 놀이기구로 바꾸기","방안 ㉡ 넘어져도 다치지 않는 바닥으로 바꾸기","방안 ㉢ 놀이터 이용 규칙 세우기"],"title":"우리 학교 놀이터 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#5','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',3,'mc','auto','학교 이름을 바꾸는 일에서 학생들이 한 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X12','SO4-2-u1-X15']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"mc","stem":"학교 이름을 바꾸는 일에서 학생들이 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"도움을 청하는 편지를 보내고 서명 운동을 벌였어요","correct":true},{"t":"혼자 이름을 정해 간판을 바꿨어요","mis":"SO4-2-u1-X12"},{"t":"아무 동의 없이 이름을 바꿨어요","mis":"SO4-2-u1-X12"},{"t":"아무 일도 하지 않고 기다렸어요","mis":"SO4-2-u1-X15"}],"explanation":["여러 사람의 힘이 필요했어요.","편지를 보냈어요.","서명 운동도 했어요."],"asset":{"type":"passage","lines":["○○ 초등학교 학생들은 학교 이름을 바꾸고 싶었다.","학부모·졸업생·지역 주민의 동의와 교육청의 허가가 있어야 하는 일이었다.","한 학생이 임원 선거에서 이를 공약으로 내세워 당선되며 활동이 시작됐다.","학생들은 도움을 청하는 편지를 보내고 서명 운동을 벌였다.","추진 위원회가 만들어지고 민주적인 절차를 거쳐 이름이 바뀌었다."],"title":"학교 이름을 바꾼 학생들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#6','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',3,'ox','auto','학교 이름은 학생들만 원하면 바로 바꿀 수 있었어요.',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"ox","stem":"학교 이름은 학생들만 원하면 바로 바꿀 수 있었어요.","answer":"X","reason_options":[{"t":"학부모·졸업생·지역 주민의 동의와 교육청의 허가가 있어야 했기 때문에","correct":true},{"t":"학생 자치회가 모든 것을 정할 수 있기 때문에","mis":"SO4-2-u1-X12"}],"mis":"SO4-2-u1-X12","explanation":["누구의 동의가 필요했나요?","허가도 필요했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["○○ 초등학교 학생들은 학교 이름을 바꾸고 싶었다.","학부모·졸업생·지역 주민의 동의와 교육청의 허가가 있어야 하는 일이었다.","한 학생이 임원 선거에서 이를 공약으로 내세워 당선되며 활동이 시작됐다.","학생들은 도움을 청하는 편지를 보내고 서명 운동을 벌였다.","추진 위원회가 만들어지고 민주적인 절차를 거쳐 이름이 바뀌었다."],"title":"학교 이름을 바꾼 학생들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#7','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',3,'mc','auto','해결 방안의 장단점을 생각하는 걸음은 다섯 걸음 가운데 어디인가요?',ARRAY['SO4-2-u1-X12','SO4-2-u1-X13']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"mc","stem":"해결 방안의 장단점을 생각하는 걸음은 다섯 걸음 가운데 어디인가요?","options":[{"t":"해결 방안 탐색하기","correct":true},{"t":"해결하고 싶은 일 확인하기","mis":"SO4-2-u1-X12"},{"t":"해결 방안 실천하기","mis":"SO4-2-u1-X12"},{"t":"실천 결과 확인하기","mis":"SO4-2-u1-X13"}],"explanation":["여러 방안을 찾아요.","좋은 점·아쉬운 점을 따져요.","탐색하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#8','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',4,'mc','auto','놀이터 사례에서 정하는 방법은 둘로 나뉘었지만 실천은 함께한 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X14','SO4-2-u1-X07','SO4-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C4","difficulty":4,"kind":"mc","stem":"놀이터 사례에서 정하는 방법은 둘로 나뉘었지만 실천은 함께한 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"정하는 방법은 일에 따라 달라도 정한 뒤에는 구성원이 함께 실천하고 결과를 확인해요","correct":true},{"t":"두 방법 가운데 하나는 쓸모가 없었어요","mis":"SO4-2-u1-X14"},{"t":"실천은 한 사람이 맡으면 돼요","mis":"SO4-2-u1-X07"},{"t":"결과는 확인하지 않아도 돼요","mis":"SO4-2-u1-X15"}],"explanation":["두 갈래로 정했어요.","실천은 함께했어요.","결과도 함께 봐요."],"asset":{"type":"passage","lines":["문제 — 놀이터가 오래되어 위험한 놀이기구가 많고, 모래 바닥이 움푹 파였다.","방안 ㉠ 안전한 놀이기구로 바꾸기","방안 ㉡ 넘어져도 다치지 않는 바닥으로 바꾸기","방안 ㉢ 놀이터 이용 규칙 세우기"],"title":"우리 학교 놀이터 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#9','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',4,'mc','auto','학교 이름을 바꾼 사례가 민주주의를 실천한 사례인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X12','SO4-2-u1-X13']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C4","difficulty":4,"kind":"mc","stem":"학교 이름을 바꾼 사례가 민주주의를 실천한 사례인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학생이 시작한 일을 여러 사람의 동의를 얻어 민주적인 절차로 해결했기 때문이에요","correct":true},{"t":"학생 한 명이 혼자 결정했기 때문이에요","mis":"SO4-2-u1-X12"},{"t":"이름을 아주 빨리 바꿨기 때문이에요","mis":"SO4-2-u1-X13"},{"t":"동의가 필요 없는 일이었기 때문이에요","mis":"SO4-2-u1-X12"}],"explanation":["학생이 시작했어요.","힘을 모았어요.","절차를 거쳤어요."],"asset":{"type":"passage","lines":["○○ 초등학교 학생들은 학교 이름을 바꾸고 싶었다.","학부모·졸업생·지역 주민의 동의와 교육청의 허가가 있어야 하는 일이었다.","한 학생이 임원 선거에서 이를 공약으로 내세워 당선되며 활동이 시작됐다.","학생들은 도움을 청하는 편지를 보내고 서명 운동을 벌였다.","추진 위원회가 만들어지고 민주적인 절차를 거쳐 이름이 바뀌었다."],"title":"학교 이름을 바꾼 학생들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L04_challenge#10','soc',4,2,'u1','L04','g4_2_soc_u1_L04_challenge','lesson_challenge','SO4-2-u1-C4',4,'essay','teacher','우리 학교에서 해결하고 싶은 일을 하나 정해, 다섯 걸음 가운데 「해결 방안 탐색하기」와 「민주적인 방법으로 결정하기」를 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C4","difficulty":4,"kind":"essay","stem":"우리 학교에서 해결하고 싶은 일을 하나 정해, 다섯 걸음 가운데 「해결 방안 탐색하기」와 「민주적인 방법으로 결정하기」를 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 비 오는 날 복도가 미끄러운 일을 해결하고 싶어요. 미끄럼 방지 매트 깔기, 우산 비닐 쓰기 같은 방안을 찾아 장단점을 따지고, 학급 회의에서 의견을 모은 뒤 학생 자치회 회의에서 함께 정할 거예요.","scoring_points":["해결하고 싶은 일을 정했는가","여러 방안을 찾고 장단점을 생각했는가","민주적인 결정 방법을 썼는가"]},"explanation":["일을 정해요.","방안을 찾아요.","정하는 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#1','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',1,'mc','auto','학생 자치회 임원이 지켜야 할 태도로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X17']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"mc","stem":"학생 자치회 임원이 지켜야 할 태도로 알맞은 것은 무엇인가요?","options":[{"t":"학생들의 생각을 최대한 반영하도록 노력해요","correct":true},{"t":"자기 생각대로만 정해요","mis":"SO4-2-u1-X17"},{"t":"학생들의 의견은 듣지 않아요","mis":"SO4-2-u1-X17"},{"t":"활동에 참여하지 않아요","mis":"SO4-2-u1-X17"}],"explanation":["누구의 대표일까요?","학생들이에요.","생각을 반영해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#2','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',1,'sa','auto','교과서 예시 계획에서 3~4월 행사의 목표는 「사이좋은 친구 사이 ○○○」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"sa","stem":"교과서 예시 계획에서 3~4월 행사의 목표는 「사이좋은 친구 사이 ○○○」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["만들기"],"explanation":["목표를 이루려고 해요.","◯◯기예요.","만들기예요."],"asset":{"type":"passage","lines":["3~4월 — 우정 표어 공모전 · 바른 말 사용 캠페인","5~6월 — 분리수거 도우미 활동 · 학교 공간 꾸미기 공모전","7~8월 — 등하교 안전 도우미 활동 · 학교 시설 안전 이용 규칙 홍보"],"title":"학생 자치회 월별 행사 계획(교과서 예시)"},"mis":"SO4-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#3','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',1,'ox','auto','학교 행사를 계획할 때는 그 행사로 얻을 수 있는 결과도 함께 생각해요.',ARRAY['SO4-2-u1-X16']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"ox","stem":"학교 행사를 계획할 때는 그 행사로 얻을 수 있는 결과도 함께 생각해요.","answer":"O","reason_options":[{"t":"형식적인 행사가 아니라 의미 있는 행사를 하기 위해서이기 때문에","correct":true},{"t":"행사는 이름만 멋있으면 되기 때문에","mis":"SO4-2-u1-X16"}],"mis":"SO4-2-u1-X16","explanation":["내용만 볼까요?","얻는 것도 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#4','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',1,'mc','auto','민주주의의 의미로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"mc","stem":"민주주의의 의미로 알맞은 것은 무엇인가요?","options":[{"t":"구성원들의 다양한 의견을 반영해 사회 공동의 문제를 결정하는 방식","correct":true},{"t":"힘이 센 사람의 뜻대로 정하는 방식","mis":"SO4-2-u1-X01"},{"t":"가장 먼저 말한 사람의 뜻대로 정하는 방식","mis":"SO4-2-u1-X01"},{"t":"아무도 정하지 않고 두는 방식","mis":"SO4-2-u1-X01"}],"explanation":["다양한 의견이에요.","함께 결정해요.","그 방식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
