INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#6','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',2,'match','auto','월별 목표와 행사를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C5","difficulty":2,"kind":"match","stem":"월별 목표와 행사를 알맞게 이으세요.","pairs":[{"l":"사이좋은 친구 사이 만들기","r":"바른 말 사용 캠페인"},{"l":"깨끗한 학교 만들기","r":"분리수거 도우미 활동"},{"l":"안전한 학교 만들기","r":"등하교 안전 도우미 활동"}],"mis":"SO4-2-u1-X16","explanation":["친구 사이는 말이에요.","깨끗함은 분리수거예요.","안전은 등하교예요."],"asset":{"type":"passage","lines":["3~4월 — 우정 표어 공모전 · 바른 말 사용 캠페인","5~6월 — 분리수거 도우미 활동 · 학교 공간 꾸미기 공모전","7~8월 — 등하교 안전 도우미 활동 · 학교 시설 안전 이용 규칙 홍보"],"title":"학생 자치회 월별 행사 계획(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#7','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',2,'mc','auto','학생 자치회 임원의 태도로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C5","difficulty":2,"kind":"mc","stem":"학생 자치회 임원의 태도로 알맞지 않은 것은 무엇인가요?","options":[{"t":"학생들에게 묻지 않고 임원끼리만 정해요","correct":true},{"t":"학생들과 민주적으로 의사소통해요","mis":"SO4-2-u1-X17"},{"t":"학생 자치회 활동에 적극적으로 참여해요","mis":"SO4-2-u1-X17"},{"t":"학생들의 생각을 최대한 반영해요","mis":"SO4-2-u1-X17"}],"explanation":["세 태도를 떠올려요.","묻지 않으면 어떨까요?","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#8','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',2,'blank','auto','민주주의란 모두가 (    ) 입장에서 함께 만들어 가는 것이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X04']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C5","difficulty":2,"kind":"blank","stem":"민주주의란 모두가 (    ) 입장에서 함께 만들어 가는 것이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"평등한","correct":true},{"t":"높은","mis":"SO4-2-u1-X04"},{"t":"바쁜","mis":"SO4-2-u1-X04"},{"t":"다른 사람의","mis":"SO4-2-u1-X04"}],"explanation":["누구나 같아요.","차별이 없어요.","평등한이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_basic#9','soc',4,2,'u1','L05','g4_2_soc_u1_L05_basic','lesson_basic','SO4-2-u1-C5',2,'ox','auto','「민주주의는 우리의 자유와 평등을 지켜 줘요」는 민주주의의 중요성을 나타낸 말이에요.',ARRAY['SO4-2-u1-X04']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C5","difficulty":2,"kind":"ox","stem":"「민주주의는 우리의 자유와 평등을 지켜 줘요」는 민주주의의 중요성을 나타낸 말이에요.","answer":"O","reason_options":[{"t":"민주주의 사회에서는 모두가 존중받고 자유롭고 평등하게 의견을 말하기 때문에","correct":true},{"t":"민주주의는 한 사람만 자유롭게 하기 때문에","mis":"SO4-2-u1-X04"}],"mis":"SO4-2-u1-X04","explanation":["자유가 있어요.","평등도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
