INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#2','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',2,'ox','auto','해마다 하던 행사는 그대로 하면 되므로 살펴볼 필요가 없어요.',ARRAY['SO4-2-u1-X16']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C5","difficulty":2,"kind":"ox","stem":"해마다 하던 행사는 그대로 하면 되므로 살펴볼 필요가 없어요.","answer":"X","reason_options":[{"t":"행사로 얻을 수 있는 결과를 생각해 의미 있는 행사인지 살펴야 하기 때문에","correct":true},{"t":"해마다 하던 행사는 언제나 가장 좋기 때문에","mis":"SO4-2-u1-X16"}],"mis":"SO4-2-u1-X16","explanation":["그대로 해도 될까요?","얻는 것을 살펴요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#3','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',3,'mc','auto','학생 자치회 임원이 행사를 정할 때 민주적으로 의사소통하는 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X17','SO4-2-u1-X16','SO4-2-u1-X05']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"mc","stem":"학생 자치회 임원이 행사를 정할 때 민주적으로 의사소통하는 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학급마다 원하는 행사를 묻고 그 의견을 모아 함께 정해요","correct":true},{"t":"임원이 좋아하는 행사로 바로 정해요","mis":"SO4-2-u1-X17"},{"t":"작년 행사를 묻지 않고 그대로 해요","mis":"SO4-2-u1-X16"},{"t":"가장 큰 목소리로 말한 행사로 정해요","mis":"SO4-2-u1-X05"}],"explanation":["누구에게 물을까요?","학생들이에요.","모아서 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#4','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',3,'error','auto','월별 행사 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X16','SO4-2-u1-X17']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"error","stem":"월별 행사 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「행사 이름이 멋있으면 무엇을 얻는지는 생각하지 않아도 돼.」","correct":true,"mis_target":"SO4-2-u1-X16"},{"t":"친구 가 — 「같은 목표의 행사를 묶어 계획했어.」","mis":"SO4-2-u1-X16"},{"t":"친구 나 — 「학생들의 생각을 반영해서 정해야 해.」","mis":"SO4-2-u1-X17"}],"explanation":["이름이 중요할까요?","얻는 것이 중요해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["3~4월 — 우정 표어 공모전 · 바른 말 사용 캠페인","5~6월 — 분리수거 도우미 활동 · 학교 공간 꾸미기 공모전","7~8월 — 등하교 안전 도우미 활동 · 학교 시설 안전 이용 규칙 홍보"],"title":"학생 자치회 월별 행사 계획(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#5','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',3,'mc','auto','「우정 표어 공모전」을 계획할 때 생각할 「얻는 것」으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"mc","stem":"「우정 표어 공모전」을 계획할 때 생각할 「얻는 것」으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구끼리 서로 아끼는 마음이 커져요","correct":true},{"t":"복도가 깨끗해져요","mis":"SO4-2-u1-X16"},{"t":"등굣길이 안전해져요","mis":"SO4-2-u1-X16"},{"t":"행사 이름이 길어져요","mis":"SO4-2-u1-X16"}],"explanation":["우정이에요.","친구 사이예요.","아끼는 마음이에요."],"asset":{"type":"passage","lines":["3~4월 — 우정 표어 공모전 · 바른 말 사용 캠페인","5~6월 — 분리수거 도우미 활동 · 학교 공간 꾸미기 공모전","7~8월 — 등하교 안전 도우미 활동 · 학교 시설 안전 이용 규칙 홍보"],"title":"학생 자치회 월별 행사 계획(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#6','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',3,'ox','auto','학교생활 속 민주주의에서 학생은 학교의 일을 결정하는 데 참여할 수 없어요.',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"ox","stem":"학교생활 속 민주주의에서 학생은 학교의 일을 결정하는 데 참여할 수 없어요.","answer":"X","reason_options":[{"t":"학생도 학교 구성원으로서 의견을 내고 함께 결정하기 때문에","correct":true},{"t":"학교의 일은 어른만 정하기 때문에","mis":"SO4-2-u1-X09"}],"mis":"SO4-2-u1-X09","explanation":["학생 자치회가 있어요.","학생도 구성원이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#7','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',3,'mc','auto','민주주의의 의미와 중요성을 그림으로 나타낼 때 가장 어울리는 장면은 무엇인가요?',ARRAY['SO4-2-u1-X01','SO4-2-u1-X02','SO4-2-u1-X05']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"mc","stem":"민주주의의 의미와 중요성을 그림으로 나타낼 때 가장 어울리는 장면은 무엇인가요?","options":[{"t":"여러 친구가 둥글게 앉아 차례로 의견을 말하는 장면","correct":true},{"t":"한 친구가 혼자 단상에서 명령하는 장면","mis":"SO4-2-u1-X01"},{"t":"몇몇만 의견을 내고 나머지는 듣지 못하는 장면","mis":"SO4-2-u1-X02"},{"t":"다른 의견에 귀를 막는 장면","mis":"SO4-2-u1-X05"}],"explanation":["누가 말하나요?","모두 말해요.","평등하게 둘러앉았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#8','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',4,'mc','auto','「학교생활 속 민주주의」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X17','SO4-2-u1-X09','SO4-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C5","difficulty":4,"kind":"mc","stem":"「학교생활 속 민주주의」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"다양한 의견을 존중하며 대화하고, 학생·교사·학부모가 함께 정해 실천하면 더 나은 학교를 만들 수 있어요","correct":true},{"t":"학교의 일은 학생 자치회 임원만 정하면 돼요","mis":"SO4-2-u1-X17"},{"t":"민주주의는 학교와 관계가 없어요","mis":"SO4-2-u1-X09"},{"t":"정한 뒤에는 결과를 살피지 않아도 돼요","mis":"SO4-2-u1-X15"}],"explanation":["의미와 태도예요.","함께 정해요.","실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#9','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',4,'mc','auto','행사 둘을 나란히 놓아야 그 자리의 목표가 보이는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X16']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C5","difficulty":4,"kind":"mc","stem":"행사 둘을 나란히 놓아야 그 자리의 목표가 보이는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"두 행사가 함께 얻는 것이 무엇인지는 둘을 견주어 보아야 알 수 있기 때문이에요","correct":true},{"t":"행사가 하나면 이름을 붙일 수 없게 정해져 있기 때문이에요","mis":"SO4-2-u1-X16"},{"t":"목표는 행사 이름 안에 다 적혀 있기 때문이에요","mis":"SO4-2-u1-X16"},{"t":"행사는 많을수록 좋기 때문이에요","mis":"SO4-2-u1-X16"}],"explanation":["하나만 보면 몰라요.","둘을 견줘요.","함께 얻는 것이 보여요."],"asset":{"type":"passage","lines":["3~4월 — 우정 표어 공모전 · 바른 말 사용 캠페인","5~6월 — 분리수거 도우미 활동 · 학교 공간 꾸미기 공모전","7~8월 — 등하교 안전 도우미 활동 · 학교 시설 안전 이용 규칙 홍보"],"title":"학생 자치회 월별 행사 계획(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L05_challenge#10','soc',4,2,'u1','L05','g4_2_soc_u1_L05_challenge','lesson_challenge','SO4-2-u1-C5',4,'essay','teacher','내가 학생 자치회 임원이라면 9~10월에 할 행사를 하나 계획하고, 그 행사로 얻을 수 있는 것과 임원으로서 지킬 태도를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C5","difficulty":4,"kind":"essay","stem":"내가 학생 자치회 임원이라면 9~10월에 할 행사를 하나 계획하고, 그 행사로 얻을 수 있는 것과 임원으로서 지킬 태도를 쓰세요.","answer_guide":{"answer":"예: 9~10월에 「책 나눔 장터」를 열고 싶어요. 읽은 책을 서로 나누며 책 읽는 즐거움이 커지는 학교를 만들 수 있어요. 학급마다 원하는 행사를 먼저 묻고 학생들의 생각을 최대한 반영할 거예요.","scoring_points":["행사를 계획했는가","행사로 얻는 것을 썼는가","임원의 태도를 썼는가"]},"explanation":["행사를 정해요.","얻는 것을 써요.","태도를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#1','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',1,'mc','auto','주민이 지역의 주인으로서 지역의 일에 참여하여 함께 문제를 해결해 나가는 것을 무엇이라고 하나요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"mc","stem":"주민이 지역의 주인으로서 지역의 일에 참여하여 함께 문제를 해결해 나가는 것을 무엇이라고 하나요?","options":[{"t":"주민 자치","correct":true},{"t":"학생 자치","mis":"SO4-2-u1-X18"},{"t":"민주주의 회의","mis":"SO4-2-u1-X18"},{"t":"지역 축제","mis":"SO4-2-u1-X18"}],"explanation":["지역의 주인은 주민이에요.","스스로 다스려요.","주민 자치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#2','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',1,'sa','auto','포스터에서 주민 자치회 위원을 신청하려면 ○○동 행정 복지 ○○로 방문해야 해요. 뒤의 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"sa","stem":"포스터에서 주민 자치회 위원을 신청하려면 ○○동 행정 복지 ○○로 방문해야 해요. 뒤의 ○○에 알맞은 두 글자를 쓰세요.","answer":["센터"],"explanation":["공공 기관이에요.","◯터예요.","센터예요."],"asset":{"type":"passage","lines":["더 나은 우리 지역을 만들 주민 자치회 위원을 모집합니다.","○○동 주민이면 누구나 참여할 수 있어요.","○○동을 위한 의견을 제시해 주세요.","○○동 행정 복지 센터로 방문하여 신청해 주세요."],"title":"게시판의 포스터"},"mis":"SO4-2-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#3','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',1,'ox','auto','포스터를 보면 ○○동 주민이면 누구나 주민 자치회에 참여할 수 있어요.',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"ox","stem":"포스터를 보면 ○○동 주민이면 누구나 주민 자치회에 참여할 수 있어요.","answer":"O","reason_options":[{"t":"포스터에 주민이면 누구나 참여할 수 있다고 했기 때문에","correct":true},{"t":"주민 자치회에는 정해진 몇 사람만 들어갈 수 있기 때문에","mis":"SO4-2-u1-X19"}],"mis":"SO4-2-u1-X19","explanation":["포스터를 읽어요.","누구나라고 했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["더 나은 우리 지역을 만들 주민 자치회 위원을 모집합니다.","○○동 주민이면 누구나 참여할 수 있어요.","○○동을 위한 의견을 제시해 주세요.","○○동 행정 복지 센터로 방문하여 신청해 주세요."],"title":"게시판의 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#4','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',1,'mc','auto','신문 기사에서 ○○동 주민 자치회가 시작한 사업은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"mc","stem":"신문 기사에서 ○○동 주민 자치회가 시작한 사업은 무엇인가요?","options":[{"t":"어두운 골목길을 밝히는 사업","correct":true},{"t":"도로를 넓히는 사업","mis":"SO4-2-u1-X18"},{"t":"다른 지역에 가게를 여는 사업","mis":"SO4-2-u1-X18"},{"t":"나무를 옮겨 심는 사업","mis":"SO4-2-u1-X18"}],"explanation":["밤이 어두웠어요.","가로등을 설치했어요.","골목길을 밝혀요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 어두운 골목길 밝히기 사업을 시작했다.","지역 입구와 골목길 곳곳에 태양광을 활용한 가로등을 설치했다.","주민들이 밤에도 안전하게 다니고, 지역의 밤 풍경도 아름답게 변하고 있다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#5','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',2,'mc','auto','주민 자치회에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X19','SO4-2-u1-X18']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"mc","stem":"주민 자치회에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"지역 주민을 대표하는 기구로 주민 자치 활동을 운영하고 지원해요","correct":true},{"t":"학생들의 대표가 모인 모임이에요","mis":"SO4-2-u1-X19"},{"t":"다른 지역 사람들이 대신 정하는 모임이에요","mis":"SO4-2-u1-X18"},{"t":"몇몇 주민이 지역의 일을 모두 정하는 모임이에요","mis":"SO4-2-u1-X18"}],"explanation":["주민의 대표예요.","활동을 운영해요.","지원도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#6','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',2,'match','auto','학교와 지역에서 비슷한 일을 하는 것끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"match","stem":"학교와 지역에서 비슷한 일을 하는 것끼리 알맞게 이으세요.","pairs":[{"l":"학생 자치회","r":"주민 자치회"},{"l":"학급 회의","r":"주민 회의"},{"l":"학교 구성원","r":"지역 주민"}],"mis":"SO4-2-u1-X19","explanation":["학생 대표와 주민 대표예요.","회의도 있어요.","구성원도 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#7','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',2,'ox','auto','지역의 중요한 일을 일부 사람만 모여 결정하면 많은 사람의 입장을 고려하지 못할 수 있어요.',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"ox","stem":"지역의 중요한 일을 일부 사람만 모여 결정하면 많은 사람의 입장을 고려하지 못할 수 있어요.","answer":"O","reason_options":[{"t":"참여하지 못한 주민들의 의견이 반영되지 않기 때문에","correct":true},{"t":"일부 사람이 정하면 모든 주민의 의견이 담기기 때문에","mis":"SO4-2-u1-X18"}],"mis":"SO4-2-u1-X18","explanation":["일부만 모였어요.","다른 주민은 빠졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#8','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',2,'blank','auto','지역 주민들이 주민 자치에 적극적으로 참여할 때 지역에서 (    )를 실천할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"blank","stem":"지역 주민들이 주민 자치에 적극적으로 참여할 때 지역에서 (    )를 실천할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"민주주의","correct":true},{"t":"경쟁","mis":"SO4-2-u1-X18"},{"t":"명령","mis":"SO4-2-u1-X18"},{"t":"구경","mis":"SO4-2-u1-X18"}],"explanation":["다양한 의견을 반영해요.","함께 결정해요.","민주주의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#9','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',2,'mc','auto','골목길 밝히기 사업으로 달라진 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"mc","stem":"골목길 밝히기 사업으로 달라진 점으로 알맞은 것은 무엇인가요?","options":[{"t":"주민들이 밤에도 안전하게 다닐 수 있게 되었어요","correct":true},{"t":"골목길이 더 어두워졌어요","mis":"SO4-2-u1-X18"},{"t":"주민들이 골목에 가지 못하게 되었어요","mis":"SO4-2-u1-X18"},{"t":"지역의 밤 풍경이 사라졌어요","mis":"SO4-2-u1-X18"}],"explanation":["가로등이 생겼어요.","밝아졌어요.","안전하게 다녀요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 어두운 골목길 밝히기 사업을 시작했다.","지역 입구와 골목길 곳곳에 태양광을 활용한 가로등을 설치했다.","주민들이 밤에도 안전하게 다니고, 지역의 밤 풍경도 아름답게 변하고 있다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_basic#10','soc',4,2,'u1','L06','g4_2_soc_u1_L06_basic','lesson_basic','SO4-2-u1-C6',3,'mc','auto','두 문장에서 바뀌지 않고 그대로인 말이 알려 주는 학생 자치회와 주민 자치회의 공통점은 무엇인가요?',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"mc","stem":"두 문장에서 바뀌지 않고 그대로인 말이 알려 주는 학생 자치회와 주민 자치회의 공통점은 무엇인가요?","options":[{"t":"구성원이 주인으로서 일에 참여해 함께 문제를 해결해요","correct":true},{"t":"모이는 곳이 같아요","mis":"SO4-2-u1-X19"},{"t":"모이는 사람이 같아요","mis":"SO4-2-u1-X19"},{"t":"하는 행사가 모두 같아요","mis":"SO4-2-u1-X19"}],"explanation":["바뀐 말은 누가와 어디예요.","나머지는 그대로예요.","주인으로 참여해요."],"asset":{"type":"passage","lines":["학교 — 학생이 학교의 주인으로서 학교의 일에 참여하여 함께 문제를 해결해 나가요.","지역 — 주민이 지역의 주인으로서 지역의 일에 참여하여 함께 문제를 해결해 나가요."],"title":"낱말을 바꿔 끼운 두 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#1','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',2,'mc','auto','지역의 주민 자치 모습 가운데 「지역의 역사와 문화」와 관계있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"mc","stem":"지역의 주민 자치 모습 가운데 「지역의 역사와 문화」와 관계있는 것은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SO4-2-u1-X18"},{"t":"㉡","mis":"SO4-2-u1-X18"},{"t":"㉣","mis":"SO4-2-u1-X18"}],"explanation":["축제가 있어요.","역사와 문화를 알려요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 주민들의 의견을 모으는 회의를 열어요.","㉡ 지역에 필요한 예산을 세우는 일에 주민이 참여해요.","㉢ 주민들이 힘을 합해 지역의 역사와 문화를 알리는 축제를 열어요.","㉣ 주민이 함께 지역에 도움이 필요한 사람들을 도와요."],"title":"지역의 주민 자치 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#2','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',2,'ox','auto','주민 자치는 주민이 자기 집의 일만 스스로 해결하는 것이에요.',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"ox","stem":"주민 자치는 주민이 자기 집의 일만 스스로 해결하는 것이에요.","answer":"X","reason_options":[{"t":"주민 자치는 지역의 일에 참여해 함께 해결해 나가는 것이기 때문에","correct":true},{"t":"지역의 일은 주민과 관계가 없기 때문에","mis":"SO4-2-u1-X18"}],"mis":"SO4-2-u1-X18","explanation":["집의 일일까요?","지역의 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#3','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',3,'mc','auto','두 문장에서 학교 문장을 지역 문장으로 바꿀 때 바뀐 말끼리 짝지은 것은 무엇인가요?',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"mc","stem":"두 문장에서 학교 문장을 지역 문장으로 바꿀 때 바뀐 말끼리 짝지은 것은 무엇인가요?","options":[{"t":"학생 → 주민, 학교 → 지역","correct":true},{"t":"주인 → 손님, 참여 → 구경","mis":"SO4-2-u1-X19"},{"t":"해결 → 포기, 함께 → 혼자","mis":"SO4-2-u1-X19"},{"t":"바뀐 말이 하나도 없어요","mis":"SO4-2-u1-X19"}],"explanation":["누가가 바뀌었어요.","어디도 바뀌었어요.","나머지는 같아요."],"asset":{"type":"passage","lines":["학교 — 학생이 학교의 주인으로서 학교의 일에 참여하여 함께 문제를 해결해 나가요.","지역 — 주민이 지역의 주인으로서 지역의 일에 참여하여 함께 문제를 해결해 나가요."],"title":"낱말을 바꿔 끼운 두 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#4','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',3,'error','auto','주민 자치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X18','SO4-2-u1-X19']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"error","stem":"주민 자치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「주민 자치는 몇몇 사람이 정해서 주민에게 알려 주는 거야.」","correct":true,"mis_target":"SO4-2-u1-X18"},{"t":"친구 가 — 「주민이 지역의 주인으로서 참여해.」","mis":"SO4-2-u1-X18"},{"t":"친구 다 — 「주민 자치회는 지역 주민을 대표해.」","mis":"SO4-2-u1-X19"}],"explanation":["몇몇이 정할까요?","주민이 함께해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#5','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',3,'mc','auto','골목길 밝히기 사업을 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"mc","stem":"골목길 밝히기 사업을 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역을 안전하고 아름답게 만들어 더 살기 좋은 지역을 만들려고","correct":true},{"t":"다른 지역보다 가로등이 많아 보이려고","mis":"SO4-2-u1-X18"},{"t":"주민 자치회 위원만 편하게 다니려고","mis":"SO4-2-u1-X18"},{"t":"밤에 골목에 아무도 못 다니게 하려고","mis":"SO4-2-u1-X18"}],"explanation":["어두우면 어떨까요?","안전이 걱정돼요.","살기 좋은 지역이에요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 어두운 골목길 밝히기 사업을 시작했다.","지역 입구와 골목길 곳곳에 태양광을 활용한 가로등을 설치했다.","주민들이 밤에도 안전하게 다니고, 지역의 밤 풍경도 아름답게 변하고 있다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#6','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',3,'ox','auto','지역에 필요한 예산을 세우는 일에 주민이 참여하는 것도 주민 자치의 모습이에요.',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"ox","stem":"지역에 필요한 예산을 세우는 일에 주민이 참여하는 것도 주민 자치의 모습이에요.","answer":"O","reason_options":[{"t":"주민이 지역의 일에 참여해 함께 정하는 것이기 때문에","correct":true},{"t":"예산은 주민과 관계없는 일이기 때문에","mis":"SO4-2-u1-X18"}],"mis":"SO4-2-u1-X18","explanation":["지역의 일이에요.","주민이 참여해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 주민들의 의견을 모으는 회의를 열어요.","㉡ 지역에 필요한 예산을 세우는 일에 주민이 참여해요.","㉢ 주민들이 힘을 합해 지역의 역사와 문화를 알리는 축제를 열어요.","㉣ 주민이 함께 지역에 도움이 필요한 사람들을 도와요."],"title":"지역의 주민 자치 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#7','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',3,'mc','auto','주민 자치의 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"mc","stem":"주민 자치의 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"주민에게 묻지 않고 몇몇 사람이 정해 알려 주기만 해요","correct":true},{"t":"주민들의 의견을 모으는 회의를 해요","mis":"SO4-2-u1-X18"},{"t":"도움이 필요한 이웃을 함께 도와요","mis":"SO4-2-u1-X18"},{"t":"지역 축제를 주민들이 힘을 합해 열어요","mis":"SO4-2-u1-X18"}],"explanation":["주민이 참여하나요?","묻지 않았어요.","그것을 골라요."],"asset":{"type":"passage","lines":["㉠ 주민들의 의견을 모으는 회의를 열어요.","㉡ 지역에 필요한 예산을 세우는 일에 주민이 참여해요.","㉢ 주민들이 힘을 합해 지역의 역사와 문화를 알리는 축제를 열어요.","㉣ 주민이 함께 지역에 도움이 필요한 사람들을 도와요."],"title":"지역의 주민 자치 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#8','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',4,'mc','auto','포스터와 신문 기사를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X19','SO4-2-u1-X18']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C6","difficulty":4,"kind":"mc","stem":"포스터와 신문 기사를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주민 누구나 주민 자치회에 참여해 지역을 더 살기 좋게 바꿀 수 있어요","correct":true},{"t":"주민 자치회는 정해진 사람만 들어갈 수 있어요","mis":"SO4-2-u1-X19"},{"t":"지역의 일은 다른 지역에서 대신 해 줘요","mis":"SO4-2-u1-X18"},{"t":"골목길은 주민과 관계없는 곳이에요","mis":"SO4-2-u1-X18"}],"explanation":["누구나 참여해요.","골목이 밝아졌어요.","살기 좋아졌어요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 어두운 골목길 밝히기 사업을 시작했다.","지역 입구와 골목길 곳곳에 태양광을 활용한 가로등을 설치했다.","주민들이 밤에도 안전하게 다니고, 지역의 밤 풍경도 아름답게 변하고 있다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#9','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',4,'mc','auto','학교에 학생 자치회가 있다면 지역에는 주민 자치회가 있어요. 두 모임이 함께 지닌 뜻으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X19','SO4-2-u1-X18']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C6","difficulty":4,"kind":"mc","stem":"학교에 학생 자치회가 있다면 지역에는 주민 자치회가 있어요. 두 모임이 함께 지닌 뜻으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"구성원이면 누구나 참여해 더 나은 곳을 만들려고 함께 노력해요","correct":true},{"t":"두 모임은 하는 일이 전혀 달라요","mis":"SO4-2-u1-X19"},{"t":"두 모임 모두 어른만 참여해요","mis":"SO4-2-u1-X19"},{"t":"두 모임 모두 대표가 혼자 정해요","mis":"SO4-2-u1-X18"}],"explanation":["누가 참여할까요?","구성원 누구나예요.","함께 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L06_challenge#10','soc',4,2,'u1','L06','g4_2_soc_u1_L06_challenge','lesson_challenge','SO4-2-u1-C6',4,'essay','teacher','지역의 주민 자치 모습 ㉠~㉣ 가운데 하나를 골라, 그것이 왜 주민 자치인지 주민 자치의 뜻과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C6","difficulty":4,"kind":"essay","stem":"지역의 주민 자치 모습 ㉠~㉣ 가운데 하나를 골라, 그것이 왜 주민 자치인지 주민 자치의 뜻과 이어 쓰세요.","answer_guide":{"answer":"예: ㉣을 골랐어요. 주민들이 함께 지역에 도움이 필요한 사람들을 돕는 것은 주민이 지역의 주인으로서 지역의 일에 참여해 함께 문제를 해결해 나가는 모습이기 때문에 주민 자치예요.","scoring_points":["하나를 골랐는가","주민 자치의 뜻을 바르게 썼는가","고른 모습과 뜻을 이었는가"]},"explanation":["하나를 골라요.","뜻을 떠올려요.","이어 써요."],"asset":{"type":"passage","lines":["㉠ 주민들의 의견을 모으는 회의를 열어요.","㉡ 지역에 필요한 예산을 세우는 일에 주민이 참여해요.","㉢ 주민들이 힘을 합해 지역의 역사와 문화를 알리는 축제를 열어요.","㉣ 주민이 함께 지역에 도움이 필요한 사람들을 도와요."],"title":"지역의 주민 자치 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#1','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',1,'mc','auto','지역에서 일어나는 일들에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C7","difficulty":1,"kind":"mc","stem":"지역에서 일어나는 일들에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"지역 주민들의 생활에 많은 영향을 미쳐요","correct":true},{"t":"주민들의 생활과는 상관없어요","mis":"SO4-2-u1-X20"},{"t":"다른 지역 사람들만 영향을 받아요","mis":"SO4-2-u1-X20"},{"t":"몇몇 사람에게만 영향을 미쳐요","mis":"SO4-2-u1-X20"}],"explanation":["우리가 사는 곳의 일이에요.","생활과 이어져요.","영향을 미쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#2','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',1,'sa','auto','혼자 생활하는 노인에게 지원한 로봇은 무엇인가요? 「○○ 로봇」의 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C7","difficulty":1,"kind":"sa","stem":"혼자 생활하는 노인에게 지원한 로봇은 무엇인가요? 「○○ 로봇」의 ○○에 알맞은 두 글자를 쓰세요.","answer":["돌봄"],"explanation":["보살펴 주는 로봇이에요.","◯봄이에요.","돌봄이에요."],"asset":{"type":"passage","lines":["혼자 생활하는 노인에게 돌봄 로봇을 지원했다.","아이를 키우는 가정을 위해 주민들이 아이들을 함께 보살폈다.","그 결과 노인의 건강과 안전을 지키고, 아이를 키우기 좋은 지역이 되었다."],"title":"주민들이 함께한 일"},"mis":"SO4-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#3','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',1,'ox','auto','지역 주민이 지역을 잘 알기 때문에 주민이 직접 참여하는 것이 중요해요.',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C7","difficulty":1,"kind":"ox","stem":"지역 주민이 지역을 잘 알기 때문에 주민이 직접 참여하는 것이 중요해요.","answer":"O","reason_options":[{"t":"지역에 무엇이 필요한지 주민이 가장 잘 알기 때문에","correct":true},{"t":"주민은 지역의 일을 잘 모르기 때문에","mis":"SO4-2-u1-X20"}],"mis":"SO4-2-u1-X20","explanation":["누가 지역을 잘 알까요?","주민이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#4','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',1,'mc','auto','「온 마을이 학교다」 프로그램에서 주민이 참여할 수 있는 활동은 무엇인가요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C7","difficulty":1,"kind":"mc","stem":"「온 마을이 학교다」 프로그램에서 주민이 참여할 수 있는 활동은 무엇인가요?","options":[{"t":"친구야 소풍 가자","correct":true},{"t":"학교 운동장 넓히기","mis":"SO4-2-u1-X21"},{"t":"가게 간판 바꾸기","mis":"SO4-2-u1-X21"},{"t":"도로에 신호등 달기","mis":"SO4-2-u1-X21"}],"explanation":["게시글을 읽어요.","학생과 주민이 함께해요.","소풍이에요."],"asset":{"type":"passage","lines":["○○ 주민 자치회는 「온 마을이 학교다」 프로그램을 운영한다.","「친구야 소풍 가자」 — 학생과 주민이 함께 소풍을 간다.","「세대 공감 이야기가 있는 우리 마을 지도 만들기」","서로 다른 추억을 지닌 세대가 소통하며 주민과 지역이 함께 성장한다."],"title":"누리집 게시글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#5','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',2,'mc','auto','주민 참여가 활발하게 이루어지면 지역은 어떻게 달라질 수 있나요?',ARRAY['SO4-2-u1-X21','SO4-2-u1-X20']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"mc","stem":"주민 참여가 활발하게 이루어지면 지역은 어떻게 달라질 수 있나요?","options":[{"t":"주민들이 원하는 방향으로 지역이 달라질 수 있어요","correct":true},{"t":"문제를 해결하기 어려워져요","mis":"SO4-2-u1-X21"},{"t":"지역이 발전하기 어려워져요","mis":"SO4-2-u1-X21"},{"t":"지역의 일이 주민과 멀어져요","mis":"SO4-2-u1-X20"}],"explanation":["참여가 활발해요.","주민 뜻이 담겨요.","원하는 방향이에요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#6','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',2,'match','auto','판의 두 가지에서 같은 층끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"match","stem":"판의 두 가지에서 같은 층끼리 알맞게 이으세요.","pairs":[{"l":"주민들이 적극적으로 참여해요","r":"주민 참여가 활발하지 않아요"},{"l":"불편한 문제를 직접 해결해요","r":"문제를 해결하기 어려워져요"},{"l":"원하는 방향으로 달라져요","r":"발전하기 어려워져요"}],"mis":"SO4-2-u1-X21","explanation":["맨 아래 층부터 봐요.","서로 반대예요.","같은 층끼리 이어요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#7','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',2,'blank','auto','주민 참여가 활발하게 이루어지면 지역의 일을 (    )으로 해결할 수 있고, 더 살기 좋은 지역으로 발전할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"blank","stem":"주민 참여가 활발하게 이루어지면 지역의 일을 (    )으로 해결할 수 있고, 더 살기 좋은 지역으로 발전할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"민주적","correct":true},{"t":"혼자","mis":"SO4-2-u1-X21"},{"t":"억지","mis":"SO4-2-u1-X21"},{"t":"대충","mis":"SO4-2-u1-X21"}],"explanation":["다양한 의견을 모아요.","함께 정해요.","민주적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#8','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',2,'ox','auto','돌봄 로봇 지원과 아이를 함께 보살피는 일로 노인의 건강과 안전을 지키고 아이를 키우기 좋은 지역이 되었어요.',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"ox","stem":"돌봄 로봇 지원과 아이를 함께 보살피는 일로 노인의 건강과 안전을 지키고 아이를 키우기 좋은 지역이 되었어요.","answer":"O","reason_options":[{"t":"주민들이 함께 지역에 필요한 일을 했기 때문에","correct":true},{"t":"주민들이 아무것도 하지 않았기 때문에","mis":"SO4-2-u1-X20"}],"mis":"SO4-2-u1-X20","explanation":["주민들이 함께했어요.","지역이 좋아졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["혼자 생활하는 노인에게 돌봄 로봇을 지원했다.","아이를 키우는 가정을 위해 주민들이 아이들을 함께 보살폈다.","그 결과 노인의 건강과 안전을 지키고, 아이를 키우기 좋은 지역이 되었다."],"title":"주민들이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#9','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',2,'mc','auto','「온 마을이 학교다」 프로그램으로 얻을 수 있는 좋은 점은 무엇인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"mc","stem":"「온 마을이 학교다」 프로그램으로 얻을 수 있는 좋은 점은 무엇인가요?","options":[{"t":"서로 다른 세대가 소통하며 주민과 지역이 함께 성장해요","correct":true},{"t":"주민들이 지역의 일에서 멀어져요","mis":"SO4-2-u1-X20"},{"t":"학생과 주민이 만나지 않게 돼요","mis":"SO4-2-u1-X21"},{"t":"지역의 이야기가 사라져요","mis":"SO4-2-u1-X21"}],"explanation":["세대가 만나요.","소통해요.","함께 성장해요."],"asset":{"type":"passage","lines":["○○ 주민 자치회는 「온 마을이 학교다」 프로그램을 운영한다.","「친구야 소풍 가자」 — 학생과 주민이 함께 소풍을 간다.","「세대 공감 이야기가 있는 우리 마을 지도 만들기」","서로 다른 추억을 지닌 세대가 소통하며 주민과 지역이 함께 성장한다."],"title":"누리집 게시글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_basic#10','soc',4,2,'u1','L07','g4_2_soc_u1_L07_basic','lesson_basic','SO4-2-u1-C7',3,'mc','auto','판에서 맨 아래 층이 서야 위층이 서는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"판에서 맨 아래 층이 서야 위층이 서는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"주민 참여가 있어야 문제 해결과 지역의 발전이 뒤따라요","correct":true},{"t":"위층 카드가 더 어려워요","mis":"SO4-2-u1-X21"},{"t":"카드는 아무 차례로 올려도 돼요","mis":"SO4-2-u1-X21"},{"t":"맨 아래 층은 없어도 돼요","mis":"SO4-2-u1-X21"}],"explanation":["맨 아래는 참여예요.","그 위는 해결이에요.","참여가 먼저예요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#1','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',2,'mc','auto','관광 두레에서 주민들이 직접 운영하는 것이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"mc","stem":"관광 두레에서 주민들이 직접 운영하는 것이 아닌 것은 무엇인가요?","options":[{"t":"다른 지역의 학교","correct":true},{"t":"숙박","mis":"SO4-2-u1-X20"},{"t":"먹거리","mis":"SO4-2-u1-X20"},{"t":"여행 체험","mis":"SO4-2-u1-X20"}],"explanation":["지역만의 특색이에요.","셋이 나와요.","아닌 것을 골라요."],"asset":{"type":"passage","lines":["관광 두레는 지역 주민이 직접 숙박, 먹거리, 여행 체험 등에서","지역만의 특색을 지닌 관광 상품을 만들고 운영하도록 나라에서 지원하는 사업이다.","관광 두레 프로듀서는 주민이 관광 사업을 계획하도록 돕고 주민들을 서로 이어 준다."],"title":"별별 직업(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#2','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',2,'ox','auto','주민 참여가 활발하지 않으면 지역이 더 나은 모습으로 발전하기 어려워져요.',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"ox","stem":"주민 참여가 활발하지 않으면 지역이 더 나은 모습으로 발전하기 어려워져요.","answer":"O","reason_options":[{"t":"주민들이 지역의 문제에 관심을 두지 않으면 해결과 발전이 어렵기 때문에","correct":true},{"t":"주민이 참여하지 않아도 지역은 저절로 발전하기 때문에","mis":"SO4-2-u1-X21"}],"mis":"SO4-2-u1-X21","explanation":["참여가 없어요.","해결이 어려워요.","그래서 O예요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#3','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',3,'mc','auto','판에서 한쪽 가지에 카드를 올리면 다른 가지의 같은 층에도 칸이 서는 까닭은 무엇인가요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"판에서 한쪽 가지에 카드를 올리면 다른 가지의 같은 층에도 칸이 서는 까닭은 무엇인가요?","options":[{"t":"주민이 참여할 때와 참여하지 않을 때 같은 일이 서로 반대로 달라지기 때문이에요","correct":true},{"t":"두 가지의 글자가 똑같기 때문이에요","mis":"SO4-2-u1-X21"},{"t":"한쪽 가지는 틀린 이야기이기 때문이에요","mis":"SO4-2-u1-X21"},{"t":"판이 칸을 아무 곳에나 세우기 때문이에요","mis":"SO4-2-u1-X21"}],"explanation":["같은 층을 견줘요.","내용이 반대예요.","함께 서요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#4','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',3,'error','auto','주민 참여를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"error","stem":"주민 참여를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「지역의 일은 우리 생활과 관계없으니 몰라도 돼.」","correct":true,"mis_target":"SO4-2-u1-X20"},{"t":"친구 가 — 「참여가 활발하면 원하는 방향으로 달라져.」","mis":"SO4-2-u1-X21"},{"t":"친구 나 — 「주민이 지역을 잘 알아서 참여가 중요해.」","mis":"SO4-2-u1-X20"}],"explanation":["관계없을까요?","생활에 영향을 줘요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#5','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',3,'mc','auto','「세대 공감 이야기가 있는 우리 마을 지도 만들기」에 참여하면 생길 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X21','SO4-2-u1-X20']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"「세대 공감 이야기가 있는 우리 마을 지도 만들기」에 참여하면 생길 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어른과 어린이가 우리 마을의 추억을 나누며 서로를 이해해요","correct":true},{"t":"어른과 어린이가 서로 만나지 않아요","mis":"SO4-2-u1-X21"},{"t":"마을 지도가 다른 지역 것으로 바뀌어요","mis":"SO4-2-u1-X20"},{"t":"주민들이 마을에 관심을 잃어요","mis":"SO4-2-u1-X21"}],"explanation":["세대가 함께해요.","이야기를 나눠요.","서로 이해해요."],"asset":{"type":"passage","lines":["○○ 주민 자치회는 「온 마을이 학교다」 프로그램을 운영한다.","「친구야 소풍 가자」 — 학생과 주민이 함께 소풍을 간다.","「세대 공감 이야기가 있는 우리 마을 지도 만들기」","서로 다른 추억을 지닌 세대가 소통하며 주민과 지역이 함께 성장한다."],"title":"누리집 게시글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#6','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',3,'ox','auto','주민 참여는 지역의 일이 다 끝난 뒤에 해도 돼요.',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"ox","stem":"주민 참여는 지역의 일이 다 끝난 뒤에 해도 돼요.","answer":"X","reason_options":[{"t":"주민이 참여해야 지역의 문제가 해결되고 발전이 뒤따르기 때문에","correct":true},{"t":"지역의 일은 주민과 상관없이 저절로 달라지기 때문에","mis":"SO4-2-u1-X21"}],"mis":"SO4-2-u1-X21","explanation":["언제 참여할까요?","참여가 먼저예요.","그래서 X예요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#7','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',3,'mc','auto','돌봄 로봇 지원처럼 주민들이 함께 지역의 일을 하면 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"돌봄 로봇 지원처럼 주민들이 함께 지역의 일을 하면 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"지역의 일을 다른 지역에 모두 맡길 수 있어요","correct":true},{"t":"도움이 필요한 이웃의 안전을 지킬 수 있어요","mis":"SO4-2-u1-X20"},{"t":"살기 좋은 지역이 될 수 있어요","mis":"SO4-2-u1-X21"},{"t":"지역에 필요한 일을 주민이 직접 해결해요","mis":"SO4-2-u1-X21"}],"explanation":["좋은 점을 떠올려요.","맡기는 것은 다른 이야기예요.","아닌 것을 골라요."],"asset":{"type":"passage","lines":["혼자 생활하는 노인에게 돌봄 로봇을 지원했다.","아이를 키우는 가정을 위해 주민들이 아이들을 함께 보살폈다.","그 결과 노인의 건강과 안전을 지키고, 아이를 키우기 좋은 지역이 되었다."],"title":"주민들이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#8','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',4,'mc','auto','세 자료(주민들이 함께한 일 · 게시글 · 관광 두레)에서 공통으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C7","difficulty":4,"kind":"mc","stem":"세 자료(주민들이 함께한 일 · 게시글 · 관광 두레)에서 공통으로 알 수 있는 것은 무엇인가요?","options":[{"t":"주민들이 지역의 일에 참여하면 지역이 더 살기 좋은 곳으로 달라져요","correct":true},{"t":"지역의 일은 공공 기관만 할 수 있어요","mis":"SO4-2-u1-X20"},{"t":"주민 참여는 노인만 할 수 있어요","mis":"SO4-2-u1-X21"},{"t":"주민이 참여하면 지역이 나빠져요","mis":"SO4-2-u1-X21"}],"explanation":["주민이 함께해요.","지역이 달라져요.","살기 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#9','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',4,'mc','auto','주민 참여가 중요한 까닭을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C7","difficulty":4,"kind":"mc","stem":"주민 참여가 중요한 까닭을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"지역의 일은 주민 생활에 영향을 주고 주민이 지역을 잘 알기에, 참여하면 문제를 민주적으로 해결하고 지역이 발전해요","correct":true},{"t":"지역의 일은 주민 생활과 관계없어서 참여하지 않아도 돼요","mis":"SO4-2-u1-X20"},{"t":"주민이 참여하면 문제가 더 어려워져요","mis":"SO4-2-u1-X21"},{"t":"공공 기관이 다 해 주니 참여는 필요 없어요","mis":"SO4-2-u1-X20"}],"explanation":["생활에 영향을 줘요.","주민이 잘 알아요.","해결하고 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L07_challenge#10','soc',4,2,'u1','L07','g4_2_soc_u1_L07_challenge','lesson_challenge','SO4-2-u1-C7',4,'essay','teacher','우리 지역에 주민 참여가 활발하지 않다면 어떤 일이 생길지 쓰고, 주민 참여가 활발하면 어떻게 달라질지 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C7","difficulty":4,"kind":"essay","stem":"우리 지역에 주민 참여가 활발하지 않다면 어떤 일이 생길지 쓰고, 주민 참여가 활발하면 어떻게 달라질지 견주어 쓰세요.","answer_guide":{"answer":"예: 주민 참여가 활발하지 않으면 동네의 불편한 문제를 해결하기 어렵고 지역이 더 나아지기 어려워요. 주민 참여가 활발하면 주민들이 불편한 문제를 직접 해결하고 주민들이 원하는 방향으로 지역이 달라질 수 있어요.","scoring_points":["활발하지 않을 때를 썼는가","활발할 때를 썼는가","두 모습을 반대로 견주었는가"]},"explanation":["활발하지 않을 때예요.","활발할 때예요.","견주어 써요."],"asset":{"type":"passage","lines":["[참여가 활발할 때] 1층 — 주민들이 관심을 갖고 적극적으로 참여해요","2층 — 불편한 문제를 주민들이 직접 해결해요","3층 — 주민들이 원하는 방향으로 지역이 달라져요","[참여가 활발하지 않을 때] 1층 — 주민 참여가 활발하지 않아요","2층 — 문제를 해결하기 어려워져요","3층 — 지역이 더 나은 모습으로 발전하기 어려워져요"],"title":"두 가지가 함께 자라는 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#1','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',1,'mc','auto','주민 참여의 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X23']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"mc","stem":"주민 참여의 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"지역 축제에서 자원봉사해요","correct":true},{"t":"지역의 일을 모른 척해요","mis":"SO4-2-u1-X23"},{"t":"다른 사람이 대신 해 주기를 기다려요","mis":"SO4-2-u1-X23"},{"t":"불편한 점을 참고만 있어요","mis":"SO4-2-u1-X23"}],"explanation":["지역의 일에 함께해요.","축제를 도와요.","자원봉사예요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#2','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',1,'sa','auto','지역 주민들이 주민 자치에 참여해 다양한 역할을 하면 지역의 구성원으로서 느끼는 것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"sa","stem":"지역 주민들이 주민 자치에 참여해 다양한 역할을 하면 지역의 구성원으로서 느끼는 것은 무엇인가요? 세 글자로 쓰세요.","answer":["만족감"],"explanation":["뿌듯한 마음이에요.","만족◯이에요.","만족감이에요."],"mis":"SO4-2-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#3','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',1,'ox','auto','주민들은 지역의 일에 관한 의견을 다른 주민이나 공공 기관에 전달하기도 해요.',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"ox","stem":"주민들은 지역의 일에 관한 의견을 다른 주민이나 공공 기관에 전달하기도 해요.","answer":"O","reason_options":[{"t":"직접 참여하는 것뿐 아니라 의견을 전하는 것도 주민 참여 방법이기 때문에","correct":true},{"t":"의견은 마음속에만 두어야 하기 때문에","mis":"SO4-2-u1-X22"}],"mis":"SO4-2-u1-X22","explanation":["의견을 전해요.","공공 기관에도요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#4','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',1,'mc','auto','신문 기사에서 ○○동 주민들은 내년에 진행할 사업을 어떻게 정했나요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"mc","stem":"신문 기사에서 ○○동 주민들은 내년에 진행할 사업을 어떻게 정했나요?","options":[{"t":"주민 투표로 정했어요","correct":true},{"t":"공공 기관이 혼자 정했어요","mis":"SO4-2-u1-X22"},{"t":"가장 나이 많은 주민이 정했어요","mis":"SO4-2-u1-X22"},{"t":"제비를 뽑아 정했어요","mis":"SO4-2-u1-X22"}],"explanation":["기사를 읽어요.","주민들이 투표했어요.","주민 투표예요."],"asset":{"type":"passage","lines":["○○동 주민들이 내년에 진행할 지역 사업을 주민 투표로 정했다.","지역 곳곳에 설치된 투표판에 직접 투표하거나,","사회 관계망 서비스를 활용해 투표할 수 있었다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#5','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',2,'mc','auto','신문 기사 속 주민 투표는 어떤 방식으로 이루어졌나요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"mc","stem":"신문 기사 속 주민 투표는 어떤 방식으로 이루어졌나요?","options":[{"t":"곳곳의 투표판에 직접 투표하거나 사회 관계망 서비스로 투표했어요","correct":true},{"t":"누리집 게시판에만 의견을 올렸어요","mis":"SO4-2-u1-X22"},{"t":"전화로만 투표했어요","mis":"SO4-2-u1-X22"},{"t":"한 사람이 대표로 정했어요","mis":"SO4-2-u1-X22"}],"explanation":["두 가지 방식이에요.","투표판이 있었어요.","사회 관계망 서비스도요."],"asset":{"type":"passage","lines":["○○동 주민들이 내년에 진행할 지역 사업을 주민 투표로 정했다.","지역 곳곳에 설치된 투표판에 직접 투표하거나,","사회 관계망 서비스를 활용해 투표할 수 있었다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#6','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',2,'match','auto','그림 속 장소와 주민 참여 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"match","stem":"그림 속 장소와 주민 참여 방법을 알맞게 이으세요.","pairs":[{"l":"빛바랜 담벼락","r":"벽화 그리기"},{"l":"아침 학교 앞 건널목","r":"등하교 안전 지킴이 활동"},{"l":"쓰레기가 떨어진 길가","r":"지역 청소하기"},{"l":"투표판이 선 길모퉁이","r":"주민 투표 참여"}],"mis":"SO4-2-u1-X22","explanation":["담벼락은 그림이에요.","건널목은 안전이에요.","길가는 청소예요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#7','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',2,'blank','auto','지역 주민들은 일상생활과 관련 있는 지역의 일에 (    ) 참여하기도 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"blank","stem":"지역 주민들은 일상생활과 관련 있는 지역의 일에 (    ) 참여하기도 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"직접","correct":true},{"t":"몰래","mis":"SO4-2-u1-X22"},{"t":"가끔만","mis":"SO4-2-u1-X22"},{"t":"돈을 내야만","mis":"SO4-2-u1-X22"}],"explanation":["스스로 나서요.","몸소 해요.","직접이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#8','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',2,'ox','auto','주민 참여의 방법은 그림에 나온 것이 전부예요.',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"ox","stem":"주민 참여의 방법은 그림에 나온 것이 전부예요.","answer":"X","reason_options":[{"t":"서명 운동, 공청회 참석, 시민 단체 활동처럼 그림 밖에도 방법이 더 있기 때문에","correct":true},{"t":"그림에 없는 방법은 주민 참여가 아니기 때문에","mis":"SO4-2-u1-X22"}],"mis":"SO4-2-u1-X22","explanation":["그림 밖도 있어요.","서명 운동도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#9','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',2,'mc','auto','지역의 일에 참여하는 주민이 지녀야 할 태도로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X23']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"mc","stem":"지역의 일에 참여하는 주민이 지녀야 할 태도로 알맞은 것은 무엇인가요?","options":[{"t":"나의 이익만이 아니라 지역 전체에 이익이 되는 것을 생각해요","correct":true},{"t":"나에게 이익이 되는 일에만 참여해요","mis":"SO4-2-u1-X23"},{"t":"다른 사람이 대신 참여하기를 기다려요","mis":"SO4-2-u1-X23"},{"t":"지역의 일은 모른 척해요","mis":"SO4-2-u1-X23"}],"explanation":["누구의 이익일까요?","지역 전체예요.","그것을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_basic#10','soc',4,2,'u1','L08','g4_2_soc_u1_L08_basic','lesson_basic','SO4-2-u1-C8',3,'mc','auto','주민 참여가 이루어지지 않는다면 지역의 일은 어떻게 결정될 수 있나요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"주민 참여가 이루어지지 않는다면 지역의 일은 어떻게 결정될 수 있나요?","options":[{"t":"주민이 원하는 방향과 상관없이 결정될 수 있어요","correct":true},{"t":"주민이 원하는 대로 저절로 정해져요","mis":"SO4-2-u1-X21"},{"t":"결정이 더 민주적으로 이루어져요","mis":"SO4-2-u1-X21"},{"t":"주민 모두의 의견이 담겨요","mis":"SO4-2-u1-X21"}],"explanation":["주민이 빠졌어요.","의견이 없어요.","상관없이 정해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#1','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',2,'mc','auto','그림 속 방법 가운데 「의견을 전달하는」 방법에 가장 가까운 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"mc","stem":"그림 속 방법 가운데 「의견을 전달하는」 방법에 가장 가까운 것은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉣","mis":"SO4-2-u1-X22"},{"t":"㉤","mis":"SO4-2-u1-X22"},{"t":"㉥","mis":"SO4-2-u1-X22"}],"explanation":["의견을 올려요.","누리집 게시판이에요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#2','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',2,'ox','auto','주민 참여는 어려운 일이라 큰 문제가 생겼을 때만 해요.',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"ox","stem":"주민 참여는 어려운 일이라 큰 문제가 생겼을 때만 해요.","answer":"X","reason_options":[{"t":"주민 참여는 작은 일에서부터 시작할 수 있기 때문에","correct":true},{"t":"주민 참여는 공공 기관 사람만 할 수 있기 때문에","mis":"SO4-2-u1-X22"}],"mis":"SO4-2-u1-X22","explanation":["어려운 일일까요?","작은 일부터 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#3','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',3,'mc','auto','그림에 나오지 않지만 주민 참여의 방법인 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"그림에 나오지 않지만 주민 참여의 방법인 것은 무엇인가요?","options":[{"t":"공청회에 참석하기","correct":true},{"t":"지역 축제에서 자원봉사하기","mis":"SO4-2-u1-X22"},{"t":"주민 회의에 참석하기","mis":"SO4-2-u1-X22"},{"t":"지역 소식지 살펴보기","mis":"SO4-2-u1-X22"}],"explanation":["그림 속 방법을 빼요.","남는 것이 있어요.","공청회예요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#4','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',3,'error','auto','주민 참여 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X22','SO4-2-u1-X23']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"error","stem":"주민 참여 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「주민 참여는 공공 기관에서 일하는 사람만 할 수 있어.」","correct":true,"mis_target":"SO4-2-u1-X22"},{"t":"친구 가 — 「서명 운동도 주민 참여 방법이야.」","mis":"SO4-2-u1-X22"},{"t":"친구 다 — 「지역 전체의 이익을 생각해야 해.」","mis":"SO4-2-u1-X23"}],"explanation":["누가 참여할까요?","주민 누구나예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#5','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',3,'mc','auto','주민 투표로 지역의 일을 결정할 때 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X22','SO4-2-u1-X21']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"주민 투표로 지역의 일을 결정할 때 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"주민 몇 사람의 뜻대로만 정할 수 있어요","correct":true},{"t":"주민들의 의견을 반영할 수 있어요","mis":"SO4-2-u1-X22"},{"t":"지역의 일을 민주적으로 해결할 수 있어요","mis":"SO4-2-u1-X22"},{"t":"주민이 원하는 방향으로 지역이 발전해요","mis":"SO4-2-u1-X21"}],"explanation":["투표는 모두가 해요.","몇 사람이 아니에요.","그것을 골라요."],"asset":{"type":"passage","lines":["○○동 주민들이 내년에 진행할 지역 사업을 주민 투표로 정했다.","지역 곳곳에 설치된 투표판에 직접 투표하거나,","사회 관계망 서비스를 활용해 투표할 수 있었다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#6','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',3,'ox','auto','내 집 앞 길만 넓혀 달라고 고집하는 것보다 지역 전체에 필요한 일을 함께 생각하는 것이 바람직해요.',ARRAY['SO4-2-u1-X23']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"ox","stem":"내 집 앞 길만 넓혀 달라고 고집하는 것보다 지역 전체에 필요한 일을 함께 생각하는 것이 바람직해요.","answer":"O","reason_options":[{"t":"지역의 일은 지역 전체의 이익을 생각해야 하기 때문에","correct":true},{"t":"나에게 이익이 되는 일이 언제나 먼저이기 때문에","mis":"SO4-2-u1-X23"}],"mis":"SO4-2-u1-X23","explanation":["누구의 길일까요?","지역 전체를 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#7','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',3,'mc','auto','투표판과 사회 관계망 서비스 두 방식으로 주민 투표를 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"투표판과 사회 관계망 서비스 두 방식으로 주민 투표를 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"더 많은 주민이 쉽게 참여해 의견을 낼 수 있게 하려고","correct":true},{"t":"투표를 어렵게 하려고","mis":"SO4-2-u1-X22"},{"t":"몇몇 주민만 투표하게 하려고","mis":"SO4-2-u1-X22"},{"t":"투표 결과를 숨기려고","mis":"SO4-2-u1-X22"}],"explanation":["방식이 두 가지예요.","편한 방법으로 해요.","많은 주민이 참여해요."],"asset":{"type":"passage","lines":["○○동 주민들이 내년에 진행할 지역 사업을 주민 투표로 정했다.","지역 곳곳에 설치된 투표판에 직접 투표하거나,","사회 관계망 서비스를 활용해 투표할 수 있었다."],"title":"신문 기사(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#8','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',4,'mc','auto','그림 속 방법과 그림 밖 방법을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C8","difficulty":4,"kind":"mc","stem":"그림 속 방법과 그림 밖 방법을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"직접 참여하거나 의견을 전하는 등 주민 참여의 방법은 여러 가지이고 더 떠올려 볼 수 있어요","correct":true},{"t":"주민 참여의 방법은 한 가지뿐이에요","mis":"SO4-2-u1-X22"},{"t":"그림 밖 방법이 더 중요해요","mis":"SO4-2-u1-X22"},{"t":"주민 참여는 어른만 할 수 있어요","mis":"SO4-2-u1-X22"}],"explanation":["그림 속에 여덟 가지예요.","그림 밖에도 있어요.","여러 가지예요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#9','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',4,'mc','auto','주민 참여의 효과를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X21','SO4-2-u1-X23','SO4-2-u1-X22']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C8","difficulty":4,"kind":"mc","stem":"주민 참여의 효과를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"주민 의견이 반영되어 더 나은 지역이 되고, 주민은 지역의 구성원으로서 만족감을 느껴요","correct":true},{"t":"지역의 일이 주민과 멀어져요","mis":"SO4-2-u1-X21"},{"t":"나의 이익만 커져요","mis":"SO4-2-u1-X23"},{"t":"공공 기관의 일이 사라져요","mis":"SO4-2-u1-X22"}],"explanation":["지역이 나아져요.","주민도 느껴요.","만족감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L08_challenge#10','soc',4,2,'u1','L08','g4_2_soc_u1_L08_challenge','lesson_challenge','SO4-2-u1-C8',4,'essay','teacher','그림 속 주민 참여 방법 가운데 내가 해 보고 싶은 것을 하나 골라, 그 방법으로 지역에 어떤 도움을 줄 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C8","difficulty":4,"kind":"essay","stem":"그림 속 주민 참여 방법 가운데 내가 해 보고 싶은 것을 하나 골라, 그 방법으로 지역에 어떤 도움을 줄 수 있는지 쓰세요.","answer_guide":{"answer":"예: ㉥ 등하교 안전 지킴이 활동을 해 보고 싶어요. 아침마다 학교 앞 건널목에서 친구들이 안전하게 길을 건너도록 도우면 사고를 줄이고 안전한 지역을 만드는 데 도움이 돼요.","scoring_points":["방법을 하나 골랐는가","지역에 주는 도움을 썼는가","지역 전체의 이익과 이어졌는가"]},"explanation":["하나를 골라요.","하는 일을 떠올려요.","도움을 써요."],"asset":{"type":"passage","lines":["㉠ 지역 축제에서 자원봉사해요.","㉡ 지역 소식지를 살펴봐요.","㉢ 공공 기관 누리집 게시판에 의견을 올려요.","㉣ 지역을 청소해요.","㉤ 빛바랜 담벼락에 벽화를 그려요.","㉥ 등하교 안전 지킴이 활동을 해요.","㉦ 주민 회의에 참석해요.","㉧ 주민 투표에 참여해요."],"title":"그림 속 주민 참여 방법(교과서 그림을 글로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#1','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',1,'mc','auto','주민 자치는 지역마다 어떤 모습으로 이루어지나요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"mc","stem":"주민 자치는 지역마다 어떤 모습으로 이루어지나요?","options":[{"t":"다양한 모습","correct":true},{"t":"똑같은 모습","mis":"SO4-2-u1-X24"},{"t":"한 가지 모습","mis":"SO4-2-u1-X24"},{"t":"정해진 모습","mis":"SO4-2-u1-X24"}],"explanation":["지역마다 달라요.","여러 가지예요.","다양한 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#2','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',1,'sa','auto','조사를 마친 뒤 조사 내용을 정리해 쓰는 글은 「조사 ○○○」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"sa","stem":"조사를 마친 뒤 조사 내용을 정리해 쓰는 글은 「조사 ○○○」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["보고서"],"explanation":["결과를 알려요.","◯고서예요.","보고서예요."],"asset":{"type":"passage","lines":["① 조사 목적 — 우리 지역의 주민 자치 사례 알아보기","② 조사 날짜 — ○월 ○일","③ 조사한 사람 · ④ 조사 방법","⑤ 조사 모습","⑥ 조사 내용 — ○○동 주민들은 지저분하고 위험한 공터를 쉼터로 만들었어요.","⑦ 알게 된 점 — 많은 주민이 참여해 여러 사람에게 도움을 주고 있어요.","⑧ 더 알고 싶은 점 — 다른 지역은 어떤 모습일까?"],"title":"조사 보고서 여덟 칸"},"mis":"SO4-2-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#3','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',1,'ox','auto','공공 기관을 방문할 때는 미리 연락해 방문 허락을 받아요.',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"ox","stem":"공공 기관을 방문할 때는 미리 연락해 방문 허락을 받아요.","answer":"O","reason_options":[{"t":"담당자가 기다릴 수 있고 다른 사람에게 피해를 주지 않기 때문에","correct":true},{"t":"허락 없이 찾아가는 것이 예의이기 때문에","mis":"SO4-2-u1-X24"}],"mis":"SO4-2-u1-X24","explanation":["미리 알려요.","허락을 받아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#4','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',1,'mc','auto','주민 자치에 활발하게 참여하는 주민을 만나 물어보는 조사 방법은 무엇인가요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"mc","stem":"주민 자치에 활발하게 참여하는 주민을 만나 물어보는 조사 방법은 무엇인가요?","options":[{"t":"지역 주민 면담하기","correct":true},{"t":"인터넷으로 찾아보기","mis":"SO4-2-u1-X24"},{"t":"지역 신문 찾아보기","mis":"SO4-2-u1-X24"},{"t":"지역 게시판 찾아보기","mis":"SO4-2-u1-X24"}],"explanation":["사람을 만나요.","직접 물어요.","면담하기예요."],"asset":{"type":"passage","lines":["㉠ 인터넷으로 찾아보기","㉡ 지역 신문 찾아보기","㉢ 지역 주민 면담하기","㉣ 지역 게시판 찾아보기","㉤ 공공 기관 방문하기"],"title":"주민 자치 사례 조사 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#5','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',2,'mc','auto','공공 기관을 방문해 조사할 때 지킬 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"mc","stem":"공공 기관을 방문해 조사할 때 지킬 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"허락 없이 찾아가 큰 소리로 이야기해요","correct":true},{"t":"보호자와 함께 가요","mis":"SO4-2-u1-X24"},{"t":"미리 연락해 허락을 받아요","mis":"SO4-2-u1-X24"},{"t":"공공질서를 지켜요","mis":"SO4-2-u1-X24"}],"explanation":["지킬 점을 떠올려요.","예의가 필요해요.","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#6','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',2,'match','auto','조사 방법과 조사하는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"match","stem":"조사 방법과 조사하는 모습을 알맞게 이으세요.","pairs":[{"l":"인터넷으로 찾아보기","r":"공공 기관 누리집에서 「주민 자치」 검색하기"},{"l":"지역 신문 찾아보기","r":"주민 자치와 관련 있는 기사 찾기"},{"l":"지역 게시판 찾아보기","r":"지역 행사와 주민 회의 소식 찾기"},{"l":"공공 기관 방문하기","r":"담당자에게 묻고 기록하기"}],"mis":"SO4-2-u1-X24","explanation":["검색은 인터넷이에요.","기사는 신문이에요.","방문은 담당자예요."],"asset":{"type":"passage","lines":["㉠ 인터넷으로 찾아보기","㉡ 지역 신문 찾아보기","㉢ 지역 주민 면담하기","㉣ 지역 게시판 찾아보기","㉤ 공공 기관 방문하기"],"title":"주민 자치 사례 조사 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#7','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',2,'blank','auto','조사하기 전에 조사 주제, 목적, 사람과 역할, 방법 등을 미리 정해 적는 것은 조사 (    )예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"blank","stem":"조사하기 전에 조사 주제, 목적, 사람과 역할, 방법 등을 미리 정해 적는 것은 조사 (    )예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"계획서","correct":true},{"t":"보고서","mis":"SO4-2-u1-X25"},{"t":"신문","mis":"SO4-2-u1-X25"},{"t":"현수막","mis":"SO4-2-u1-X25"}],"explanation":["조사하기 전이에요.","미리 계획해요.","계획서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#8','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',2,'ox','auto','조사 보고서의 「알게 된 점」 칸은 조사하기 전에 미리 써 둘 수 있어요.',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"ox","stem":"조사 보고서의 「알게 된 점」 칸은 조사하기 전에 미리 써 둘 수 있어요.","answer":"X","reason_options":[{"t":"조사를 해 봐야 무엇을 알게 되었는지 알 수 있기 때문에","correct":true},{"t":"보고서는 아무 칸이나 먼저 써도 되기 때문에","mis":"SO4-2-u1-X25"}],"mis":"SO4-2-u1-X25","explanation":["언제 알게 될까요?","조사를 마친 뒤예요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 조사 목적 — 우리 지역의 주민 자치 사례 알아보기","② 조사 날짜 — ○월 ○일","③ 조사한 사람 · ④ 조사 방법","⑤ 조사 모습","⑥ 조사 내용 — ○○동 주민들은 지저분하고 위험한 공터를 쉼터로 만들었어요.","⑦ 알게 된 점 — 많은 주민이 참여해 여러 사람에게 도움을 주고 있어요.","⑧ 더 알고 싶은 점 — 다른 지역은 어떤 모습일까?"],"title":"조사 보고서 여덟 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_basic#9','soc',4,2,'u1','L09','g4_2_soc_u1_L09_basic','lesson_basic','SO4-2-u1-C9',2,'mc','auto','우리 지역 주민 자치 사례를 발표할 때 중점을 두어 전하면 좋은 것은 무엇인가요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"mc","stem":"우리 지역 주민 자치 사례를 발표할 때 중점을 두어 전하면 좋은 것은 무엇인가요?","options":[{"t":"주민 자치로 우리 지역이 더 나아진 점","correct":true},{"t":"조사한 친구들의 이름","mis":"SO4-2-u1-X25"},{"t":"조사하러 간 날의 날씨","mis":"SO4-2-u1-X25"},{"t":"발표 차례를 정한 방법","mis":"SO4-2-u1-X25"}],"explanation":["무엇을 알리고 싶나요?","달라진 지역이에요.","나아진 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
