INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#1','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',2,'mc','auto','보고서 ⑥ 조사 내용에 나온 주민 자치 사례는 무엇인가요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"mc","stem":"보고서 ⑥ 조사 내용에 나온 주민 자치 사례는 무엇인가요?","options":[{"t":"지저분하고 위험한 공터를 주민들이 쉼터로 만들었어요","correct":true},{"t":"도로를 넓혔어요","mis":"SO4-2-u1-X24"},{"t":"다른 지역에 가게를 열었어요","mis":"SO4-2-u1-X24"},{"t":"학교 이름을 바꾸었어요","mis":"SO4-2-u1-X24"}],"explanation":["⑥을 읽어요.","공터가 있었어요.","쉼터가 됐어요."],"asset":{"type":"passage","lines":["① 조사 목적 — 우리 지역의 주민 자치 사례 알아보기","② 조사 날짜 — ○월 ○일","③ 조사한 사람 · ④ 조사 방법","⑤ 조사 모습","⑥ 조사 내용 — ○○동 주민들은 지저분하고 위험한 공터를 쉼터로 만들었어요.","⑦ 알게 된 점 — 많은 주민이 참여해 여러 사람에게 도움을 주고 있어요.","⑧ 더 알고 싶은 점 — 다른 지역은 어떤 모습일까?"],"title":"조사 보고서 여덟 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#2','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',2,'ox','auto','조사 방법에는 옳고 그름이 없어 알맞은 방법을 골라 조사하면 돼요.',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"ox","stem":"조사 방법에는 옳고 그름이 없어 알맞은 방법을 골라 조사하면 돼요.","answer":"O","reason_options":[{"t":"여러 방법 모두 주민 자치 사례를 알아볼 수 있는 방법이기 때문에","correct":true},{"t":"공공 기관 방문만 바른 방법이기 때문에","mis":"SO4-2-u1-X24"}],"mis":"SO4-2-u1-X24","explanation":["방법이 다섯이에요.","모두 쓸 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 인터넷으로 찾아보기","㉡ 지역 신문 찾아보기","㉢ 지역 주민 면담하기","㉣ 지역 게시판 찾아보기","㉤ 공공 기관 방문하기"],"title":"주민 자치 사례 조사 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#3','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',3,'mc','auto','보고서 칸을 쓰는 때에 따라 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"mc","stem":"보고서 칸을 쓰는 때에 따라 바르게 짝지은 것은 무엇인가요?","options":[{"t":"조사하기 전 — 조사 목적 · 조사를 마친 뒤 — 알게 된 점","correct":true},{"t":"조사하기 전 — 알게 된 점 · 조사를 마친 뒤 — 조사 목적","mis":"SO4-2-u1-X25"},{"t":"조사하기 전 — 조사 날짜 · 조사를 마친 뒤 — 조사 방법","mis":"SO4-2-u1-X25"},{"t":"모든 칸을 조사하기 전에 써요","mis":"SO4-2-u1-X25"}],"explanation":["목적은 미리 정해요.","알게 된 점은 마친 뒤예요.","때가 달라요."],"asset":{"type":"passage","lines":["① 조사 목적 — 우리 지역의 주민 자치 사례 알아보기","② 조사 날짜 — ○월 ○일","③ 조사한 사람 · ④ 조사 방법","⑤ 조사 모습","⑥ 조사 내용 — ○○동 주민들은 지저분하고 위험한 공터를 쉼터로 만들었어요.","⑦ 알게 된 점 — 많은 주민이 참여해 여러 사람에게 도움을 주고 있어요.","⑧ 더 알고 싶은 점 — 다른 지역은 어떤 모습일까?"],"title":"조사 보고서 여덟 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#4','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',3,'error','auto','조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X25','SO4-2-u1-X24']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"error","stem":"조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「조사 계획서에 알게 된 점과 더 알고 싶은 점을 미리 써.」","correct":true,"mis_target":"SO4-2-u1-X25"},{"t":"친구 나 — 「공공 기관에 갈 때는 보호자와 함께 가.」","mis":"SO4-2-u1-X24"},{"t":"친구 다 — 「지역 신문에서 관련 기사를 찾을 수 있어.」","mis":"SO4-2-u1-X24"}],"explanation":["계획서에 쓸까요?","보고서에 써요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#5','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',3,'mc','auto','생활 실험실에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X24','SO4-2-u1-X18']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"mc","stem":"생활 실험실에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"주민이 중심이 되어 공공 기관·전문가와 손잡고 생활 속 불편을 직접 해결해요","correct":true},{"t":"학교 과학실에서 실험만 해요","mis":"SO4-2-u1-X24"},{"t":"전문가들만 모여 지역의 일을 대신 정해요","mis":"SO4-2-u1-X18"},{"t":"가상 세계에서 놀이만 해요","mis":"SO4-2-u1-X24"}],"explanation":["주민이 중심이에요.","함께 손잡아요.","불편을 해결해요."],"asset":{"type":"passage","lines":["생활 실험실은 지역 주민들이 중심이 되어","공공 기관, 전문가들과 손잡고","생활 속에서 겪는 어려움이나 불편함을 직접 해결해 나가는 방식이다."],"title":"풍덩 사회 속으로(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#6','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',3,'ox','auto','공공 기관을 방문할 때 다른 사람에게 피해를 주지 않도록 공공질서를 지켜야 해요.',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"ox","stem":"공공 기관을 방문할 때 다른 사람에게 피해를 주지 않도록 공공질서를 지켜야 해요.","answer":"O","reason_options":[{"t":"공공 기관은 여러 사람이 함께 쓰는 곳이기 때문에","correct":true},{"t":"조사하러 갔으면 무엇이든 해도 되기 때문에","mis":"SO4-2-u1-X24"}],"mis":"SO4-2-u1-X24","explanation":["여러 사람이 와요.","질서를 지켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#7','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',3,'mc','auto','조사 계획서에 넣을 내용으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"mc","stem":"조사 계획서에 넣을 내용으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"조사를 마치고 느낀 점","correct":true},{"t":"조사 주제","mis":"SO4-2-u1-X25"},{"t":"조사하는 사람과 역할","mis":"SO4-2-u1-X25"},{"t":"주의할 점","mis":"SO4-2-u1-X25"}],"explanation":["계획서는 미리 써요.","느낀 점은 언제일까요?","마친 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#8','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',4,'mc','auto','주민 자치 사례를 조사하면 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X24','SO4-2-u1-X18']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C9","difficulty":4,"kind":"mc","stem":"주민 자치 사례를 조사하면 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 지역을 살기 좋게 만들려는 주민들의 노력을 알 수 있어요","correct":true},{"t":"주민 자치는 모든 지역에서 똑같아요","mis":"SO4-2-u1-X24"},{"t":"우리 지역에는 주민 자치가 필요 없어요","mis":"SO4-2-u1-X18"},{"t":"주민 자치는 공공 기관만 해요","mis":"SO4-2-u1-X18"}],"explanation":["사례를 찾아요.","주민이 노력했어요.","살기 좋게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#9','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',4,'mc','auto','「다른 지역에서는 어떤 모습으로 주민 자치가 이루어지고 있을까?」는 보고서의 어느 칸에 어울리나요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C9","difficulty":4,"kind":"mc","stem":"「다른 지역에서는 어떤 모습으로 주민 자치가 이루어지고 있을까?」는 보고서의 어느 칸에 어울리나요?","options":[{"t":"더 알고 싶은 점","correct":true},{"t":"조사 목적","mis":"SO4-2-u1-X25"},{"t":"조사 날짜","mis":"SO4-2-u1-X25"},{"t":"조사 방법","mis":"SO4-2-u1-X25"}],"explanation":["조사를 마쳤어요.","궁금한 것이 생겼어요.","더 알고 싶은 점이에요."],"asset":{"type":"passage","lines":["① 조사 목적 — 우리 지역의 주민 자치 사례 알아보기","② 조사 날짜 — ○월 ○일","③ 조사한 사람 · ④ 조사 방법","⑤ 조사 모습","⑥ 조사 내용 — ○○동 주민들은 지저분하고 위험한 공터를 쉼터로 만들었어요.","⑦ 알게 된 점 — 많은 주민이 참여해 여러 사람에게 도움을 주고 있어요.","⑧ 더 알고 싶은 점 — 다른 지역은 어떤 모습일까?"],"title":"조사 보고서 여덟 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L09_challenge#10','soc',4,2,'u1','L09','g4_2_soc_u1_L09_challenge','lesson_challenge','SO4-2-u1-C9',4,'essay','teacher','우리 지역의 주민 자치 사례를 조사한다면 어떤 방법을 고를지 쓰고, 그 방법으로 조사할 때 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C9","difficulty":4,"kind":"essay","stem":"우리 지역의 주민 자치 사례를 조사한다면 어떤 방법을 고를지 쓰고, 그 방법으로 조사할 때 주의할 점을 쓰세요.","answer_guide":{"answer":"예: 지역 주민 면담하기를 고를 거예요. 주민 자치회에서 활동하는 주민을 만나 어떤 일을 했는지 물어볼 거예요. 미리 연락해 허락을 받고, 보호자와 함께 가며, 예의 바르게 묻고 들은 내용을 기록할 거예요.","scoring_points":["조사 방법을 골랐는가","조사할 내용을 썼는가","주의할 점을 썼는가"]},"explanation":["방법을 골라요.","무엇을 물을까요?","주의할 점을 써요."],"asset":{"type":"passage","lines":["㉠ 인터넷으로 찾아보기","㉡ 지역 신문 찾아보기","㉢ 지역 주민 면담하기","㉣ 지역 게시판 찾아보기","㉤ 공공 기관 방문하기"],"title":"주민 자치 사례 조사 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#1','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',1,'mc','auto','주민 자치에 참여할 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"mc","stem":"주민 자치에 참여할 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"주민 자치가 필요한 일 찾기","correct":true},{"t":"달라진 점 쓰기","mis":"SO4-2-u1-X26"},{"t":"돌아보며 평가하기","mis":"SO4-2-u1-X26"},{"t":"계획을 세워 실천하기","mis":"SO4-2-u1-X26"}],"explanation":["무엇이 필요할까요?","일을 먼저 찾아요.","필요한 일 찾기예요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#2','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',1,'sa','auto','교과서 예시에서 주민 자치가 필요한 일로 찾은 곳은 학교에 오는 「○○로」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"sa","stem":"교과서 예시에서 주민 자치가 필요한 일로 찾은 곳은 학교에 오는 「○○로」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["통학"],"explanation":["학교에 다니는 길이에요.","통◯로예요.","통학이에요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"},"mis":"SO4-2-u1-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#3','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',1,'ox','auto','주민의 힘만으로 해결하기 어려운 문제는 공공 기관에 도움을 청할 수 있어요.',ARRAY['SO4-2-u1-X27']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"ox","stem":"주민의 힘만으로 해결하기 어려운 문제는 공공 기관에 도움을 청할 수 있어요.","answer":"O","reason_options":[{"t":"공공 기관과 함께하면 어려운 문제도 해결할 수 있기 때문에","correct":true},{"t":"어려운 문제는 그대로 두어야 하기 때문에","mis":"SO4-2-u1-X27"}],"mis":"SO4-2-u1-X27","explanation":["어려운 문제예요.","도움을 청해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#4','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',1,'mc','auto','교과서에서 소개한 주민 자치에 참여하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X27']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"mc","stem":"교과서에서 소개한 주민 자치에 참여하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"친구들과 캠페인 문구를 만들어 주민들에게 알려요","correct":true},{"t":"지역의 일은 어른에게만 맡겨요","mis":"SO4-2-u1-X26"},{"t":"불편해도 참고 기다려요","mis":"SO4-2-u1-X27"},{"t":"공공 기관의 일에 관심을 두지 않아요","mis":"SO4-2-u1-X27"}],"explanation":["친구들과 함께해요.","문구를 만들어요.","캠페인이에요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
