INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#6','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',2,'match','auto','참여 걸음과 통학로 예시를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"match","stem":"참여 걸음과 통학로 예시를 알맞게 이으세요.","pairs":[{"l":"필요한 일 찾기","r":"통학로가 위험해요"},{"l":"참여 방법 찾기","r":"누리집 게시판에 의견 올리기"},{"l":"계획을 세워 실천하기","r":"벽화 그리기"},{"l":"달라진 점 쓰기","r":"주민들의 관심이 높아졌어요"}],"mis":"SO4-2-u1-X26","explanation":["처음은 일 찾기예요.","방법을 찾고 실천해요.","달라진 점을 써요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#7','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',2,'blank','auto','지역 주민들이 중심이 되어 지역의 일에 관심을 기울이고 노력하면 더 나은 (    )을 만들 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X27']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"blank","stem":"지역 주민들이 중심이 되어 지역의 일에 관심을 기울이고 노력하면 더 나은 (    )을 만들 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"지역","correct":true},{"t":"교실","mis":"SO4-2-u1-X26"},{"t":"집 안","mis":"SO4-2-u1-X26"},{"t":"공공 기관 건물","mis":"SO4-2-u1-X27"}],"explanation":["주민이 사는 곳이에요.","우리 동네예요.","지역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#8','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',2,'ox','auto','주민 자치는 어른이 된 뒤에만 참여할 수 있어요.',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"ox","stem":"주민 자치는 어른이 된 뒤에만 참여할 수 있어요.","answer":"X","reason_options":[{"t":"어린이도 친구들과 함께 캠페인 같은 방법으로 참여할 수 있기 때문에","correct":true},{"t":"어린이는 지역 주민이 아니기 때문에","mis":"SO4-2-u1-X26"}],"mis":"SO4-2-u1-X26","explanation":["통학로 예시를 봐요.","친구들이 참여했어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#9','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',2,'mc','auto','참여하기 전과 참여한 뒤를 견주는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X27']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"mc","stem":"참여하기 전과 참여한 뒤를 견주는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"참여로 지역이 어떻게 달라졌는지 알 수 있기 때문이에요","correct":true},{"t":"두 장면이 똑같은지 확인하려고","mis":"SO4-2-u1-X26"},{"t":"참여하지 않으려고","mis":"SO4-2-u1-X27"},{"t":"그림을 많이 그리려고","mis":"SO4-2-u1-X26"}],"explanation":["전과 후가 있어요.","같은 자리를 견줘요.","달라진 점이 보여요."],"asset":{"type":"passage","lines":["참여하기 전 — 통학로의 벽은 낡고, 학교에 오는 길은 위험하고, 학교에 대한 주민들의 관심은 낮아요.","참여한 뒤 — 통학로가 예쁘게 꾸며지고, 주민들이 함께 그린 벽화가 생기고, 주민들의 관심이 높아졌어요."],"title":"참여하기 전과 참여한 뒤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_basic#10','soc',4,2,'u1','L10','g4_2_soc_u1_L10_basic','lesson_basic','SO4-2-u1-C10',3,'mc','auto','주민 자치 참여 다섯 걸음 가운데 「참여한 과정을 스스로 되짚어 보는」 걸음은 무엇인가요?',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"mc","stem":"주민 자치 참여 다섯 걸음 가운데 「참여한 과정을 스스로 되짚어 보는」 걸음은 무엇인가요?","options":[{"t":"⑤ 돌아보며 평가하기","correct":true},{"t":"① 필요한 일 찾기","mis":"SO4-2-u1-X26"},{"t":"② 참여 방법 찾기","mis":"SO4-2-u1-X26"},{"t":"④ 달라진 점 쓰기","mis":"SO4-2-u1-X26"}],"explanation":["마지막 걸음이에요.","되돌아봐요.","평가하기예요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#1','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',2,'mc','auto','참여하기 전과 참여한 뒤에서 「통학로의 벽」은 어떻게 달라졌나요?',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"mc","stem":"참여하기 전과 참여한 뒤에서 「통학로의 벽」은 어떻게 달라졌나요?","options":[{"t":"주민들이 함께 그린 벽화가 생겼어요","correct":true},{"t":"벽이 더 낡았어요","mis":"SO4-2-u1-X26"},{"t":"벽이 없어졌어요","mis":"SO4-2-u1-X26"},{"t":"달라지지 않았어요","mis":"SO4-2-u1-X26"}],"explanation":["같은 자리를 견줘요.","전에는 낡았어요.","벽화가 생겼어요."],"asset":{"type":"passage","lines":["참여하기 전 — 통학로의 벽은 낡고, 학교에 오는 길은 위험하고, 학교에 대한 주민들의 관심은 낮아요.","참여한 뒤 — 통학로가 예쁘게 꾸며지고, 주민들이 함께 그린 벽화가 생기고, 주민들의 관심이 높아졌어요."],"title":"참여하기 전과 참여한 뒤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#2','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',2,'ox','auto','주민 자치에 참여한 뒤에는 참여한 과정을 돌아보며 스스로 평가해요.',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"ox","stem":"주민 자치에 참여한 뒤에는 참여한 과정을 돌아보며 스스로 평가해요.","answer":"O","reason_options":[{"t":"잘한 점과 아쉬운 점을 살펴 다음 참여에 도움을 받을 수 있기 때문에","correct":true},{"t":"참여만 하면 끝이기 때문에","mis":"SO4-2-u1-X26"}],"mis":"SO4-2-u1-X26","explanation":["마지막 걸음이에요.","돌아봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#3','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',3,'mc','auto','「회의로 협의하기」는 다섯 걸음 가운데 어느 걸음에 속하나요?',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"mc","stem":"「회의로 협의하기」는 다섯 걸음 가운데 어느 걸음에 속하나요?","options":[{"t":"② 참여 방법 찾기","correct":true},{"t":"① 필요한 일 찾기","mis":"SO4-2-u1-X26"},{"t":"④ 달라진 점 쓰기","mis":"SO4-2-u1-X26"},{"t":"⑤ 돌아보며 평가하기","mis":"SO4-2-u1-X26"}],"explanation":["어떻게 참여할지 정해요.","방법을 찾아요.","②예요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#4','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',3,'error','auto','주민 자치 참여를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X27','SO4-2-u1-X26']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"error","stem":"주민 자치 참여를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「주민끼리 해결하기 어려운 문제는 그냥 두는 수밖에 없어.」","correct":true,"mis_target":"SO4-2-u1-X27"},{"t":"친구 가 — 「필요한 일을 먼저 찾아야 해.」","mis":"SO4-2-u1-X26"},{"t":"친구 나 — 「우리도 친구들과 캠페인을 할 수 있어.」","mis":"SO4-2-u1-X26"}],"explanation":["그냥 둘까요?","도움을 청해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#5','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',3,'mc','auto','통학로가 위험하다는 일을 찾은 뒤 바로 다음에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X27']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"mc","stem":"통학로가 위험하다는 일을 찾은 뒤 바로 다음에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"캠페인·게시판·회의 같은 참여 방법을 찾아요","correct":true},{"t":"달라진 점부터 써요","mis":"SO4-2-u1-X26"},{"t":"평가부터 해요","mis":"SO4-2-u1-X26"},{"t":"아무것도 하지 않고 기다려요","mis":"SO4-2-u1-X27"}],"explanation":["일을 찾았어요.","다음은 방법이에요.","참여 방법을 찾아요."],"asset":{"type":"passage","lines":["① 필요한 일 찾기 — 학교에 오는 통학로가 위험해요.","② 참여 방법 찾기 — 누리집 게시판 · 캠페인 문구 · 회의로 협의","③ 계획을 세워 실천하기 — 캠페인 · 곳곳을 예쁘게 꾸미기 · 벽화 그리기","④ 달라진 점 쓰기 — 더 안전하게 학교에 와요 · 주민들의 관심이 높아졌어요","⑤ 돌아보며 평가하기"],"title":"주민 자치 참여 다섯 걸음(교과서 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#6','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',3,'ox','auto','참여하기 전 장면과 참여한 뒤 장면의 같은 자리를 견주면 달라진 점을 찾을 수 있어요.',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"ox","stem":"참여하기 전 장면과 참여한 뒤 장면의 같은 자리를 견주면 달라진 점을 찾을 수 있어요.","answer":"O","reason_options":[{"t":"같은 자리가 참여 전과 후에 어떻게 바뀌었는지 보이기 때문에","correct":true},{"t":"참여한 뒤 장면만 보면 충분하기 때문에","mis":"SO4-2-u1-X26"}],"mis":"SO4-2-u1-X26","explanation":["같은 자리예요.","견줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["참여하기 전 — 통학로의 벽은 낡고, 학교에 오는 길은 위험하고, 학교에 대한 주민들의 관심은 낮아요.","참여한 뒤 — 통학로가 예쁘게 꾸며지고, 주민들이 함께 그린 벽화가 생기고, 주민들의 관심이 높아졌어요."],"title":"참여하기 전과 참여한 뒤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#7','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',3,'mc','auto','통학로 예시에서 공공 기관에 도움을 청하기에 가장 알맞은 일은 무엇인가요?',ARRAY['SO4-2-u1-X27','SO4-2-u1-X26']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"mc","stem":"통학로 예시에서 공공 기관에 도움을 청하기에 가장 알맞은 일은 무엇인가요?","options":[{"t":"건널목에 신호등을 새로 놓아 달라고 요청하기","correct":true},{"t":"친구들과 캠페인 문구 만들기","mis":"SO4-2-u1-X27"},{"t":"벽화 그리기에 참여하기","mis":"SO4-2-u1-X27"},{"t":"돌아보며 평가하기","mis":"SO4-2-u1-X26"}],"explanation":["주민 힘으로 어려워요.","시설이 필요해요.","공공 기관에 청해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#8','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',4,'mc','auto','통학로 예시를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X27']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C10","difficulty":4,"kind":"mc","stem":"통학로 예시를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어린이도 주민으로서 관심을 갖고 참여하면 지역을 더 안전하고 나은 곳으로 바꿀 수 있어요","correct":true},{"t":"통학로는 어른만 고칠 수 있어요","mis":"SO4-2-u1-X26"},{"t":"지역의 일은 공공 기관이 다 해 줘요","mis":"SO4-2-u1-X27"},{"t":"참여해도 지역은 달라지지 않아요","mis":"SO4-2-u1-X26"}],"explanation":["친구들이 참여했어요.","통학로가 바뀌었어요.","지역이 나아졌어요."],"asset":{"type":"passage","lines":["참여하기 전 — 통학로의 벽은 낡고, 학교에 오는 길은 위험하고, 학교에 대한 주민들의 관심은 낮아요.","참여한 뒤 — 통학로가 예쁘게 꾸며지고, 주민들이 함께 그린 벽화가 생기고, 주민들의 관심이 높아졌어요."],"title":"참여하기 전과 참여한 뒤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#9','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',4,'mc','auto','「주민 자치와 민주주의」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X18','SO4-2-u1-X22','SO4-2-u1-X20']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C10","difficulty":4,"kind":"mc","stem":"「주민 자치와 민주주의」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"주민이 지역의 주인으로서 다양한 방법으로 참여하면 지역의 일을 민주적으로 해결하고 더 살기 좋은 지역을 만들 수 있어요","correct":true},{"t":"주민 자치는 몇몇 사람이 대신 해 주는 일이에요","mis":"SO4-2-u1-X18"},{"t":"주민 참여 방법은 주민 투표 하나뿐이에요","mis":"SO4-2-u1-X22"},{"t":"주민 참여는 지역 생활과 관계없어요","mis":"SO4-2-u1-X20"}],"explanation":["주민이 주인이에요.","여러 방법으로 참여해요.","살기 좋아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_L10_challenge#10','soc',4,2,'u1','L10','g4_2_soc_u1_L10_challenge','lesson_challenge','SO4-2-u1-C10',4,'essay','teacher','우리 지역에서 주민 자치가 필요한 일을 하나 찾아, 참여 방법과 참여한 뒤 기대하는 달라진 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C10","difficulty":4,"kind":"essay","stem":"우리 지역에서 주민 자치가 필요한 일을 하나 찾아, 참여 방법과 참여한 뒤 기대하는 달라진 점을 쓰세요.","answer_guide":{"answer":"예: 공원 산책로에 쓰레기가 많은 일을 찾았어요. 친구들과 「깨끗한 산책로를 함께 지켜요」 캠페인 문구를 만들고, 주민들과 함께 청소하며, 쓰레기통이 더 필요하면 공공 기관 누리집 게시판에 의견을 올릴 거예요. 그러면 산책로가 깨끗해지고 주민들의 관심도 높아질 거예요.","scoring_points":["필요한 일을 찾았는가","참여 방법을 썼는가","기대하는 달라진 점을 썼는가"]},"explanation":["일을 찾아요.","방법을 정해요.","달라질 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#1','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C1',1,'mc','auto','민주주의에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"mc","stem":"민주주의에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"구성원들의 다양한 의견을 반영해 공동의 문제를 함께 결정하는 방식이에요","correct":true},{"t":"한 사람이 모두의 일을 정하는 방식이에요","mis":"SO4-2-u1-X01"},{"t":"가장 빨리 정하는 방식이에요","mis":"SO4-2-u1-X01"},{"t":"아무도 정하지 않는 방식이에요","mis":"SO4-2-u1-X01"}],"explanation":["다양한 의견이에요.","함께 정해요.","민주주의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#2','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C2',1,'mc','auto','민주주의를 실천하는 태도로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X05']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"mc","stem":"민주주의를 실천하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"상대방의 의견을 존중하며 대화해요","correct":true},{"t":"내 의견만 크게 말해요","mis":"SO4-2-u1-X05"},{"t":"다른 의견은 무시해요","mis":"SO4-2-u1-X05"},{"t":"회의에서 아무 말도 하지 않아요","mis":"SO4-2-u1-X05"}],"explanation":["상대방이 있어요.","존중해요.","대화해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#3','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C3',1,'mc','auto','신문 ②에서 그늘막을 설치하기로 정한 곳은 어디인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"mc","stem":"신문 ②에서 그늘막을 설치하기로 정한 곳은 어디인가요?","options":[{"t":"전교 회의","correct":true},{"t":"교장실","mis":"SO4-2-u1-X10"},{"t":"학부모 모임","mis":"SO4-2-u1-X10"},{"t":"운동장","mis":"SO4-2-u1-X10"}],"explanation":["제안을 모았어요.","토의했어요.","전교 회의예요."],"asset":{"type":"passage","lines":["학생 자치회가 학급마다 학교에 필요한 것을 제안받았다.","전교 회의에서 제안을 토의해 운동장 그늘막을 설치하기로 했다.","학생 참여 예산제로 지원받아 그늘막이 설치됐다."],"title":"신문 ② — 운동장에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#4','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C4',1,'mc','auto','학교에서 민주주의를 실천하는 다섯 걸음 가운데 첫 걸음은 무엇인가요?',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"mc","stem":"학교에서 민주주의를 실천하는 다섯 걸음 가운데 첫 걸음은 무엇인가요?","options":[{"t":"해결하고 싶은 일 확인하기","correct":true},{"t":"해결 방안 결정하기","mis":"SO4-2-u1-X12"},{"t":"해결 방안 실천하기","mis":"SO4-2-u1-X12"},{"t":"실천 결과 확인하기","mis":"SO4-2-u1-X12"}],"explanation":["무엇이 먼저일까요?","일을 확인해요.","첫 걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#5','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C5',1,'mc','auto','신문 ④의 행사 ㉮·㉯로 함께 얻을 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"mc","stem":"신문 ④의 행사 ㉮·㉯로 함께 얻을 수 있는 것은 무엇인가요?","options":[{"t":"책 읽는 학교","correct":true},{"t":"깨끗한 학교","mis":"SO4-2-u1-X16"},{"t":"안전한 학교","mis":"SO4-2-u1-X16"},{"t":"조용한 운동장","mis":"SO4-2-u1-X16"}],"explanation":["두 행사를 봐요.","책이 있어요.","책 읽는 학교예요."],"asset":{"type":"passage","lines":["9~10월 목표 — 책 읽는 학교 만들기","행사 ㉮ 책 나눔 장터 · 행사 ㉯ 독서 퀴즈 대회","임원들은 학급마다 원하는 행사를 먼저 물어 계획을 세웠다."],"title":"신문 ④ — 학생 자치회 행사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#6','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C6',1,'mc','auto','주민이 지역의 주인으로서 지역의 일에 참여해 함께 문제를 해결해 나가는 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"mc","stem":"주민이 지역의 주인으로서 지역의 일에 참여해 함께 문제를 해결해 나가는 것은 무엇인가요?","options":[{"t":"주민 자치","correct":true},{"t":"학생 자치","mis":"SO4-2-u1-X18"},{"t":"지역 축제","mis":"SO4-2-u1-X18"},{"t":"공공 기관","mis":"SO4-2-u1-X18"}],"explanation":["지역의 주인이에요.","주민이 참여해요.","주민 자치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#7','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C7',1,'mc','auto','지역에서 일어나는 일은 주민들의 무엇에 많은 영향을 미치나요?',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C7","difficulty":1,"kind":"mc","stem":"지역에서 일어나는 일은 주민들의 무엇에 많은 영향을 미치나요?","options":[{"t":"생활","correct":true},{"t":"이름","mis":"SO4-2-u1-X20"},{"t":"취미","mis":"SO4-2-u1-X20"},{"t":"키","mis":"SO4-2-u1-X20"}],"explanation":["매일의 삶이에요.","생◯이에요.","생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#8','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C9',1,'mc','auto','우리 지역 신문에서 주민 자치와 관련 있는 기사를 찾아보는 조사 방법은 무엇인가요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"mc","stem":"우리 지역 신문에서 주민 자치와 관련 있는 기사를 찾아보는 조사 방법은 무엇인가요?","options":[{"t":"지역 신문 찾아보기","correct":true},{"t":"지역 주민 면담하기","mis":"SO4-2-u1-X24"},{"t":"지역 게시판 찾아보기","mis":"SO4-2-u1-X24"},{"t":"공공 기관 방문하기","mis":"SO4-2-u1-X24"}],"explanation":["기사가 있어요.","신문이에요.","신문 찾아보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#9','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C1',2,'mc','auto','몇몇 사람의 뜻대로만 결정하면 생길 수 있는 문제는 무엇인가요?',ARRAY['SO4-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"mc","stem":"몇몇 사람의 뜻대로만 결정하면 생길 수 있는 문제는 무엇인가요?","options":[{"t":"여러 사람의 의견을 반영할 수 없어요","correct":true},{"t":"결정이 아예 나지 않아요","mis":"SO4-2-u1-X02"},{"t":"모두가 더 만족해요","mis":"SO4-2-u1-X02"},{"t":"문제가 저절로 사라져요","mis":"SO4-2-u1-X02"}],"explanation":["몇몇만 정했어요.","다른 의견은 빠져요.","반영할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#10','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C2',2,'mc','auto','신문 ①에서 반대 의견을 낸 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X08']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"mc","stem":"신문 ①에서 반대 의견을 낸 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"그림 잘 그리는 친구들만 꾸미면 다른 친구들의 생각이 빠지기 때문이에요","correct":true},{"t":"처음 의견을 낸 친구가 싫어서예요","mis":"SO4-2-u1-X08"},{"t":"그 의견이 가장 먼저 나와서예요","mis":"SO4-2-u1-X08"},{"t":"게시판이 너무 작아서예요","mis":"SO4-2-u1-X08"}],"explanation":["반대 까닭을 읽어요.","생각이 빠져요.","그래서 반대했어요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#11','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C3',2,'mc','auto','신문 ②를 세 걸음(의견 모으기 → 회의로 정하기 → 함께 실천하기)에 맞추면 「전교 회의에서 토의」는 어느 걸음인가요?',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":11,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"mc","stem":"신문 ②를 세 걸음(의견 모으기 → 회의로 정하기 → 함께 실천하기)에 맞추면 「전교 회의에서 토의」는 어느 걸음인가요?","options":[{"t":"회의로 정하기","correct":true},{"t":"의견 모으기","mis":"SO4-2-u1-X11"},{"t":"함께 실천하기","mis":"SO4-2-u1-X11"},{"t":"어느 걸음도 아니에요","mis":"SO4-2-u1-X11"}],"explanation":["제안은 모으기예요.","토의는 다음이에요.","회의로 정하기예요."],"asset":{"type":"passage","lines":["학생 자치회가 학급마다 학교에 필요한 것을 제안받았다.","전교 회의에서 제안을 토의해 운동장 그늘막을 설치하기로 했다.","학생 참여 예산제로 지원받아 그늘막이 설치됐다."],"title":"신문 ② — 운동장에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#12','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C4',2,'mc','auto','신문 ③에서 ㉡은 다섯 걸음 가운데 어느 걸음인가요?',ARRAY['SO4-2-u1-X12','SO4-2-u1-X15']::text[],false,'{"seq":12,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"mc","stem":"신문 ③에서 ㉡은 다섯 걸음 가운데 어느 걸음인가요?","options":[{"t":"해결 방안 탐색하기","correct":true},{"t":"해결하고 싶은 일 확인하기","mis":"SO4-2-u1-X12"},{"t":"해결 방안 실천하기","mis":"SO4-2-u1-X12"},{"t":"실천 결과 확인하기","mis":"SO4-2-u1-X15"}],"explanation":["방안을 찾았어요.","여러 가지예요.","탐색하기예요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#13','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C6',2,'mc','auto','신문 ⑤가 주민 자치의 모습인 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":13,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"mc","stem":"신문 ⑤가 주민 자치의 모습인 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"주민들이 지역의 일에 참여해 함께 문제를 해결했기 때문이에요","correct":true},{"t":"공공 기관이 혼자 해결했기 때문이에요","mis":"SO4-2-u1-X18"},{"t":"몇몇 주민만 꽃을 봤기 때문이에요","mis":"SO4-2-u1-X18"},{"t":"화단이 다른 지역에 있기 때문이에요","mis":"SO4-2-u1-X18"}],"explanation":["주민 회의를 열었어요.","함께 심어요.","함께 해결해요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 주민 회의를 열었다.","주민들은 동네 공원 화단이 메말라 보기 좋지 않다는 의견을 냈다.","주민들이 함께 꽃을 심고 돌아가며 물을 주기로 했다."],"title":"신문 ⑤ — ○○동 꽃밭 가꾸기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#14','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C7',2,'mc','auto','주민 참여가 활발할 때의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X21']::text[],false,'{"seq":14,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"mc","stem":"주민 참여가 활발할 때의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"불편한 문제를 주민들이 직접 해결할 수 있어요","correct":true},{"t":"문제를 해결하기 어려워져요","mis":"SO4-2-u1-X21"},{"t":"지역이 발전하기 어려워져요","mis":"SO4-2-u1-X21"},{"t":"주민이 원하지 않는 쪽으로 달라져요","mis":"SO4-2-u1-X21"}],"explanation":["참여가 활발해요.","직접 나서요.","해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#15','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C8',2,'mc','auto','신문 ⑥에서 투표판과 사회 관계망 서비스로 투표한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":15,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"mc","stem":"신문 ⑥에서 투표판과 사회 관계망 서비스로 투표한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"더 많은 주민이 쉽게 참여해 의견을 낼 수 있게 하려고","correct":true},{"t":"몇몇 주민만 투표하게 하려고","mis":"SO4-2-u1-X22"},{"t":"투표를 어렵게 하려고","mis":"SO4-2-u1-X22"},{"t":"결과를 숨기려고","mis":"SO4-2-u1-X22"}],"explanation":["방식이 둘이에요.","쉽게 참여해요.","많은 주민이에요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#16','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C9',2,'mc','auto','신문 ⑦ 보고서에서 「알게 된 점」은 언제 쓸 수 있나요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":16,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"mc","stem":"신문 ⑦ 보고서에서 「알게 된 점」은 언제 쓸 수 있나요?","options":[{"t":"조사를 마친 뒤","correct":true},{"t":"조사하기 전","mis":"SO4-2-u1-X25"},{"t":"조사 계획서를 쓸 때","mis":"SO4-2-u1-X25"},{"t":"조사 날짜를 정할 때","mis":"SO4-2-u1-X25"}],"explanation":["알게 된 점이에요.","조사해 봐야 알아요.","마친 뒤예요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#17','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C2',3,'error','auto','신문 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X06','SO4-2-u1-X08','SO4-2-u1-X07']::text[],false,'{"seq":17,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"error","stem":"신문 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「반대 의견이 나왔으니 처음 의견을 낸 친구는 회의에서 빠져야 해.」","correct":true,"mis_target":"SO4-2-u1-X06"},{"t":"친구 가 — 「까닭을 들어 반대했어.」","mis":"SO4-2-u1-X08"},{"t":"친구 다 — 「정한 대로 모두 함께 꾸몄어.」","mis":"SO4-2-u1-X07"}],"explanation":["빠져야 할까요?","고쳐서 냈어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#18','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C4',3,'error','auto','신문 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X15','SO4-2-u1-X14','SO4-2-u1-X12']::text[],false,'{"seq":18,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"error","stem":"신문 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「새 신발장을 놓았으니 바꾼 뒤를 살필 필요는 없어.」","correct":true,"mis_target":"SO4-2-u1-X15"},{"t":"친구 가 — 「무엇을 정하느냐에 따라 방법이 달랐어.」","mis":"SO4-2-u1-X14"},{"t":"친구 나 — 「방안을 찾기 전에 문제를 먼저 확인했어.」","mis":"SO4-2-u1-X12"}],"explanation":["살필 필요 없을까요?","결과를 확인해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#19','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C6',3,'error','auto','주민 자치의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X18','SO4-2-u1-X19']::text[],false,'{"seq":19,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"error","stem":"주민 자치의 뜻을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「주민 자치는 공공 기관이 정해 주민에게 알려 주는 거야.」","correct":true,"mis_target":"SO4-2-u1-X18"},{"t":"친구 나 — 「주민 자치회는 주민을 대표해.」","mis":"SO4-2-u1-X19"},{"t":"친구 다 — 「주민이 참여할 때 민주주의를 실천해.」","mis":"SO4-2-u1-X18"}],"explanation":["누가 정할까요?","주민이 함께해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#20','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C8',3,'error','auto','주민 참여를 언제 하는지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X22','SO4-2-u1-X23']::text[],false,'{"seq":20,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"error","stem":"주민 참여를 언제 하는지 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「주민 참여는 큰 문제가 생겼을 때 한 번만 하면 돼.」","correct":true,"mis_target":"SO4-2-u1-X22"},{"t":"친구 가 — 「공청회에 참석하는 것도 방법이야.」","mis":"SO4-2-u1-X22"},{"t":"친구 다 — 「지역 전체의 이익을 생각해야 해.」","mis":"SO4-2-u1-X23"}],"explanation":["한 번만일까요?","작은 일부터 해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#21','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C10',3,'error','auto','신문 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X26','SO4-2-u1-X22']::text[],false,'{"seq":21,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"error","stem":"신문 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「어린이는 주민 자치에 참여할 수 없으니 어른이 한 일이야.」","correct":true,"mis_target":"SO4-2-u1-X26"},{"t":"친구 가 — 「누리집 게시판에 의견을 올리기로 했어.」","mis":"SO4-2-u1-X22"},{"t":"친구 나 — 「마지막에 잘한 점과 아쉬운 점을 돌아보았어.」","mis":"SO4-2-u1-X26"}],"explanation":["누가 했을까요?","푸른반이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#22','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C3',3,'mc','auto','신문 ②와 신문 ⑥을 견줄 때 비슷한 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X09','SO4-2-u1-X19','SO4-2-u1-X11']::text[],false,'{"seq":22,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"mc","stem":"신문 ②와 신문 ⑥을 견줄 때 비슷한 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"구성원의 의견을 모아 필요한 것을 정해 실제로 바꾸었어요","correct":true},{"t":"한 사람이 모든 것을 정했어요","mis":"SO4-2-u1-X09"},{"t":"학교와 지역은 하는 일이 같아요","mis":"SO4-2-u1-X19"},{"t":"의견을 모으지 않았어요","mis":"SO4-2-u1-X11"}],"explanation":["②는 학교예요.","⑥은 지역이에요.","의견을 모아 바꾸었어요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#23','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C1',4,'mc','auto','신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X09','SO4-2-u1-X06','SO4-2-u1-X15']::text[],false,'{"seq":23,"concept":"SO4-2-u1-C1","difficulty":4,"kind":"mc","stem":"신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학교생활에서도 대화하고 의견을 모아 함께 정하고 실천하며 민주주의를 실천해요","correct":true},{"t":"학교의 일은 선생님만 정해요","mis":"SO4-2-u1-X09"},{"t":"반대 의견이 나오면 회의를 그만둬요","mis":"SO4-2-u1-X06"},{"t":"정한 뒤에는 결과를 살피지 않아요","mis":"SO4-2-u1-X15"}],"explanation":["①은 회의예요.","②③은 학교의 일이에요.","④는 행사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#24','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C2',4,'essay','teacher','신문 ①의 학급 회의에서 볼 수 있는 민주주의를 실천하는 태도 두 가지를 찾아 쓰고, 그 태도가 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u1-C2","difficulty":4,"kind":"essay","stem":"신문 ①의 학급 회의에서 볼 수 있는 민주주의를 실천하는 태도 두 가지를 찾아 쓰고, 그 태도가 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: 반대할 때 까닭을 들어 의견의 장단점을 생각한 태도와, 처음 의견을 고쳐 양보하고 타협한 태도를 볼 수 있어요. 이런 태도가 있어야 서로의 의견을 존중하며 모두가 받아들일 수 있는 방안을 정할 수 있어요.","scoring_points":["태도 두 가지를 찾았는가","신문 내용과 이었는가","필요한 까닭을 썼는가"]},"explanation":["반대 까닭을 봐요.","고친 의견도 봐요.","까닭을 써요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_a#25','soc',4,2,'u1','','g4_2_soc_u1_review_a','unit_review','SO4-2-u1-C3',4,'essay','teacher','신문 ②가 학교에서 민주주의를 실천한 사례인 까닭을 세 걸음(의견 모으기 → 회의로 정하기 → 함께 실천하기)과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u1-C3","difficulty":4,"kind":"essay","stem":"신문 ②가 학교에서 민주주의를 실천한 사례인 까닭을 세 걸음(의견 모으기 → 회의로 정하기 → 함께 실천하기)과 이어 쓰세요.","answer_guide":{"answer":"예: 학생 자치회가 학급마다 필요한 것을 제안받아 의견을 모았고, 전교 회의에서 토의해 그늘막을 설치하기로 정했으며, 학생 참여 예산제로 실제로 설치했어요. 학생들의 의견을 모아 함께 정하고 실천했기 때문에 민주주의를 실천한 사례예요.","scoring_points":["의견 모으기를 썼는가","회의로 정하기를 썼는가","함께 실천하기를 썼는가"]},"explanation":["제안을 모았어요.","토의했어요.","설치했어요."],"asset":{"type":"passage","lines":["학생 자치회가 학급마다 학교에 필요한 것을 제안받았다.","전교 회의에서 제안을 토의해 운동장 그늘막을 설치하기로 했다.","학생 참여 예산제로 지원받아 그늘막이 설치됐다."],"title":"신문 ② — 운동장에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#1','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C1',1,'sa','auto','가정에서 가족이 함께 의논해 주말 계획을 정하는 회의를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"sa","stem":"가정에서 가족이 함께 의논해 주말 계획을 정하는 회의를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["가족회의","가족 회의"],"explanation":["가족이 모여요.","가족◯◯예요.","가족회의예요."],"mis":"SO4-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#2','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C2',1,'sa','auto','서로 조금씩 물러나 알맞게 의견을 맞추는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"sa","stem":"서로 조금씩 물러나 알맞게 의견을 맞추는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["타협"],"explanation":["양보하고 ◯◯해요.","타◯이에요.","타협이에요."],"mis":"SO4-2-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#3','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C3',1,'sa','auto','학생들이 대표를 뽑아 구성하는 것은 「학생 ○○회」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"sa","stem":"학생들이 대표를 뽑아 구성하는 것은 「학생 ○○회」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["자치"],"explanation":["스스로 다스려요.","자◯예요.","자치예요."],"mis":"SO4-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#4','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C4',1,'sa','auto','신문 ③에서 신발장 모양을 정할 때 쓴 방법은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"sa","stem":"신문 ③에서 신발장 모양을 정할 때 쓴 방법은 무엇인가요? 네 글자로 쓰세요.","answer":["설문조사","설문 조사"],"explanation":["여러 사람에게 물어요.","설문◯◯예요.","설문조사예요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"},"mis":"SO4-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#5','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C5',1,'sa','auto','학교 행사를 계획할 때 행사의 내용뿐 아니라 행사로 얻을 수 있는 ○○도 생각해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"sa","stem":"학교 행사를 계획할 때 행사의 내용뿐 아니라 행사로 얻을 수 있는 ○○도 생각해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["결과"],"explanation":["행사를 한 뒤예요.","결◯예요.","결과예요."],"mis":"SO4-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#6','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C6',1,'sa','auto','신문 ⑤에서 주민들의 의견을 모은 모임은 「주민 ○○」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"sa","stem":"신문 ⑤에서 주민들의 의견을 모은 모임은 「주민 ○○」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["회의"],"explanation":["모여서 의논해요.","◯의예요.","회의예요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 주민 회의를 열었다.","주민들은 동네 공원 화단이 메말라 보기 좋지 않다는 의견을 냈다.","주민들이 함께 꽃을 심고 돌아가며 물을 주기로 했다."],"title":"신문 ⑤ — ○○동 꽃밭 가꾸기"},"mis":"SO4-2-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#7','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C8',1,'sa','auto','신문 ⑥에서 쉼터에 놓을 것을 정한 방법은 「주민 ○○」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"sa","stem":"신문 ⑥에서 쉼터에 놓을 것을 정한 방법은 「주민 ○○」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["투표"],"explanation":["표를 내요.","투◯예요.","투표예요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"},"mis":"SO4-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#8','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C10',1,'sa','auto','주민 자치 참여 다섯 걸음 가운데 마지막은 「돌아보며 ○○하기」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"sa","stem":"주민 자치 참여 다섯 걸음 가운데 마지막은 「돌아보며 ○○하기」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["평가"],"explanation":["잘한 점을 살펴요.","◯가예요.","평가예요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"},"mis":"SO4-2-u1-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#9','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C1',2,'match','auto','민주주의를 실천하는 곳과 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"match","stem":"민주주의를 실천하는 곳과 모습을 알맞게 이으세요.","pairs":[{"l":"가정","r":"가족회의"},{"l":"학교","r":"학급 회의"},{"l":"지역","r":"주민 회의"},{"l":"국가","r":"투표"}],"mis":"SO4-2-u1-X03","explanation":["집이에요.","학교와 지역이에요.","나라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#10','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C2',2,'match','auto','신문 ①의 모습과 태도를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"match","stem":"신문 ①의 모습과 태도를 알맞게 이으세요.","pairs":[{"l":"반대 까닭을 들어요","r":"옳고 그름과 장단점 생각하기"},{"l":"처음 의견을 고쳐 내요","r":"양보하고 타협하기"},{"l":"정한 대로 함께 꾸며요","r":"모두 적극적으로 실천하기"}],"mis":"SO4-2-u1-X06","explanation":["까닭이 있어요.","고쳤어요.","함께 꾸몄어요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#11','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C3',2,'match','auto','신문 ②의 일과 세 걸음을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"match","stem":"신문 ②의 일과 세 걸음을 알맞게 이으세요.","pairs":[{"l":"학급마다 필요한 것을 제안받음","r":"의견 모으기"},{"l":"전교 회의에서 토의해 정함","r":"회의로 정하기"},{"l":"그늘막이 설치됨","r":"함께 실천하기"}],"mis":"SO4-2-u1-X11","explanation":["제안을 받았어요.","토의했어요.","설치했어요."],"asset":{"type":"passage","lines":["학생 자치회가 학급마다 학교에 필요한 것을 제안받았다.","전교 회의에서 제안을 토의해 운동장 그늘막을 설치하기로 했다.","학생 참여 예산제로 지원받아 그늘막이 설치됐다."],"title":"신문 ② — 운동장에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#12','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C4',2,'match','auto','신문 ③의 일과 걸음을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"match","stem":"신문 ③의 일과 걸음을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"해결하고 싶은 일 확인하기"},{"l":"㉢","r":"민주적인 방법으로 결정하기"},{"l":"㉣","r":"해결 방안 실천하기"},{"l":"㉤","r":"실천 결과 확인하기"}],"mis":"SO4-2-u1-X12","explanation":["㉠은 문제예요.","㉢은 정하기예요.","㉣·㉤은 실천과 확인이에요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
