INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#14','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C7',2,'match','auto','주민 참여가 활발할 때와 활발하지 않을 때를 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"match","stem":"주민 참여가 활발할 때와 활발하지 않을 때를 알맞게 이으세요.","pairs":[{"l":"활발할 때","r":"원하는 방향으로 지역이 달라져요"},{"l":"활발하지 않을 때","r":"지역이 더 나아지기 어려워요"}],"mis":"SO4-2-u1-X21","explanation":["참여가 있어요.","참여가 없어요.","반대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#15','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C8',2,'match','auto','참여 방법과 알맞은 모습을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"match","stem":"참여 방법과 알맞은 모습을 이으세요.","pairs":[{"l":"주민 투표","r":"투표판에 표 내기"},{"l":"누리집 게시판","r":"의견 글 올리기"},{"l":"자원봉사","r":"축제 일 돕기"},{"l":"벽화 그리기","r":"담벼락 꾸미기"}],"mis":"SO4-2-u1-X22","explanation":["투표예요.","글을 올려요.","돕고 꾸며요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#16','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C10',2,'match','auto','신문 ⑧의 일과 참여 걸음을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"match","stem":"신문 ⑧의 일과 참여 걸음을 알맞게 이으세요.","pairs":[{"l":"①","r":"필요한 일 찾기"},{"l":"②","r":"참여 방법 찾기"},{"l":"③","r":"계획을 세워 실천하기"},{"l":"④","r":"달라진 점 쓰기"}],"mis":"SO4-2-u1-X26","explanation":["①은 일 찾기예요.","②는 방법이에요.","③④는 실천과 달라진 점이에요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#17','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C1',3,'mc','auto','신문 ①의 처음 의견대로 정했다면 어떤 점이 아쉬웠을까요?',ARRAY['SO4-2-u1-X02']::text[],false,'{"seq":17,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"mc","stem":"신문 ①의 처음 의견대로 정했다면 어떤 점이 아쉬웠을까요?","options":[{"t":"그림 잘 그리는 몇몇 친구의 생각만 들어가 다른 친구들의 의견이 반영되지 못해요","correct":true},{"t":"게시판이 더 넓어져요","mis":"SO4-2-u1-X02"},{"t":"모든 친구의 생각이 들어가요","mis":"SO4-2-u1-X02"},{"t":"아쉬운 점이 하나도 없어요","mis":"SO4-2-u1-X02"}],"explanation":["몇몇만 꾸며요.","다른 친구는 빠져요.","반영되지 못해요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#18','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C4',3,'mc','auto','신문 ③에서 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정한 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X14','SO4-2-u1-X13']::text[],false,'{"seq":18,"concept":"SO4-2-u1-C4","difficulty":3,"kind":"mc","stem":"신문 ③에서 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정한 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"무엇을 정하느냐에 따라 알맞은 민주적인 방법이 달라요","correct":true},{"t":"설문조사가 언제나 더 나은 방법이에요","mis":"SO4-2-u1-X14"},{"t":"정하는 방법은 한 가지뿐이에요","mis":"SO4-2-u1-X14"},{"t":"규칙은 정하지 않아도 돼요","mis":"SO4-2-u1-X13"}],"explanation":["정할 것이 둘이에요.","방법도 둘이에요.","알맞은 방법이 달라요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#19','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C6',3,'mc','auto','신문 ⑤와 신문 ⑥에서 같은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18','SO4-2-u1-X22']::text[],false,'{"seq":19,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"mc","stem":"신문 ⑤와 신문 ⑥에서 같은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주민들이 지역의 일에 참여해 함께 정했어요","correct":true},{"t":"공공 기관이 혼자 정했어요","mis":"SO4-2-u1-X18"},{"t":"정하는 방법이 똑같았어요","mis":"SO4-2-u1-X22"},{"t":"몇몇 주민만 참여했어요","mis":"SO4-2-u1-X18"}],"explanation":["⑤는 회의예요.","⑥은 투표예요.","주민이 함께 정했어요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#20','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C9',3,'mc','auto','신문 ⑦ 보고서의 칸 가운데 조사하기 전에 미리 정할 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u1-X25']::text[],false,'{"seq":20,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"mc","stem":"신문 ⑦ 보고서의 칸 가운데 조사하기 전에 미리 정할 수 있는 것은 무엇인가요?","options":[{"t":"조사 목적","correct":true},{"t":"조사 내용","mis":"SO4-2-u1-X25"},{"t":"알게 된 점","mis":"SO4-2-u1-X25"},{"t":"조사 모습","mis":"SO4-2-u1-X25"}],"explanation":["무엇을 알아볼까요?","미리 정해요.","조사 목적이에요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#21','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C10',3,'mc','auto','신문 ⑧에서 쓰레기통이 모자라 주민 힘만으로 해결하기 어렵다면 어떻게 할 수 있나요?',ARRAY['SO4-2-u1-X27','SO4-2-u1-X23']::text[],false,'{"seq":21,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"mc","stem":"신문 ⑧에서 쓰레기통이 모자라 주민 힘만으로 해결하기 어렵다면 어떻게 할 수 있나요?","options":[{"t":"공공 기관에 쓰레기통을 더 놓아 달라고 도움을 청해요","correct":true},{"t":"쓰레기를 그대로 둬요","mis":"SO4-2-u1-X27"},{"t":"다른 동네에 버려요","mis":"SO4-2-u1-X23"},{"t":"캠페인을 그만둬요","mis":"SO4-2-u1-X27"}],"explanation":["주민 힘으로 어려워요.","도움이 필요해요.","공공 기관에 청해요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#22','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C5',3,'error','auto','신문 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u1-X16','SO4-2-u1-X17']::text[],false,'{"seq":22,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"error","stem":"신문 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「행사는 이름만 멋있으면 무엇을 얻는지는 몰라도 돼.」","correct":true,"mis_target":"SO4-2-u1-X16"},{"t":"친구 나 — 「두 행사는 책 읽는 학교라는 같은 목표를 가져.」","mis":"SO4-2-u1-X16"},{"t":"친구 다 — 「임원들이 학생들의 생각을 물었어.」","mis":"SO4-2-u1-X17"}],"explanation":["얻는 것이 중요해요.","이름만이 아니에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["9~10월 목표 — 책 읽는 학교 만들기","행사 ㉮ 책 나눔 장터 · 행사 ㉯ 독서 퀴즈 대회","임원들은 학급마다 원하는 행사를 먼저 물어 계획을 세웠다."],"title":"신문 ④ — 학생 자치회 행사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#23','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C6',4,'mc','auto','신문 ⑤~⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X18','SO4-2-u1-X22','SO4-2-u1-X26']::text[],false,'{"seq":23,"concept":"SO4-2-u1-C6","difficulty":4,"kind":"mc","stem":"신문 ⑤~⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"주민이 지역의 주인으로서 여러 방법으로 참여하면 지역의 일을 함께 해결하고 더 살기 좋은 지역이 돼요","correct":true},{"t":"지역의 일은 공공 기관만 해요","mis":"SO4-2-u1-X18"},{"t":"주민 참여 방법은 한 가지뿐이에요","mis":"SO4-2-u1-X22"},{"t":"어린이는 지역의 일에 참여할 수 없어요","mis":"SO4-2-u1-X26"}],"explanation":["⑤⑥은 주민이에요.","⑦⑧은 우리 반이에요.","함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#24','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C4',4,'essay','teacher','신문 ③을 다섯 걸음(확인 → 탐색 → 결정 → 실천 → 결과 확인)에 맞추어 정리하고, ㉤ 다음에 할 수 있는 일을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u1-C4","difficulty":4,"kind":"essay","stem":"신문 ③을 다섯 걸음(확인 → 탐색 → 결정 → 실천 → 결과 확인)에 맞추어 정리하고, ㉤ 다음에 할 수 있는 일을 하나 쓰세요.","answer_guide":{"answer":"예: ㉠은 해결하고 싶은 일 확인, ㉡은 방안 탐색, ㉢은 민주적인 방법으로 결정, ㉣은 실천, ㉤은 결과 확인이에요. ㉤ 다음에는 아쉬운 점을 친구들에게 물어 규칙을 고치거나, 학교에서 민주적으로 해결할 다른 일이 있는지 살펴볼 수 있어요.","scoring_points":["다섯 걸음에 맞추었는가","걸음의 차례가 바른가","다음에 할 일을 썼는가"]},"explanation":["㉠부터 맞춰요.","차례를 지켜요.","다음 일을 써요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_b#25','soc',4,2,'u1','','g4_2_soc_u1_review_b','unit_review','SO4-2-u1-C5',4,'essay','teacher','신문 ④처럼 우리 학교 11~12월 행사를 하나 계획하고, 그 행사로 얻을 수 있는 것과 학생들의 생각을 반영할 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u1-C5","difficulty":4,"kind":"essay","stem":"신문 ④처럼 우리 학교 11~12월 행사를 하나 계획하고, 그 행사로 얻을 수 있는 것과 학생들의 생각을 반영할 방법을 쓰세요.","answer_guide":{"answer":"예: 11~12월에 「고마운 분께 편지 쓰기」 행사를 하고 싶어요. 학교에서 우리를 돕는 분들께 감사하는 마음을 나누는 따뜻한 학교를 만들 수 있어요. 학급마다 하고 싶은 행사를 먼저 묻고 의견을 모아 정할 거예요.","scoring_points":["행사를 계획했는가","얻는 것을 썼는가","생각을 반영할 방법을 썼는가"]},"explanation":["행사를 정해요.","얻는 것을 써요.","묻는 방법을 써요."],"asset":{"type":"passage","lines":["9~10월 목표 — 책 읽는 학교 만들기","행사 ㉮ 책 나눔 장터 · 행사 ㉯ 독서 퀴즈 대회","임원들은 학급마다 원하는 행사를 먼저 물어 계획을 세웠다."],"title":"신문 ④ — 학생 자치회 행사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#1','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C1',1,'ox','auto','민주주의 사회에서는 구성원 모두가 존중받아요.',ARRAY['SO4-2-u1-X04']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"ox","stem":"민주주의 사회에서는 구성원 모두가 존중받아요.","answer":"O","reason_options":[{"t":"모두가 평등한 입장에서 의견을 말할 수 있기 때문에","correct":true},{"t":"일부 사람만 존중받기 때문에","mis":"SO4-2-u1-X04"}],"mis":"SO4-2-u1-X04","explanation":["누가 존중받나요?","모두예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#2','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C2',1,'ox','auto','신문 ①에서 처음 의견을 낸 친구는 반대 까닭을 듣고 의견을 고쳤어요.',ARRAY['SO4-2-u1-X06']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"ox","stem":"신문 ①에서 처음 의견을 낸 친구는 반대 까닭을 듣고 의견을 고쳤어요.","answer":"O","reason_options":[{"t":"「모둠마다 한 칸씩 맡아 꾸미자」로 고쳐 다시 냈기 때문에","correct":true},{"t":"처음 의견을 끝까지 그대로 주장했기 때문에","mis":"SO4-2-u1-X06"}],"mis":"SO4-2-u1-X06","explanation":["반대가 나왔어요.","의견을 고쳤어요.","그래서 O예요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#3','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C3',1,'ox','auto','학교의 일은 학생·교사·학부모가 함께 의논하며 해결해 나가요.',ARRAY['SO4-2-u1-X09']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"ox","stem":"학교의 일은 학생·교사·학부모가 함께 의논하며 해결해 나가요.","answer":"O","reason_options":[{"t":"세 구성원 모두 학교 구성원이기 때문에","correct":true},{"t":"교사만 학교 구성원이기 때문에","mis":"SO4-2-u1-X09"}],"mis":"SO4-2-u1-X09","explanation":["학교 구성원이에요.","셋이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#4','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C4',1,'ox','auto','신문 ③의 ㉤은 실천 결과를 확인하는 걸음이에요.',ARRAY['SO4-2-u1-X15']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"ox","stem":"신문 ③의 ㉤은 실천 결과를 확인하는 걸음이에요.","answer":"O","reason_options":[{"t":"바꾼 뒤를 살피고 아쉬운 점을 고쳐 가기로 했기 때문에","correct":true},{"t":"해결 방안을 처음 찾는 걸음이기 때문에","mis":"SO4-2-u1-X15"}],"mis":"SO4-2-u1-X15","explanation":["바꾼 뒤를 살폈어요.","결과를 확인해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#5','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C5',1,'ox','auto','신문 ④에서 임원들은 학급마다 원하는 행사를 먼저 물었어요.',ARRAY['SO4-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"ox","stem":"신문 ④에서 임원들은 학급마다 원하는 행사를 먼저 물었어요.","answer":"O","reason_options":[{"t":"학생들의 생각을 반영하려고 했기 때문에","correct":true},{"t":"임원끼리만 정했기 때문에","mis":"SO4-2-u1-X17"}],"mis":"SO4-2-u1-X17","explanation":["먼저 물었어요.","생각을 반영해요.","그래서 O예요."],"asset":{"type":"passage","lines":["9~10월 목표 — 책 읽는 학교 만들기","행사 ㉮ 책 나눔 장터 · 행사 ㉯ 독서 퀴즈 대회","임원들은 학급마다 원하는 행사를 먼저 물어 계획을 세웠다."],"title":"신문 ④ — 학생 자치회 행사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#6','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C6',1,'ox','auto','신문 ⑤에서 주민들은 함께 꽃을 심고 돌아가며 물을 주기로 했어요.',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"ox","stem":"신문 ⑤에서 주민들은 함께 꽃을 심고 돌아가며 물을 주기로 했어요.","answer":"O","reason_options":[{"t":"주민들이 지역의 일에 함께 참여했기 때문에","correct":true},{"t":"공공 기관이 혼자 정했기 때문에","mis":"SO4-2-u1-X18"}],"mis":"SO4-2-u1-X18","explanation":["주민이 정했어요.","함께해요.","그래서 O예요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 주민 회의를 열었다.","주민들은 동네 공원 화단이 메말라 보기 좋지 않다는 의견을 냈다.","주민들이 함께 꽃을 심고 돌아가며 물을 주기로 했다."],"title":"신문 ⑤ — ○○동 꽃밭 가꾸기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#7','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C8',1,'ox','auto','지역 청소하기도 주민 참여의 방법이에요.',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"ox","stem":"지역 청소하기도 주민 참여의 방법이에요.","answer":"O","reason_options":[{"t":"지역의 일에 직접 참여하는 것이기 때문에","correct":true},{"t":"청소는 지역의 일이 아니기 때문에","mis":"SO4-2-u1-X22"}],"mis":"SO4-2-u1-X22","explanation":["지역을 깨끗하게 해요.","직접 참여해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#8','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C9',1,'ox','auto','신문 ⑦의 모둠은 보호자와 함께, 미리 허락을 받고 면담했어요.',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C9","difficulty":1,"kind":"ox","stem":"신문 ⑦의 모둠은 보호자와 함께, 미리 허락을 받고 면담했어요.","answer":"O","reason_options":[{"t":"조사할 때 지킬 점을 지켰기 때문에","correct":true},{"t":"허락 없이 찾아가는 것이 좋기 때문에","mis":"SO4-2-u1-X24"}],"mis":"SO4-2-u1-X24","explanation":["보호자와 갔어요.","허락받았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#9','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C1',2,'ox','auto','결정만 나면 두 사람의 의견만 들어가도 민주적인 결정이에요.',ARRAY['SO4-2-u1-X02']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"ox","stem":"결정만 나면 두 사람의 의견만 들어가도 민주적인 결정이에요.","answer":"X","reason_options":[{"t":"다양한 의견이 반영되어야 민주적인 결정이기 때문에","correct":true},{"t":"결정이 나면 모두의 의견이 들어간 것이기 때문에","mis":"SO4-2-u1-X02"}],"mis":"SO4-2-u1-X02","explanation":["결정은 났어요.","의견은 둘뿐이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#10','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C2',2,'ox','auto','신문 ①에서 반대 의견이 나왔으니 처음 의견은 버려졌어요.',ARRAY['SO4-2-u1-X06']::text[],false,'{"seq":10,"concept":"SO4-2-u1-C2","difficulty":2,"kind":"ox","stem":"신문 ①에서 반대 의견이 나왔으니 처음 의견은 버려졌어요.","answer":"X","reason_options":[{"t":"처음 의견을 고쳐 다시 내 모두가 찬성했기 때문에","correct":true},{"t":"반대된 의견은 다시 낼 수 없기 때문에","mis":"SO4-2-u1-X06"}],"mis":"SO4-2-u1-X06","explanation":["버려졌을까요?","고쳐서 냈어요.","그래서 X예요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#11','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C3',2,'ox','auto','학생 참여 예산제는 학생들이 제안한 사업을 학생들이 스스로 기획하고 운영하는 제도예요.',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":11,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"ox","stem":"학생 참여 예산제는 학생들이 제안한 사업을 학생들이 스스로 기획하고 운영하는 제도예요.","answer":"O","reason_options":[{"t":"학생들이 제안하면 예산을 지원하고 학생이 운영하기 때문에","correct":true},{"t":"교사가 모든 사업을 정하기 때문에","mis":"SO4-2-u1-X10"}],"mis":"SO4-2-u1-X10","explanation":["학생이 제안해요.","학생이 운영해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#12','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C4',2,'ox','auto','신문 ③에서 신발장 모양과 사용 규칙은 같은 방법으로 정했어요.',ARRAY['SO4-2-u1-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"ox","stem":"신문 ③에서 신발장 모양과 사용 규칙은 같은 방법으로 정했어요.","answer":"X","reason_options":[{"t":"모양은 설문조사로, 규칙은 학급 회의로 정했기 때문에","correct":true},{"t":"민주적으로 정하는 방법은 한 가지뿐이기 때문에","mis":"SO4-2-u1-X14"}],"mis":"SO4-2-u1-X14","explanation":["㉢을 읽어요.","방법이 둘이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#13','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C6',2,'ox','auto','주민 자치회에는 주민이면 누구나 참여할 수 있어요.',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":13,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"ox","stem":"주민 자치회에는 주민이면 누구나 참여할 수 있어요.","answer":"O","reason_options":[{"t":"구성원이면 누구나 참여해 더 나은 지역을 만들려고 하기 때문에","correct":true},{"t":"정해진 몇 사람만 들어갈 수 있기 때문에","mis":"SO4-2-u1-X19"}],"mis":"SO4-2-u1-X19","explanation":["누가 참여할까요?","주민 누구나예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#14','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C7',2,'ox','auto','주민이 지역을 잘 알기 때문에 주민이 직접 참여하는 것이 중요해요.',ARRAY['SO4-2-u1-X20']::text[],false,'{"seq":14,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"ox","stem":"주민이 지역을 잘 알기 때문에 주민이 직접 참여하는 것이 중요해요.","answer":"O","reason_options":[{"t":"지역에 무엇이 필요한지 주민이 잘 알기 때문에","correct":true},{"t":"주민은 지역을 잘 모르기 때문에","mis":"SO4-2-u1-X20"}],"mis":"SO4-2-u1-X20","explanation":["누가 잘 알까요?","주민이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#15','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C8',2,'ox','auto','지역의 일에 참여할 때는 지역 전체에 이익이 되는 것을 생각해요.',ARRAY['SO4-2-u1-X23']::text[],false,'{"seq":15,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"ox","stem":"지역의 일에 참여할 때는 지역 전체에 이익이 되는 것을 생각해요.","answer":"O","reason_options":[{"t":"지역의 일은 주민 모두와 관계있기 때문에","correct":true},{"t":"나에게 이익이 되는 일만 하면 되기 때문에","mis":"SO4-2-u1-X23"}],"mis":"SO4-2-u1-X23","explanation":["누구의 이익일까요?","지역 전체예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#16','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C10',2,'ox','auto','신문 ⑦에서 주민들은 주민의 힘만으로 어려운 일을 공공 기관에 요청했어요.',ARRAY['SO4-2-u1-X27']::text[],false,'{"seq":16,"concept":"SO4-2-u1-C10","difficulty":2,"kind":"ox","stem":"신문 ⑦에서 주민들은 주민의 힘만으로 어려운 일을 공공 기관에 요청했어요.","answer":"O","reason_options":[{"t":"조명을 다는 일을 공공 기관에 함께 해결해 달라고 했기 때문에","correct":true},{"t":"어려운 일은 그냥 두었기 때문에","mis":"SO4-2-u1-X27"}],"mis":"SO4-2-u1-X27","explanation":["조명이 필요했어요.","요청했어요.","그래서 O예요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#17','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C2',3,'ox','auto','신문 ①에서 고친 의견은 처음 의견을 글자 그대로 다시 낸 것이에요.',ARRAY['SO4-2-u1-X06']::text[],false,'{"seq":17,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"ox","stem":"신문 ①에서 고친 의견은 처음 의견을 글자 그대로 다시 낸 것이에요.","answer":"X","reason_options":[{"t":"반대 까닭을 받아들여 「모둠마다 한 칸씩」으로 고친 의견이기 때문에","correct":true},{"t":"회의에서는 처음 의견만 낼 수 있기 때문에","mis":"SO4-2-u1-X06"}],"mis":"SO4-2-u1-X06","explanation":["두 의견을 견줘요.","글자가 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#18','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C3',3,'ox','auto','신문 ②와 신문 ③은 한 일이 달라도 의견을 모아 함께 정하고 실천했다는 점이 같아요.',ARRAY['SO4-2-u1-X11']::text[],false,'{"seq":18,"concept":"SO4-2-u1-C3","difficulty":3,"kind":"ox","stem":"신문 ②와 신문 ③은 한 일이 달라도 의견을 모아 함께 정하고 실천했다는 점이 같아요.","answer":"O","reason_options":[{"t":"두 사례 모두 구성원의 의견을 모아 정하고 실천했기 때문에","correct":true},{"t":"한 일이 다르면 민주주의 걸음도 다르기 때문에","mis":"SO4-2-u1-X11"}],"mis":"SO4-2-u1-X11","explanation":["한 일은 달라요.","걸음을 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#19','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C6',3,'ox','auto','학생 자치회와 주민 자치회는 구성원이 주인으로서 참여해 함께 문제를 해결한다는 점이 같아요.',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":19,"concept":"SO4-2-u1-C6","difficulty":3,"kind":"ox","stem":"학생 자치회와 주민 자치회는 구성원이 주인으로서 참여해 함께 문제를 해결한다는 점이 같아요.","answer":"O","reason_options":[{"t":"학교와 지역이라는 곳만 다를 뿐 참여하는 모습이 같기 때문에","correct":true},{"t":"두 모임은 서로 아무 관계가 없기 때문에","mis":"SO4-2-u1-X19"}],"mis":"SO4-2-u1-X19","explanation":["곳이 달라요.","참여는 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#20','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C9',3,'ox','auto','신문 ⑦의 모둠은 조사 방법을 정하고 조사할 때 지킬 점도 지켰어요.',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":20,"concept":"SO4-2-u1-C9","difficulty":3,"kind":"ox","stem":"신문 ⑦의 모둠은 조사 방법을 정하고 조사할 때 지킬 점도 지켰어요.","answer":"O","reason_options":[{"t":"면담을 고르고 보호자와 함께 미리 허락을 받았기 때문에","correct":true},{"t":"허락 없이 찾아갔기 때문에","mis":"SO4-2-u1-X24"}],"mis":"SO4-2-u1-X24","explanation":["면담이에요.","허락받았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#21','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C10',3,'ox','auto','신문 ⑧의 ④는 참여하기 전과 참여한 뒤를 견주어 달라진 점을 쓴 것이에요.',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":21,"concept":"SO4-2-u1-C10","difficulty":3,"kind":"ox","stem":"신문 ⑧의 ④는 참여하기 전과 참여한 뒤를 견주어 달라진 점을 쓴 것이에요.","answer":"O","reason_options":[{"t":"정류장이 깨끗해지고 관심이 높아졌다는 달라진 점이기 때문에","correct":true},{"t":"④는 필요한 일을 찾은 걸음이기 때문에","mis":"SO4-2-u1-X26"}],"mis":"SO4-2-u1-X26","explanation":["전과 후예요.","달라졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#22','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C1',3,'ox','auto','학교와 지역 모두에서 구성원이 참여해 함께 결정하면 민주주의를 실천할 수 있어요.',ARRAY['SO4-2-u1-X03']::text[],false,'{"seq":22,"concept":"SO4-2-u1-C1","difficulty":3,"kind":"ox","stem":"학교와 지역 모두에서 구성원이 참여해 함께 결정하면 민주주의를 실천할 수 있어요.","answer":"O","reason_options":[{"t":"구성원의 다양한 의견이 반영되기 때문에","correct":true},{"t":"민주주의는 나라에서만 실천하기 때문에","mis":"SO4-2-u1-X03"}],"mis":"SO4-2-u1-X03","explanation":["학교예요.","지역도요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#23','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C4',4,'mc','auto','신문 ③과 신문 ⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X12','SO4-2-u1-X15','SO4-2-u1-X26']::text[],false,'{"seq":23,"concept":"SO4-2-u1-C4","difficulty":4,"kind":"mc","stem":"신문 ③과 신문 ⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학교와 지역 모두 문제를 찾고 방법을 정해 실천한 뒤 결과를 돌아봐요","correct":true},{"t":"문제를 찾지 않고 바로 실천해요","mis":"SO4-2-u1-X12"},{"t":"실천하면 돌아보지 않아도 돼요","mis":"SO4-2-u1-X15"},{"t":"학교와 지역의 해결 차례는 정반대예요","mis":"SO4-2-u1-X26"}],"explanation":["③은 학교예요.","⑧은 지역이에요.","걸음이 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#24','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C6',4,'essay','teacher','신문 ⑤가 주민 자치의 모습인 까닭을 주민 자치의 뜻과 이어 쓰고, 주민들이 참여하지 않았다면 어땠을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u1-C6","difficulty":4,"kind":"essay","stem":"신문 ⑤가 주민 자치의 모습인 까닭을 주민 자치의 뜻과 이어 쓰고, 주민들이 참여하지 않았다면 어땠을지 쓰세요.","answer_guide":{"answer":"예: 주민들이 주민 회의에서 화단 문제를 이야기하고 함께 꽃을 심기로 했으니, 주민이 지역의 주인으로서 지역의 일에 참여해 문제를 해결한 주민 자치예요. 참여하지 않았다면 화단은 계속 메말라 동네가 보기 좋지 않았을 거예요.","scoring_points":["주민 자치의 뜻을 썼는가","신문 ⑤와 이었는가","참여하지 않았을 때를 썼는가"]},"explanation":["주민 회의를 열었어요.","함께 심어요.","참여하지 않았다면요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 주민 회의를 열었다.","주민들은 동네 공원 화단이 메말라 보기 좋지 않다는 의견을 냈다.","주민들이 함께 꽃을 심고 돌아가며 물을 주기로 했다."],"title":"신문 ⑤ — ○○동 꽃밭 가꾸기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_c#25','soc',4,2,'u1','','g4_2_soc_u1_review_c','unit_review','SO4-2-u1-C9',4,'essay','teacher','신문 ⑦의 보고서에 「더 알고 싶은 점」 칸을 채운다면 무엇을 쓸지 쓰고, 그 칸을 언제 쓰는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u1-C9","difficulty":4,"kind":"essay","stem":"신문 ⑦의 보고서에 「더 알고 싶은 점」 칸을 채운다면 무엇을 쓸지 쓰고, 그 칸을 언제 쓰는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「조명을 단 뒤 공터를 쓰는 주민이 얼마나 늘었을까?」를 쓸 거예요. 이 칸은 조사를 마친 뒤에 써요. 조사를 해 보아야 무엇을 알게 되었고 무엇이 더 궁금한지 알 수 있기 때문이에요.","scoring_points":["더 알고 싶은 점을 썼는가","조사를 마친 뒤라고 썼는가","까닭을 썼는가"]},"explanation":["궁금한 것을 써요.","언제일까요?","까닭을 써요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#1','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C1',1,'blank','auto','학생 자치회 임원 선거에서 학생들은 후보들의 (    )을 듣고 투표했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u1-C1","difficulty":1,"kind":"blank","stem":"학생 자치회 임원 선거에서 학생들은 후보들의 (    )을 듣고 투표했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공약","correct":true},{"t":"별명","mis":"SO4-2-u1-X01"},{"t":"키","mis":"SO4-2-u1-X01"},{"t":"성적","mis":"SO4-2-u1-X01"}],"explanation":["하겠다는 약속이에요.","공◯이에요.","공약이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#2','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C2',1,'mc','auto','함께 정한 해결 방안은 누가 실천하나요?',ARRAY['SO4-2-u1-X07']::text[],false,'{"seq":2,"concept":"SO4-2-u1-C2","difficulty":1,"kind":"mc","stem":"함께 정한 해결 방안은 누가 실천하나요?","options":[{"t":"구성원 모두","correct":true},{"t":"의견을 낸 사람만","mis":"SO4-2-u1-X07"},{"t":"반장만","mis":"SO4-2-u1-X07"},{"t":"찬성한 사람만","mis":"SO4-2-u1-X07"}],"explanation":["함께 정했어요.","모두의 약속이에요.","모두 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#3','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C3',1,'mc','auto','신문 ②에서 그늘막 설치에 쓰인 제도는 무엇인가요?',ARRAY['SO4-2-u1-X10']::text[],false,'{"seq":3,"concept":"SO4-2-u1-C3","difficulty":1,"kind":"mc","stem":"신문 ②에서 그늘막 설치에 쓰인 제도는 무엇인가요?","options":[{"t":"학생 참여 예산제","correct":true},{"t":"학급 문고 제도","mis":"SO4-2-u1-X10"},{"t":"방과 후 제도","mis":"SO4-2-u1-X10"},{"t":"급식 제도","mis":"SO4-2-u1-X10"}],"explanation":["학생이 제안했어요.","예산을 지원받았어요.","학생 참여 예산제예요."],"asset":{"type":"passage","lines":["학생 자치회가 학급마다 학교에 필요한 것을 제안받았다.","전교 회의에서 제안을 토의해 운동장 그늘막을 설치하기로 했다.","학생 참여 예산제로 지원받아 그늘막이 설치됐다."],"title":"신문 ② — 운동장에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#4','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C4',1,'mc','auto','신문 ③에서 해결하고 싶은 일은 무엇이었나요?',ARRAY['SO4-2-u1-X12']::text[],false,'{"seq":4,"concept":"SO4-2-u1-C4","difficulty":1,"kind":"mc","stem":"신문 ③에서 해결하고 싶은 일은 무엇이었나요?","options":[{"t":"복도 신발장이 좁아 신발이 자주 떨어지는 것","correct":true},{"t":"운동장에 그늘이 없는 것","mis":"SO4-2-u1-X12"},{"t":"게시판이 비어 있는 것","mis":"SO4-2-u1-X12"},{"t":"교실이 너무 넓은 것","mis":"SO4-2-u1-X12"}],"explanation":["㉠을 읽어요.","신발장이에요.","좁았어요."],"asset":{"type":"passage","lines":["㉠ 복도 신발장이 좁아 신발이 자주 떨어진다.","㉡ 신발장 늘리기, 칸마다 이름표 붙이기 같은 방안을 찾았다.","㉢ 신발장 모양은 설문조사로, 사용 규칙은 학급 회의로 정했다.","㉣ 새 신발장을 놓고 규칙을 알렸다.","㉤ 바꾼 뒤를 살피니 신발이 덜 떨어졌고, 아쉬운 점은 고쳐 가기로 했다."],"title":"신문 ③ — 신발장 문제를 해결했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#5','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C5',1,'mc','auto','학생 자치회 임원으로서 바람직한 모습은 무엇인가요?',ARRAY['SO4-2-u1-X17']::text[],false,'{"seq":5,"concept":"SO4-2-u1-C5","difficulty":1,"kind":"mc","stem":"학생 자치회 임원으로서 바람직한 모습은 무엇인가요?","options":[{"t":"학생 자치회 활동에 적극적으로 참여해요","correct":true},{"t":"활동은 다른 임원에게 미뤄요","mis":"SO4-2-u1-X17"},{"t":"학생들에게 묻지 않아요","mis":"SO4-2-u1-X17"},{"t":"자기 생각대로만 정해요","mis":"SO4-2-u1-X17"}],"explanation":["임원의 일이에요.","열심히 해요.","적극적으로 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#6','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C6',1,'mc','auto','지역 주민을 대표하는 기구로 주민 자치 활동을 운영하고 지원하는 것은 무엇인가요?',ARRAY['SO4-2-u1-X19']::text[],false,'{"seq":6,"concept":"SO4-2-u1-C6","difficulty":1,"kind":"mc","stem":"지역 주민을 대표하는 기구로 주민 자치 활동을 운영하고 지원하는 것은 무엇인가요?","options":[{"t":"주민 자치회","correct":true},{"t":"학생 자치회","mis":"SO4-2-u1-X19"},{"t":"학급 회의","mis":"SO4-2-u1-X19"},{"t":"교사 회의","mis":"SO4-2-u1-X19"}],"explanation":["지역 주민의 대표예요.","자치 활동을 해요.","주민 자치회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#7','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C8',1,'mc','auto','주민 참여의 방법이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u1-C8","difficulty":1,"kind":"mc","stem":"주민 참여의 방법이 아닌 것은 무엇인가요?","options":[{"t":"지역의 일을 모른 척하기","correct":true},{"t":"주민 회의에 참석하기","mis":"SO4-2-u1-X22"},{"t":"벽화 그리기","mis":"SO4-2-u1-X22"},{"t":"공청회에 참석하기","mis":"SO4-2-u1-X22"}],"explanation":["참여 방법을 떠올려요.","모른 척은 어떨까요?","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#8','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C10',1,'mc','auto','신문 ⑧에서 푸른반이 가장 먼저 한 일은 무엇인가요?',ARRAY['SO4-2-u1-X26']::text[],false,'{"seq":8,"concept":"SO4-2-u1-C10","difficulty":1,"kind":"mc","stem":"신문 ⑧에서 푸른반이 가장 먼저 한 일은 무엇인가요?","options":[{"t":"정류장 주변에 쓰레기가 많다는 일을 찾았어요","correct":true},{"t":"정류장이 깨끗해졌어요","mis":"SO4-2-u1-X26"},{"t":"잘한 점을 돌아보았어요","mis":"SO4-2-u1-X26"},{"t":"주민들과 청소했어요","mis":"SO4-2-u1-X26"}],"explanation":["①을 읽어요.","일을 찾았어요.","먼저 찾았어요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#9','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C1',2,'mc','auto','학생 자치회 임원 선거가 민주주의를 실천하는 사례인 까닭은 무엇인가요?',ARRAY['SO4-2-u1-X01']::text[],false,'{"seq":9,"concept":"SO4-2-u1-C1","difficulty":2,"kind":"mc","stem":"학생 자치회 임원 선거가 민주주의를 실천하는 사례인 까닭은 무엇인가요?","options":[{"t":"학생들의 의견을 투표로 확인해 학교의 대표를 정하기 때문이에요","correct":true},{"t":"선거를 자주 하기 때문이에요","mis":"SO4-2-u1-X01"},{"t":"기표소가 있기 때문이에요","mis":"SO4-2-u1-X01"},{"t":"공약이 많기 때문이에요","mis":"SO4-2-u1-X01"}],"explanation":["누구의 의견일까요?","학생들이에요.","대표를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
