INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#11','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C3',2,'mc','auto','학교생활에서 민주주의를 실천한 모습으로 보기 어려운 것은 무엇인가요?',ARRAY['SO4-2-u1-X09','SO4-2-u1-X10']::text[],false,'{"seq":11,"concept":"SO4-2-u1-C3","difficulty":2,"kind":"mc","stem":"학교생활에서 민주주의를 실천한 모습으로 보기 어려운 것은 무엇인가요?","options":[{"t":"친한 친구끼리만 학급의 일을 정해요","correct":true},{"t":"학생 자치회가 의견을 모아 행사를 정해요","mis":"SO4-2-u1-X09"},{"t":"학생·교사·학부모가 함께 학교 일을 의논해요","mis":"SO4-2-u1-X09"},{"t":"학생 참여 예산제로 필요한 것을 설치해요","mis":"SO4-2-u1-X10"}],"explanation":["함께 정했나요?","친한 친구끼리예요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#12','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C4',2,'mc','auto','해결 방안을 찾을 때 생각할 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u1-X13']::text[],false,'{"seq":12,"concept":"SO4-2-u1-C4","difficulty":2,"kind":"mc","stem":"해결 방안을 찾을 때 생각할 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"한 사람만 좋아하는 방안인지 생각해요","correct":true},{"t":"문제의 원인을 생각해요","mis":"SO4-2-u1-X13"},{"t":"방안의 장단점을 생각해요","mis":"SO4-2-u1-X13"},{"t":"많은 구성원이 만족할지 생각해요","mis":"SO4-2-u1-X13"}],"explanation":["생각할 점 셋이에요.","많은 사람이에요.","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#13','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C6',2,'mc','auto','일부 사람만 모여 지역의 중요한 일을 결정하면 어떻게 될 수 있나요?',ARRAY['SO4-2-u1-X18']::text[],false,'{"seq":13,"concept":"SO4-2-u1-C6","difficulty":2,"kind":"mc","stem":"일부 사람만 모여 지역의 중요한 일을 결정하면 어떻게 될 수 있나요?","options":[{"t":"많은 사람의 입장을 고려하지 못할 수 있어요","correct":true},{"t":"모든 주민의 의견이 담겨요","mis":"SO4-2-u1-X18"},{"t":"민주주의를 더 잘 실천해요","mis":"SO4-2-u1-X18"},{"t":"주민 모두가 지역의 주인이 돼요","mis":"SO4-2-u1-X18"}],"explanation":["일부만 모였어요.","다른 주민은 빠졌어요.","고려하지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#14','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C7',2,'mc','auto','신문 ⑤에서 주민들이 참여하지 않았다면 어떻게 되었을까요?',ARRAY['SO4-2-u1-X21','SO4-2-u1-X20']::text[],false,'{"seq":14,"concept":"SO4-2-u1-C7","difficulty":2,"kind":"mc","stem":"신문 ⑤에서 주민들이 참여하지 않았다면 어떻게 되었을까요?","options":[{"t":"공원 화단은 계속 메마른 채로 남았을 거예요","correct":true},{"t":"화단이 저절로 꽃밭이 되었을 거예요","mis":"SO4-2-u1-X21"},{"t":"주민 생활과 관계없어 아무 일 없었을 거예요","mis":"SO4-2-u1-X20"},{"t":"다른 지역 사람들이 꽃을 심었을 거예요","mis":"SO4-2-u1-X20"}],"explanation":["참여가 없어요.","문제가 남아요.","메마른 채예요."],"asset":{"type":"passage","lines":["○○동 주민 자치회가 주민 회의를 열었다.","주민들은 동네 공원 화단이 메말라 보기 좋지 않다는 의견을 냈다.","주민들이 함께 꽃을 심고 돌아가며 물을 주기로 했다."],"title":"신문 ⑤ — ○○동 꽃밭 가꾸기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#15','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C8',2,'mc','auto','주민 참여의 효과로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X23','SO4-2-u1-X21']::text[],false,'{"seq":15,"concept":"SO4-2-u1-C8","difficulty":2,"kind":"mc","stem":"주민 참여의 효과로 알맞은 것은 무엇인가요?","options":[{"t":"지역의 구성원으로서 만족감을 느껴요","correct":true},{"t":"지역의 일에서 멀어져요","mis":"SO4-2-u1-X23"},{"t":"나의 이익만 커져요","mis":"SO4-2-u1-X23"},{"t":"불편이 더 커져요","mis":"SO4-2-u1-X21"}],"explanation":["참여했어요.","뿌듯해요.","만족감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#16','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C9',2,'mc','auto','신문 ⑦의 모둠이 고른 조사 방법은 무엇인가요?',ARRAY['SO4-2-u1-X24']::text[],false,'{"seq":16,"concept":"SO4-2-u1-C9","difficulty":2,"kind":"mc","stem":"신문 ⑦의 모둠이 고른 조사 방법은 무엇인가요?","options":[{"t":"지역 주민 면담하기","correct":true},{"t":"인터넷으로 찾아보기","mis":"SO4-2-u1-X24"},{"t":"지역 신문 찾아보기","mis":"SO4-2-u1-X24"},{"t":"지역 게시판 찾아보기","mis":"SO4-2-u1-X24"}],"explanation":["조사 방법 칸이에요.","주민을 만났어요.","면담하기예요."],"asset":{"type":"passage","lines":["조사 목적 — 우리 동네 주민 자치 사례 알아보기","조사 방법 — 지역 주민 면담하기(보호자와 함께, 미리 허락받음)","조사 내용 — 주민들이 어두운 놀이 공터에 조명을 달아 달라고 공공 기관에 요청했다.","알게 된 점 — 주민의 힘만으로 어려운 일은 공공 기관과 함께 해결한다."],"title":"신문 ⑦ — 푸른반 모둠 조사 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#17','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C2',3,'mc','auto','신문 ①의 회의가 민주적이었던 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X05','SO4-2-u1-X07']::text[],false,'{"seq":17,"concept":"SO4-2-u1-C2","difficulty":3,"kind":"mc","stem":"신문 ①의 회의가 민주적이었던 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"반대 까닭을 듣고 의견을 고쳐 모두가 찬성하는 방안을 정하고 함께 실천했기 때문이에요","correct":true},{"t":"처음 의견을 끝까지 밀어붙였기 때문이에요","mis":"SO4-2-u1-X05"},{"t":"목소리 큰 친구가 정했기 때문이에요","mis":"SO4-2-u1-X05"},{"t":"찬성한 친구들만 꾸몄기 때문이에요","mis":"SO4-2-u1-X07"}],"explanation":["반대를 들었어요.","고쳤어요.","함께 실천했어요."],"asset":{"type":"passage","lines":["푸른반은 교실 뒤 게시판을 어떻게 꾸밀지 학급 회의를 열었다.","한 친구가 「그림 잘 그리는 친구들만 꾸미자」고 했다.","「그러면 다른 친구들의 생각이 빠진다」는 반대 까닭이 나왔다.","처음 의견을 낸 친구가 「모둠마다 한 칸씩 맡아 꾸미자」로 의견을 고쳤다.","모두가 찬성했고, 정한 대로 함께 꾸몄다."],"title":"신문 ① — 푸른반 학급 회의"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#18','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C5',3,'mc','auto','신문 ④의 임원들이 행사 계획에서 잘한 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u1-X17','SO4-2-u1-X16']::text[],false,'{"seq":18,"concept":"SO4-2-u1-C5","difficulty":3,"kind":"mc","stem":"신문 ④의 임원들이 행사 계획에서 잘한 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"학급마다 원하는 행사를 먼저 물어 학생들의 생각을 반영했어요","correct":true},{"t":"임원끼리만 정해 시간을 아꼈어요","mis":"SO4-2-u1-X17"},{"t":"행사 이름을 멋있게 지었어요","mis":"SO4-2-u1-X16"},{"t":"작년 행사를 묻지 않고 그대로 했어요","mis":"SO4-2-u1-X16"}],"explanation":["먼저 물었어요.","생각을 모았어요.","반영했어요."],"asset":{"type":"passage","lines":["9~10월 목표 — 책 읽는 학교 만들기","행사 ㉮ 책 나눔 장터 · 행사 ㉯ 독서 퀴즈 대회","임원들은 학급마다 원하는 행사를 먼저 물어 계획을 세웠다."],"title":"신문 ④ — 학생 자치회 행사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#19','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C7',3,'mc','auto','신문 ⑥의 쉼터 사례로 알 수 있는 주민 참여가 중요한 까닭은 무엇인가요?',ARRAY['SO4-2-u1-X20','SO4-2-u1-X21']::text[],false,'{"seq":19,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"신문 ⑥의 쉼터 사례로 알 수 있는 주민 참여가 중요한 까닭은 무엇인가요?","options":[{"t":"주민 생활과 관계있는 일을 주민 뜻대로 정해 원하는 방향으로 지역을 바꿀 수 있어요","correct":true},{"t":"쉼터는 주민 생활과 관계없어요","mis":"SO4-2-u1-X20"},{"t":"참여해도 쉼터는 달라지지 않아요","mis":"SO4-2-u1-X21"},{"t":"공공 기관이 알아서 다 해요","mis":"SO4-2-u1-X20"}],"explanation":["주민이 쓰는 쉼터예요.","주민이 골랐어요.","원하는 대로 바뀌어요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#20','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C8',3,'mc','auto','신문 ⑥에서 쉼터에 그늘 의자와 책장을 놓기로 한 까닭은 무엇인가요?',ARRAY['SO4-2-u1-X22','SO4-2-u1-X23']::text[],false,'{"seq":20,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"신문 ⑥에서 쉼터에 그늘 의자와 책장을 놓기로 한 까닭은 무엇인가요?","options":[{"t":"가장 많은 주민이 그것을 골랐기 때문이에요","correct":true},{"t":"공공 기관이 혼자 골랐기 때문이에요","mis":"SO4-2-u1-X22"},{"t":"한 주민이 정했기 때문이에요","mis":"SO4-2-u1-X23"},{"t":"투표 없이 정했기 때문이에요","mis":"SO4-2-u1-X22"}],"explanation":["투표를 했어요.","많은 주민이 골랐어요.","그래서 정했어요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#21','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C7',3,'mc','auto','신문 ⑧처럼 주민 참여가 활발해지면 지역은 어떻게 달라지나요?',ARRAY['SO4-2-u1-X21','SO4-2-u1-X20','SO4-2-u1-X27']::text[],false,'{"seq":21,"concept":"SO4-2-u1-C7","difficulty":3,"kind":"mc","stem":"신문 ⑧처럼 주민 참여가 활발해지면 지역은 어떻게 달라지나요?","options":[{"t":"지역의 불편한 문제를 주민들이 직접 해결하고 더 살기 좋아져요","correct":true},{"t":"지역의 문제를 해결하기 어려워져요","mis":"SO4-2-u1-X21"},{"t":"주민 생활과 관계없어요","mis":"SO4-2-u1-X20"},{"t":"공공 기관이 할 일이 사라져요","mis":"SO4-2-u1-X27"}],"explanation":["참여했어요.","정류장이 깨끗해졌어요.","살기 좋아져요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#22','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C8',3,'mc','auto','신문 ⑥과 신문 ⑧에서 쓴 주민 참여 방법을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-2-u1-X22']::text[],false,'{"seq":22,"concept":"SO4-2-u1-C8","difficulty":3,"kind":"mc","stem":"신문 ⑥과 신문 ⑧에서 쓴 주민 참여 방법을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"⑥ — 주민 투표 · ⑧ — 캠페인과 누리집 게시판","correct":true},{"t":"⑥ — 캠페인 · ⑧ — 주민 투표","mis":"SO4-2-u1-X22"},{"t":"⑥ — 벽화 그리기 · ⑧ — 공청회","mis":"SO4-2-u1-X22"},{"t":"두 신문 모두 같은 방법이에요","mis":"SO4-2-u1-X22"}],"explanation":["⑥은 투표예요.","⑧은 캠페인이에요.","게시판도 있어요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#23','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C1',4,'mc','auto','「민주주의와 자치」 단원을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u1-X03','SO4-2-u1-X18','SO4-2-u1-X19']::text[],false,'{"seq":23,"concept":"SO4-2-u1-C1","difficulty":4,"kind":"mc","stem":"「민주주의와 자치」 단원을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"민주주의는 다양한 의견을 반영해 함께 결정하는 것이고, 학교에서는 학생 자치로 지역에서는 주민 자치로 실천해요","correct":true},{"t":"민주주의는 나라에서만 실천해요","mis":"SO4-2-u1-X03"},{"t":"학교와 지역의 일은 몇몇이 대신 정하면 돼요","mis":"SO4-2-u1-X18"},{"t":"주민 자치와 학생 자치는 관계가 없어요","mis":"SO4-2-u1-X19"}],"explanation":["민주주의의 뜻이에요.","학교와 지역이에요.","자치로 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#24','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C8',4,'essay','teacher','신문 ⑥의 주민 투표가 좋은 점을 두 가지 쓰고, 주민 투표에 참여할 때 지녀야 할 태도를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u1-C8","difficulty":4,"kind":"essay","stem":"신문 ⑥의 주민 투표가 좋은 점을 두 가지 쓰고, 주민 투표에 참여할 때 지녀야 할 태도를 쓰세요.","answer_guide":{"answer":"예: 주민 투표로 정하면 주민들의 의견을 반영할 수 있고, 지역의 일을 민주적으로 해결할 수 있어요. 투표할 때는 나의 이익만 생각하지 말고 지역 전체에 이익이 되는 것이 무엇인지 생각해야 해요.","scoring_points":["좋은 점 두 가지를 썼는가","지역 전체의 이익을 생각하는 태도를 썼는가","투표와 이어졌는가"]},"explanation":["좋은 점을 찾아요.","두 가지예요.","태도를 써요."],"asset":{"type":"passage","lines":["○○동은 동네 쉼터에 무엇을 놓을지 주민 투표를 했다.","주민들은 곳곳의 투표판이나 사회 관계망 서비스로 투표했다.","가장 많은 주민이 고른 그늘 의자와 책장을 놓기로 했다."],"title":"신문 ⑥ — 쉼터는 주민 투표로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u1_review_d#25','soc',4,2,'u1','','g4_2_soc_u1_review_d','unit_review','SO4-2-u1-C10',4,'essay','teacher','신문 ⑧처럼 우리 반이 주민 자치에 참여한다면 필요한 일을 하나 찾고, 참여 방법과 공공 기관에 도움을 청할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u1-C10","difficulty":4,"kind":"essay","stem":"신문 ⑧처럼 우리 반이 주민 자치에 참여한다면 필요한 일을 하나 찾고, 참여 방법과 공공 기관에 도움을 청할 일을 쓰세요.","answer_guide":{"answer":"예: 학교 앞 횡단보도가 위험한 일을 찾았어요. 친구들과 안전 캠페인을 벌이고 주민들과 함께 등하교 안전 지킴이 활동을 할 거예요. 신호등이나 안전 표지판처럼 우리 힘만으로 어려운 일은 공공 기관 누리집 게시판에 의견을 올려 도움을 청할 거예요.","scoring_points":["필요한 일을 찾았는가","참여 방법을 썼는가","공공 기관에 청할 일을 썼는가"]},"explanation":["일을 찾아요.","방법을 써요.","도움을 청해요."],"asset":{"type":"passage","lines":["① 버스 정류장 주변에 쓰레기가 많다는 일을 찾았다.","② 캠페인 문구를 만들고 공공 기관 누리집 게시판에 의견을 올리기로 했다.","③ 주민들과 함께 청소하고 캠페인을 벌였다.","④ 정류장이 깨끗해지고 주민들의 관심이 높아졌다.","⑤ 잘한 점과 아쉬운 점을 돌아보았다."],"title":"신문 ⑧ — 푸른반 주민 자치 참여"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
